#include <stdlib.h>
#include <string.h>

char* append_slash(const char* input, size_t limit) {
    // Check if the input string exceeds the size limit
    if (strlen(input) >= limit) {
        return NULL;
    }

    // Allocate memory for the new string including space for the null terminator and the slash
    char* result = (char*)malloc((limit + 2) * sizeof(char));
    if (result == NULL) {
        return NULL; // Allocation failed
    }

    // Copy the input string to the new memory location
    strcpy(result, input);

    // Append a slash at the end of the copied string
    result[strlen(input)] = '/';
    result[limit + 1] = '\0'; // Ensure null termination

    return result;
}
