#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void process_line(char *line) {
    char *token;
    char *last_field = NULL;
    double sum = 0.0, average = 0.0;
    int count = 0;

    token = strtok(line, ",\n");
    while (token != NULL) {
        if (count == 0) {
            printf("%s", token);
        } else {
            sum += atof(token);
            last_field = token;
        }
        count++;
        token = strtok(NULL, ",\n");
    }

    if (count > 1 && last_field != NULL) {
        average = sum / (count - 1);
        printf(",%.2f\n", average);
    } else {
        printf("\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
