        perror("Error opening file");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        process_line(line);
    }

    free(line);
    fclose(file);
    return EXIT_SUCCESS;
}
