#include <stdlib.h>

// Define the structure for the binary search tree node
typedef struct BSTNode {
    int offset;
    struct BSTNode *left;
    struct BSTNode *right;
} BSTNode;

// Function to create a new BST node
BSTNode* createNode(int offset) {
    BSTNode* newNode = (BSTNode*)malloc(sizeof(BSTNode));
    if (newNode == NULL) {
        return NULL; // Allocation failed
    }
    newNode->offset = offset;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert an offset into the BST
BSTNode* insertOffset(BSTNode* root, int offset) {
    if (root == NULL) {
        return createNode(offset); // If the tree is empty, create a new node
    }
    if (offset < root->offset) {
        root->left = insertOffset(root->left, offset); // Insert into the left subtree
    } else if (offset > root->offset) {
        root->right = insertOffset(root->right, offset); // Insert into the right subtree
    }
    // If offset is already present, do nothing
    return root;
}

// Function to search for an offset in the BST
BSTNode* searchOffset(BSTNode* root, int offset) {
    if (root == NULL || root->offset == offset) {
        return root; // Return the node if found or NULL if not found
    }
    if (offset < root->offset) {
        return searchOffset(root->left, offset); // Search in the left subtree
    } else {
        return searchOffset(root->right, offset); // Search in the right subtree
    }
}
