#include <tiffio.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TIFFInfo;

TIFFInfo parseTIFF(const char *filename) {
    TIFFInfo info = {0};
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        return info;
    }

    uint16_t samplesPerPixel = 0;
    uint16_t *bitsPerSample = NULL;
    uint16_t extraSamples = 0;
    uint16_t *sampleFormat = NULL;

    if (!TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
        fprintf(stderr, "Error reading samples per pixel\n");
        TIFFClose(tiff);
        return info;
    }

    bitsPerSample = (uint16_t *)malloc(samplesPerPixel * sizeof(uint16_t));
    if (!bitsPerSample) {
        fprintf(stderr, "Memory allocation failed\n");
        TIFFClose(tiff);
        return info;
    }

    sampleFormat = (uint16_t *)malloc(samplesPerPixel * sizeof(uint16_t));
    if (!sampleFormat) {
        fprintf(stderr, "Memory allocation failed\n");
        free(bitsPerSample);
        TIFFClose(tiff);
        return info;
    }

    if (!TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, bitsPerSample)) {
        fprintf(stderr, "Error reading bits per sample\n");
        free(bitsPerSample);
        free(sampleFormat);
        TIFFClose(tiff);
        return info;
    }

    if (!TIFFGetField(tiff, TIFFTAG_SAMPLEFORMAT, sampleFormat)) {
        fprintf(stderr, "Error reading sample format\n");
        free(bitsPerSample);
        free(sampleFormat);
        TIFFClose(tiff);
        return info;
    }

    if (!TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples)) {
        extraSamples = 0;
    }

    // Validate bits per sample and handle unsupported cases
    for (uint16_t i = 0; i < samplesPerPixel; ++i) {
        if (bitsPerSample[i] != 1 && bitsPerSample[i] != 2 && bitsPerSample[i] != 4 && bitsPerSample[i] != 8 && bitsPerSample[i] != 16) {
            fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample[i]);
            free(bitsPerSample);
            free(sampleFormat);
            TIFFClose(tiff);
            return info;
        }
    }

    info.bitsPerSample = bitsPerSample[0]; // For simplicity, assuming all samples have the same bit depth
    info.samplesPerPixel = samplesPerPixel;
    info.extraSamples = extraSamples;

    free(bitsPerSample);
    free(sampleFormat);
    TIFFClose(tiff);

    return info;
}
