#define BUFFER_SIZE 1024
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 8080
#define MODE_INVALID -1

int receive_file(const char *filename, int mode) {
    if (mode <= 0 || mode > 0666) {
        fprintf(stderr, "Invalid file mode\n");
        return -1;
    }

    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    FILE *file;
    ssize_t bytes_received;
    size_t total_bytes = 0;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr);

    // Prepare the filename message
    char msg[BUFFER_SIZE];
    snprintf(msg, BUFFER_SIZE, "%s %d", filename, mode);

    // Send the filename and mode to the server
    if (sendto(sockfd, msg, strlen(msg), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Sendto failed");
        close(sockfd);
        return -1;
    }

    // Open the file for writing with the given mode
    if ((file = fopen(filename, "wb")) == NULL) {
        perror("File opening failed");
        close(sockfd);
        return -1;
    }

    // Receive and write data to the file
    while ((bytes_received = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, NULL, NULL)) > 0) {
        if (fwrite(buffer, 1, bytes_received, file) != bytes_received) {
            perror("File writing failed");
            fclose(file);
            close(sockfd);
            return -1;
        }
        total_bytes += bytes_received;
    }

    if (bytes_received < 0) {
        perror("Recvfrom failed");
        fclose(file);
        close(sockfd);
        return -1;
    }

    // Clean up
    fclose(file);
    close(sockfd);
    return total_bytes;
}
