typedef struct {
    char **strings;
    int count;
} Result;

Result* process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Result *result = (Result *)malloc(sizeof(Result));
    result->strings = malloc(100 * sizeof(char *)); // Initial allocation for strings
    result->count = 0;
