        if (buffer[0] == '!') {
            result->count++;
            result->strings = realloc(result->strings, (result->count + 1) * sizeof(char *));
            result->strings[result->count - 1] = strdup(buffer);
        } else if (buffer[0] == '\'') {
            int len = strlen(buffer);
            if (len > 1 && buffer[len - 1] == '\n') {
                buffer[len - 1] = '\0'; // Remove newline character
            }
            result->count++;
            result->strings = realloc(result->strings, (result->count + 1) * sizeof(char *));
            result->strings[result->count - 1] = strdup(buffer + 1);
        }
    }

    fclose(file);
    return result;
}
