void print_usage() {
    printf("Usage: ./program [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage       Display the manual page.\n");
    printf("  -cs            Print the number of lines in the file.\n");
    printf("  -o output_file  Specify an output file.\n");
}

int main(int argc, char *argv[]) {
    int cs = 0;
    char *output_file = NULL;
    int opt;

    while ((opt = getopt(argc, argv, "o:cs")) != -1) {
        switch (opt) {
            case 'o':
                output_file = optarg;
                break;
            case 'cs':
                cs = 1;
                break;
            default:
                print_usage();
                return 1;
        }
    }

    if (optind >= argc) {
        print_usage();
        return 1;
    }

    char *input_file = argv[optind];

    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    int line_count = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }

    fclose(file);

    if (cs) {
        printf("Number of lines: %d\n", line_count);
    }

    return 0;
}
