#include <tiffio.h>
#include <stdlib.h>

int compressAndReverseTIFF(TIFF *in, TIFF *out) {
    uint32 width, height;
    uint16 samplesPerPixel, bitsPerSample;
    uint32 row;
    tsize_t scanlineSize;
    void *buf = NULL;
    uint8 *data;

    // Get image dimensions and sample information
    TIFFGetField(in, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(in, TIFFTAG_IMAGELENGTH, &height);
    TIFFGetField(in, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
    TIFFGetField(in, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);

    // Calculate the size of each scanline in bytes
    scanlineSize = TIFFScanlineSize(in);

    // Allocate memory for the buffer
    buf = _TIFFmalloc(scanlineSize);
    if (buf == NULL) {
        TIFFError(NULL, "Failed to allocate memory");
        return 0;
    }

    // Iterate over each scanline and reverse the pixel order
    for (row = 0; row < height; row++) {
        uint32_t offset = row * scanlineSize;
        TIFFReadScanline(in, buf, row, 0);
        data = (uint8 *)buf + offset;

        // Reverse the pixel order in each scanline
        for (uint32 col = 0; col < width * samplesPerPixel * bitsPerSample / 8; col += samplesPerPixel * bitsPerSample / 8) {
            uint32_t temp[samplesPerPixel];
            for (uint16 spp = 0; spp < samplesPerPixel; spp++) {
                temp[spp] = data[col + spp * (bitsPerSample / 8)];
            }
            for (uint16 spp = 0; spp < samplesPerPixel; spp++) {
                data[col + spp * (bitsPerSample / 8)] = temp[samplesPerPixel - 1 - spp];
            }
        }

        // Write the compressed scanline to the new TIFF file
        if (TIFFWriteScanline(out, buf, row, 0) < 0) {
            TIFFError(NULL, "Failed to write scanline %lu", (unsigned long)row);
            _TIFFfree(buf);
            return 0;
        }
    }

    // Free the allocated memory for the buffer
    _TIFFfree(buf);
    return 1;
}
