#include <stdio.h>
#include <stdlib.h>

void parse_ip_packet(const u_char *packet, int length) {
    if (length < 20) { // IP header minimum length is 20 bytes
        printf("Packet too short to be an IP packet.\n");
        return;
    }

    const u_char *ip_header = packet;
    int ip_header_len = ip_header[0] & 0x0F; // Extract header length in words (4 bytes)
    if (length < 20 + (ip_header_len * 4)) { // Ensure there's enough data for the entire packet
        printf("Packet is truncated or malformed.\n");
        return;
    }

    const u_char *options = packet + 20 + (ip_header_len * 4); // Start of options after IP header
    int remaining_length = length - (20 + (ip_header_len * 4)); // Remaining data for options and payload

    while (remaining_length > 0) {
        if (options[0] == 0) { // End of options
            break;
        }

        int option_type = options[0];
        int option_len = options[1];

        if (option_len < 2 || remaining_length < option_len) {
            printf("Option type %d is malformed or truncated.\n", option_type);
            break;
        }

        printf("Option type: %d, Length: %d\n", option_type, option_len);

        // Print the option data (excluding the first two bytes which are the type and length)
        for (int i = 0; i < option_len - 2; i++) {
            printf("%02x ", options[2 + i]);
        }
        printf("\n");

        options += option_len;
        remaining_length -= option_len;
    }
