typedef struct {
    char hostname[256];
    int data_port;
    int health_port;
} DownstreamHostStruct;

typedef struct {
    int num_downstreams;
    DownstreamHostStruct *downstreams;
} HostListResponse;

int parse_host_and_ports(const char* input, HostListResponse* response) {
    // 使用正则表达式验证和解析主机名和端口号
    const char* pattern = "^([^:]+):(\\d+):(\\d+)$";
    regex_t regex;
    int reti;

    reti = regcomp(&regex, pattern, REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Could not compile regex\n");
        return -1;
    }

    // 初始化响应结构
    response->num_downstreams = 0;
    response->downstreams = NULL;

    char *line = strdup(input);
    if (!line) {
        regfree(&regex);
        return -1;
    }

    // 逐行解析输入字符串
    char *token = strtok(line, ",");
    while (token != NULL) {
        regmatch_t matches[4];
        reti = regexec(&regex, token, 4, matches, 0);
        if (!reti) {
            // 提取匹配的主机名、数据端口和健康端口
            char *hostname = strndup(token + matches[1].rm_so, matches[1].rm_eo - matches[1].rm_so);
            int data_port = atoi(token + matches[2].rm_so);
            int health_port = atoi(token + matches[3].rm_so);

            // 增加下游主机数量
            response->num_downstreams++;

            // 重新分配下游主机数组以容纳新元素
            DownstreamHostStruct *new_downstreams = realloc(response->downstreams, response->num_downstreams * sizeof(DownstreamHostStruct));
            if (!new_downstreams) {
                free(hostname);
                regfree(&regex);
                free(line);
                return -1;
            }
            response->downstreams = new_downstreams;

            // 填充新元素
            strncpy(response->downstreams[response->num_downstreams - 1].hostname, hostname, sizeof(response->downstreams[response->num_downstreams - 1].hostname));
            response->downstreams[response->num_downstreams - 1].data_port = data_port;
            response->downstreams[response->num_downstreams - 1].health_port = health_port;

            free(hostname);
        } else {
            regfree(&regex);
            free(line);
            return -1;
        }

        token = strtok(NULL, ",");
    }

    // 释放资源
    regfree(&regex);
    free(line);

    return 0;
}

int main() {
    const char* input = "example.com:8080:8443,localhost:9000:9001";
