void count_characters(char *sentence, int *vowel_count, int *uppercase_count, int *lowercase_count) {
    while (*sentence != '\0') {
        char ch = tolower(*sentence);
        if (ch >= 'a' && ch <= 'z') {
            (*lowercase_count)++;
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
