    [rows, cols] = size(matrix);

    if rows ~= cols || ~issparse(matrix)
        error('Matrix must be square and sparse.');
    end

    % Check if the permutation is valid
    if length(permutation) ~= rows || any(sort(permutation) ~= 1:rows)
        error('Permutation vector is not valid.');
    end

    % Perform fill-reducing ordering using the given permutation
    ordering = matrix(:, permutation);
end
