int uart_init() {
    int fd;
    struct termios options;

    // Open the UART device in non-blocking mode
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return -1;
    }

    // Get the current options for the port
    tcgetattr(fd, &options);

    // Set the baud rates to 9600
    cfsetispeed(&options, BAUDE_RATE);
    cfsetospeed(&options, BAUDE_RATE);

    // Enable the receiver and set local mode (no modem control lines)
    options.c_cflag |= (CLOCAL | CREAD);

    // Set 8 data bits, no parity, 1 stop bit
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    // Set the new options for the port
    tcsetattr(fd, TCSANOW, &options);

    return fd;
}

void uart_tx_wait(int fd) {
    while (1) {
        int bytesAvailable = 0;
        ioctl(fd, FIONREAD, &bytesAvailable);
        if (bytesAvailable > 0) {
            break;
        }
        usleep(100000); // Sleep for 100 ms
    }
}

