#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *value;
} TIGValue;

TIGValue* concatenateStrings(const char *str1, const char *str2, int index) {
    if (str1 == NULL || str2 == NULL || index < 0) {
        return NULL;
    }

    size_t len1 = strlen(str1);
    if (index > len1) {
        return NULL;
    }

    TIGValue *result = (TIGValue *)malloc(sizeof(TIGValue));
    if (result == NULL) {
        return NULL;
    }

    result->value = (char *)malloc(len1 + strlen(str2) + 1);
    if (result->value == NULL) {
        free(result);
        return NULL;
    }

    size_t i;
    for (i = 0; i < len1 && i < index; ++i) {
        result->value[i] = str1[i];
    }

    for (size_t j = 0; j < strlen(str2); ++j, ++i) {
        result->value[i] = str2[j];
    }

    for (; i < len1 + strlen(str2); ++i) {
        result->value[i] = str1[i - strlen(str2)];
    }

    result->value[len1 + strlen(str2)] = '\0';

    return result;
}
