#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    pthread_t* threads;
    int num_threads;
    pthread_mutex_t mutex;
} Scheduler;

Scheduler* init_scheduler(int num_threads, void* (*start_routine)(void*), void* arg) {
    if (num_threads <= 0) {
        return NULL;
    }

    Scheduler* scheduler = (Scheduler*)malloc(sizeof(Scheduler));
    if (!scheduler) {
        return NULL;
    }

    scheduler->num_threads = num_threads;
    scheduler->threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
