        free(scheduler->threads);
        free(scheduler);
        return NULL;
    }

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&scheduler->threads[i], NULL, start_routine, arg) != 0) {
            pthread_mutex_destroy(&scheduler->mutex);
            free(scheduler->threads);
            free(scheduler);
            return NULL;
        }
    }

    return scheduler;
}
