#include <string.h>

// Global state variable to indicate an acknowledgement is awaited
int awaiting_acknowledgement = 1;

void transmit_packet(const char *packet, size_t packet_length) {
    // Calculate the checksum of the packet (simple sum for demonstration purposes)
    uint8_t checksum = 0;
    for (size_t i = 0; i < packet_length; ++i) {
        checksum += packet[i];
    }

    // Create a buffer to hold the entire packet including the checksum
    char *buffer = (char *)malloc(packet_length + 1);
    if (!buffer) {
