    for (size_t i = 0; i < packet_length + 1; ++i) {
        printf("%02X ", (unsigned char)buffer[i]);
    }
    printf("\n");

    // Free the allocated buffer
    free(buffer);

    // Update global state to indicate an acknowledgement is awaited
    awaiting_acknowledgement = 1;
}
