struct Server {
    char *hostname;
    uint16_t port;
};

struct ServerList {
    struct Server *servers;
    size_t count;
};

struct Server* parseServer(const char *serverEntry) {
    struct Server *server = malloc(sizeof(struct Server));
    if (server == NULL) {
        return NULL;
    }

    const char *colon = strchr(serverEntry, ':');
    if (colon == NULL || colon[1] == '\0') {
        free(server);
        return NULL;
    }

    server->hostname = malloc(colon - serverEntry + 1);
    if (server->hostname == NULL) {
        free(server);
        return NULL;
    }

    strncpy(server->hostname, serverEntry, colon - serverEntry);
    server->hostname[colon - serverEntry] = '\0';

    char *endptr;
    unsigned long portValue = strtoul(colon + 1, &endptr, 10);
    if (*endptr != '\0' || portValue > UINT16_MAX) {
        free(server->hostname);
        free(server);
        return NULL;
    }

    server->port = (uint16_t)portValue;
    return server;
}

struct ServerList* parseServerList(const char *serversString) {
    struct ServerList *list = malloc(sizeof(struct ServerList));
    if (list == NULL) {
        return NULL;
    }

    list->count = 0;
    list->servers = NULL;

    const char *start = serversString;
    while (*start != '\0') {
        const char *end = strchr(start, ',');
        if (end == NULL) {
            end = start + strlen(start);
        }

        size_t length = end - start;
        if (length > 0) {
            struct Server *server = parseServer(start);
            if (server != NULL) {
                list->servers = realloc(list->servers, (list->count + 1) * sizeof(struct Server));
                if (list->servers == NULL) {
                    free(server->hostname);
                    free(server);
                    free(list);
                    return NULL;
                }
                list->servers[list->count] = *server;
                list->count++;
                free(server);
            } else {
                // If parsing fails, clean up previously allocated memory
                for (size_t i = 0; i < list->count; i++) {
                    free(list->servers[i].hostname);
                }
                free(list->servers);
                free(list);
                return NULL;
            }
        }

        start = end + 1;
    }

    return list;
}
