#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define STACK_SIZE 1024

typedef struct {
    char **lines;
    int size;
} Stack;

void initialize_stack(Stack *stack) {
    stack->size = 0;
    stack->lines = (char **)malloc(STACK_SIZE * sizeof(char *));
    if (stack->lines == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void push_line(Stack *stack, const char *line) {
    if (stack->size >= STACK_SIZE) {
        fprintf(stderr, "Stack overflow\n");
        return;
    }
    stack->lines[stack->size] = strdup(line);
    if (stack->lines[stack->size] == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    stack->size++;
}

void process_input(const char *input) {
    Stack stack;
    initialize_stack(&stack);

    if (input == NULL || strlen(input) == 0) {
        printf("Input is empty\n");
        free_stack(&stack);
        return;
    }

    push_line(&stack, input);
    push_line(&stack, ""); // Append newline character

    for (int i = 0; i < stack.size; i++) {
        printf("Line %d: %s\n", i + 1, stack.lines[i]);
        free(stack.lines[i]);
    }

    free(stack.lines);
}

void free_stack(Stack *stack) {
    for (int i = 0; i < stack->size; i++) {
        free(stack->lines[i]);
    }
    free(stack->lines);
}

int main() {
    const char *input = "function_call arg1 arg2";
    process_input(input);
    return 0;
}
