#include <stdlib.h>

typedef struct {
    int *fds;
    size_t capacity;
    size_t size;
} Pollset;

Pollset* create_pollset(size_t initial_capacity) {
    Pollset *pollset = (Pollset *)malloc(sizeof(Pollset));
    if (!pollset) return NULL;

    pollset->fds = (int *)calloc(initial_capacity, sizeof(int));
    if (!pollset->fds) {
        free(pollset);
        return NULL;
    }

    pollset->capacity = initial_capacity;
    pollset->size = 0;
    return pollset;
}

int add_to_pollset(Pollset *pollset, int fd) {
    if (pollset->size >= pollset->capacity) {
        size_t new_capacity = pollset->capacity * 2;
        int *new_fds = (int *)realloc(pollset->fds, new_capacity * sizeof(int));
        if (!new_fds) return -1; // Allocation failed

        pollset->fds = new_fds;
        pollset->capacity = new_capacity;
    }

    pollset->fds[pollset->size++] = fd;
    return 0; // Success
}

void free_pollset(Pollset *pollset) {
    if (pollset) {
        free(pollset->fds);
        free(pollset);
    }
}
