    if (!inet_ntop(client_addr.ss_family, ip_ptr, ip_str, sizeof(ip_str))) {
        perror("inet_ntop");
        close(client_fd);
        return;
    }

    printf("Client IP: %s\n", ip_str);

    // Clean up
    close(client_fd);
}
