unsigned char* encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, const EVP_CIPHER *cipher) {
    // Create and initialize the context for the cipher operation
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL;  // Memory allocation failed
    }

    // Initialize encryption operation. Note key and IV must be set before calling this function.
