        EVP_CIPHER_CTX_free(ctx);
        return NULL;  // Error finalizing the encryption process
    }
    ciphertext_len += len;

    // Clean up and return the encrypted data
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext;
}
