char* read_line_from_stdin() {
    fd_set readfds;
    struct timeval timeout;
    int ret, maxfd = 0;
    char buffer[128];
    size_t bufsize = sizeof(buffer);
    char *result = malloc(bufsize);
    if (!result) {
        return NULL; // Handle memory allocation failure
    }
    result[0] = '\0';

    FD_ZERO(&readfds);
    FD_SET(STDIN_FILENO, &readfds);
    maxfd = STDIN_FILENO + 1;

