    timeout.tv_usec = 0;

    ret = select(maxfd, &readfds, NULL, NULL, &timeout);
    if (ret == -1) {
        perror("select");
        free(result);
        return NULL; // Handle error in select
    } else if (ret == 0) {
        fprintf(stderr, "Timeout occurred! No data after 10 seconds.\n");
        free(result);
        return NULL; // Timeout occurred
    }

    if (FD_ISSET(STDIN_FILENO, &readfds)) {
        size_t pos = 0;
        while ((ret = read(STDIN_FILENO, buffer, sizeof(buffer) - 1)) > 0) {
            if (pos + ret >= bufsize - 1) {
                // Resize the result buffer to accommodate more data
                bufsize *= 2;
