#include <stdlib.h>
#include <stdio.h>

typedef struct knode {
    int data;
    struct knode *next;
} knode_t;

typedef struct record {
    int value;
    knode_t *head;
} record_t;

record_t* create_record(int size, int order) {
    // Calculate the maximum number of nodes based on input size and order
    int max_nodes = size * order;

    // Allocate memory for the root record
    record_t *root = (record_t *)malloc(sizeof(record_t));
    if (root == NULL) {
        perror("Failed to allocate memory for root record");
        return NULL;
    }

    // Initialize the root record
    root->value = 0;
    root->head = NULL;

    // Allocate memory for the nodes in the queue
    knode_t *current_node = (knode_t *)malloc(sizeof(knode_t));
    if (current_node == NULL) {
        perror("Failed to allocate memory for initial node");
        free(root);
        return NULL;
    }

    // Set up the root node
    current_node->data = 0;
    current_node->next = NULL;
    root->head = current_node;

    // Allocate memory for additional nodes if needed
    knode_t *prev_node = current_node;
    for (int i = 1; i < max_nodes; ++i) {
        current_node = (knode_t *)malloc(sizeof(knode_t));
        if (current_node == NULL) {
            perror("Failed to allocate memory for additional nodes");
            // Clean up previously allocated nodes
            knode_t *temp;
            while (prev_node != NULL) {
                temp = prev_node->next;
                free(prev_node);
                prev_node = temp;
            }
            free(root);
            return NULL;
        }
        current_node->data = i;
        current_node->next = NULL;
        prev_node->next = current_node;
        prev_node = current_node;
    }

    return root;
}
