    FILE *file;
} LineBuffer;

void initLineBuffer(LineBuffer *lb, FILE *fp) {
    lb->pos = 0;
    lb->file = fp;
    memset(lb->buffer, 0, BUFFER_SIZE);
}

char* getNextLine(LineBuffer *lb) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    if (lb->pos < BUFFER_SIZE && lb->buffer[lb->pos] != '\0') {
        // Read from the buffer first
        for (len = 0; lb->pos < BUFFER_SIZE && lb->buffer[lb->pos] != '\n' && lb->buffer[lb->pos] != '\0'; len++) {
            line = realloc(line, len + 1);
            if (!line) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }
            line[len] = lb->buffer[lb->pos++];
        }
        if (lb->pos < BUFFER_SIZE && lb->buffer[lb->pos] == '\n') {
            len++;
