            if (!line) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }
            line[len - 1] = lb->buffer[lb->pos++];
            line[len] = '\0';
        } else if (lb->pos < BUFFER_SIZE && lb->buffer[lb->pos] == '\0') {
            // End of buffer, read more from file
            lb->pos++;
            return NULL;
        }
