#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Card {
    int type;
    char name[20];
} Card;

typedef struct Node {
    Card card;
    struct Node* next;
} Node;

Node* create_node(Card card) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    new_node->card = card;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

unsigned int hash(const char* str) {
    unsigned int hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

Node* shuffle_cards(Card cards[], size_t count) {
    srand((unsigned int)time(NULL)); // Seed the random number generator with a dynamic value

    for (size_t i = count - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        Card temp = cards[i];
        cards[i] = cards[j];
        cards[j] = temp;
    }

    Node* head = NULL;
    Node* tail = NULL;

    for (size_t i = 0; i < count; ++i) {
        Card card = cards[i];
        Node* new_node = create_node(card);
        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}
