#include <omp.h>
#include <stdlib.h>

int** create_matrix(int* arr, int rows, int cols) {
    // Allocate memory for the matrix
    int** matrix = (int**)malloc(rows * sizeof(int*));
    if (!matrix) {
        return NULL; // Memory allocation failed
    }

    // Allocate memory for each row
    for (int i = 0; i < rows; i++) {
        matrix[i] = (int*)malloc(cols * sizeof(int));
        if (!matrix[i]) {
            // Free previously allocated memory before returning NULL
            for (int j = 0; j < i; j++) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL; // Memory allocation failed
        }
    }

    // Copy the elements from the input array to the matrix
    int index = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            matrix[i][j] = arr[index++];
        }
    }

    return matrix;
}

void free_matrix(int** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int* distribute_blocks(int* arr, int total_elements, int num_threads) {
    // Allocate memory for the distributed blocks
    int* distributed = (int*)malloc(total_elements * sizeof(int));
    if (!distributed) {
        return NULL; // Memory allocation failed
    }

    // Distribute the elements among threads
    #pragma omp parallel num_threads(num_threads)
    {
        int thread_id = omp_get_thread_num();
        int block_size = total_elements / num_threads;
        int start = thread_id * block_size;
        int end = (thread_id == num_threads - 1) ? total_elements : (thread_id + 1) * block_size;

        for (int i = start; i < end; i++) {
            distributed[i] = arr[i];
        }
    }

    return distributed;
}
