        return NULL; // Return null if memory allocation fails
    }

    // Convert the binary hash to a hexadecimal string
    for (int i = 0; i < MD4_DIGEST_LENGTH; ++i) {
        sprintf(&output[i * 2], "%02x", digest[i]);
    }

    return output;
}
