#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[32];
    int status;
    int priority;
    unsigned int stack_high_water_mark;
} TaskStatus;

void print_task_info(TaskStatus *tasks, size_t num_tasks, char *buffer, size_t buffer_size) {
    if (buffer == NULL || tasks == NULL || buffer_size < 1) {
        return;
    }

    size_t offset = 0;
    for (size_t i = 0; i < num_tasks; ++i) {
        TaskStatus *task = &tasks[i];
        int len = snprintf(buffer + offset, buffer_size - offset, "Task %zu: Name=%s, Status=%d, Priority=%d, Stack High Water Mark=%u\n",
                           i, task->name, task->status, task->priority, task->stack_high_water_mark);
        if (len < 0 || len >= buffer_size - offset) {
            break; // Buffer overflow
        }
        offset += len;
    }
}

int main() {
    TaskStatus tasks[] = {
        {"Task1", 1, 5, 1024},
        {"Task2", 0, 3, 2048},
        {"Task3", 1, 7, 512}
    };
    size_t num_tasks = sizeof(tasks) / sizeof(tasks[0]);
    char buffer[512]; // Adjust buffer size as needed

    print_task_info(tasks, num_tasks, buffer, sizeof(buffer));
    printf("%s", buffer);

    return 0;
}
