PyObject* axis_slice(PyArrayObject *input, int axis, npy_intp *out_shape) {
    // Check if the input array is valid
    if (!PyArray_Check(input)) {
        PyErr_SetString(PyExc_TypeError, "Input must be a NumPy array");
