int count_files_with_format(const char *dir, const char *format) {
    int total_count = 0;
    DIR *dp;
    struct dirent *entry;
    char path[1024];

    if ((dp = opendir(dir)) == NULL) {
        perror("opendir");
        return -1; // Indicate an error by returning a negative number
    }

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // Skip the current directory and parent directory entries
        }

        snprintf(path, sizeof(path), "%s/%s", dir, entry->d_name);

        if (entry->d_type == DT_DIR) {
            total_count += count_files_with_format(path, format); // Recursively traverse directories
        } else if (entry->d_type == DT_REG) {
            FILE *file = fopen(path, "r");
            if (file != NULL) {
                char buffer[1024];
                size_t bytesRead;
                while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
                    for (size_t i = 0; i < bytesRead; ++i) {
                        if (strstr(&buffer[i], format) != NULL) {
                            total_count++;
                            break; // Only count the first occurrence in each file
                        }
                    }
                }
                fclose(file);
            } else {
                perror("fopen");
            }
        }
    }

    closedir(dp);
    return total_count;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <format>\n", argv[0]);
