#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

char* generate_random_file_path(const char* dir, const char* prefix, size_t max_size) {
    if (dir == NULL || prefix == NULL || max_size <= 0) {
        return NULL;
    }

    // Calculate the maximum length for the directory path and prefix
    size_t dir_len = strlen(dir);
    size_t prefix_len = strlen(prefix);
    if (dir_len >= max_size || prefix_len >= max_size) {
        return NULL;
    }

    // Calculate the total length of the final path
    size_t total_length = dir_len + 1 + prefix_len + 1; // directory + '/' + prefix + '\0'
    if (total_length >= max_size) {
        return NULL;
    }

    // Allocate memory for the final path
    char* path = (char*)malloc(max_size);
    if (path == NULL) {
        return NULL;
    }

    // Concatenate the directory path and prefix
    snprintf(path, max_size, "%s/%s", dir, prefix);

    // Check if the resulting path length exceeds the maximum allowed size
    if (strlen(path) >= max_size) {
        free(path);
        return NULL;
    }

    return path;
}
