#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>

typedef struct {
    char **paths;
    int count;
} PathTable;

void initPathTable(PathTable *table) {
    table->count = 0;
    table->paths = malloc(sizeof(char*));
    if (table->paths == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void addPath(PathTable *table, const char *path) {
    table->count++;
    table->paths = realloc(table->paths, table->count * sizeof(char*));
    if (table->paths == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    table->paths[table->count - 1] = strdup(path);
}

void freePathTable(PathTable *table) {
    for (int i = 0; i < table->count; i++) {
        free(table->paths[i]);
    }
    free(table->paths);
}

DIR* openDirectory(const char *path) {
    DIR *dir = opendir(path);
    if (dir == NULL) {
        perror("Failed to open directory");
    }
    return dir;
}

void traverseDirectoryTree(PathTable *table, const char *root) {
    DIR *dir = openDirectory(root);
    if (dir == NULL) {
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char *fullPath = malloc(strlen(root) + strlen(entry->d_name) + 2);
        if (fullPath == NULL) {
            perror("Failed to allocate memory");
            closedir(dir);
            exit(EXIT_FAILURE);
        }
        sprintf(fullPath, "%s/%s", root, entry->d_name);
        addPath(table, fullPath);
        free(fullPath);
    }
    closedir(dir);
}

char* findDirectoryContainingPath(const char *targetPath) {
    PathTable table;
    initPathTable(&table);
    traverseDirectoryTree(&table, "/"); // Start traversal from the root directory

    for (int i = 0; i < table.count; i++) {
        if (strstr(targetPath, table.paths[i]) != NULL) {
            freePathTable(&table);
            return strdup(table.paths[i]);
        }
    }

    freePathTable(&table);
    return NULL;
}

int main() {
    char *dirContainingPath = findDirectoryContainingPath("/some/path/to/find");
    if (dirContainingPath != NULL) {
        printf("Directory containing path: %s\n", dirContainingPath);
        free(dirContainingPath);
    } else {
        printf("Path not found in the directory tree.\n");
    }
    return 0;
}
