void display_progress(int percentage) {
    static int initialized = 0;
    static WINDOW *progress_win = NULL;
    static int bar_width = 50;

    if (!initialized) {
        // Initialize ncurses window for progress bar
        initscr();
        cbreak();
        noecho();
        refresh();
        progress_win = newwin(3, bar_width + 4, (LINES - 3) / 2, (COLS - bar_width - 4) / 2);
