        return;
    }

    // Clear the progress bar window
    wclear(progress_win);
    box(progress_win, 0, 0);

    // Display the percentage complete
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "%d%%", percentage);
    mvwprintw(progress_win, 1, (bar_width - strlen(buffer)) / 2, "%s", buffer);

    // Display the progress bar
    int filled_length = (int)(percentage * bar_width / 100.0);
    for (int i = 0; i < filled_length; ++i) {
        mvwaddch(progress_win, 1, i + 2, ' ');
    }

    wrefresh(progress_win);
}

