#include <stdlib.h>
#include <string.h>

char* concatenate_filename(const char* filename, const char* extension) {
    size_t filename_len = strlen(filename);
    size_t extension_len = strlen(extension);
    size_t total_len = filename_len + extension_len + 1; // +1 for the null terminator

    // Allocate memory for the new filename string
    char* new_filename = (char*)malloc(total_len * sizeof(char));
    if (new_filename == NULL) {
        return NULL; // Allocation failed
    }

    // Concatenate the filename and extension
    strcpy(new_filename, filename);
    strcat(new_filename, ".");
    strcat(new_filename, extension);

    return new_filename;
}
