#include <string.h>

char* remove_trailing_newlines(char *input) {
    // Ensure input is not NULL to prevent null pointer dereference
    if (input == NULL) {
        return NULL;
    }

    // Find the length of the string
    size_t len = strlen(input);

    // Check for empty strings or strings without newline characters
    if (len == 0) {
        return input;
    }

    // Remove trailing newlines and carriage returns
    while (len > 0 && (input[len - 1] == '\n' || input[len - 1] == '\r')) {
        len--;
    }

    // Ensure the string is not empty after trimming
    if (len == 0) {
        return input;
    }

    // Append a newline character to the end of the string
    input[len] = '\n';
    input[len + 1] = '\0';

    return input;
}
