char* copy_and_handle_comma(const char* input) {
    if (input == NULL) {
        return NULL;
    }

    // Calculate the length of the new string including space for the comma and null terminator
    size_t len = strlen(input);
    if (len == 0) {
        return strdup("");
    }

    char* output = (char*)malloc((len + 2) * sizeof(char)); // +1 for comma, +1 for null terminator
    if (output == NULL) {
        return NULL;
