char* create_full_path(const char* dir, const char* fname) {
    // Get the current working directory
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        perror("getcwd() error");
        return NULL;
    }

    // Allocate memory for the full path name
    size_t dir_len = strlen(dir);
