    // Ensure there is a '/' at the end of the directory path
    if (dir[dir_len - 1] != '/' && dir[dir_len - 1] != '\\') {
        strcat(full_path, "/");
    }

    // Concatenate the file name to the full path
    strcat(full_path, fname);

    return full_path;
}
