int retrieve_file(const char *filename, const char *ip_address, int mode) {
    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[1024] = {0};
    FILE *file;

    // Initialize socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        return -errno;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Assuming port 80 for HTTP (adjust if needed)
    inet_pton(AF_INET, ip_address, &server_addr.sin_addr);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return -errno;
    }

    // Send request for file
    char request[256];
    snprintf(request, sizeof(request), "GET /%s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", filename, ip_address);
    send(sockfd, request, strlen(request), 0);

    // Read response from server
    int bytes_received = 0;
    while ((bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        if (mode == 1) { // Write mode
            file = fopen(filename, "wb");
            if (!file) {
                perror("File open failed");
                close(sockfd);
                return -errno;
            }
            fwrite(buffer, 1, bytes_received, file);
            fclose(file);
        } else if (mode == 2) { // Read mode
            printf("%.*s", bytes_received, buffer);
        }
    }

    if (bytes_received < 0) {
        perror("Receive failed");
    }

    close(sockfd);
    return 0;
}
