typedef struct {
    int pid;
    char *network_address;
} Context;

int set_context(Context *ctx, const char *command_path) {
    if (ctx == NULL || command_path == NULL) {
        return -1; // Invalid input parameters
    }

    ctx->pid = getpid(); // Set the current process ID

    size_t addr_len = strlen(command_path);
    if (addr_len > 0 && command_path[addr_len - 1] == '\n') {
        addr_len--; // Remove newline character if present
    }

    ctx->network_address = (char *)malloc((addr_len + 1) * sizeof(char));
    if (ctx->network_address == NULL) {
        return -1; // Memory allocation failed
    }

    strncpy(ctx->network_address, command_path, addr_len);
    ctx->network_address[addr_len] = '\0'; // Null-terminate the string

    return 0; // Success
}

void free_context(Context *ctx) {
    if (ctx != NULL) {
        if (ctx->network_address != NULL) {
            free(ctx->network_address);
            ctx->network_address = NULL;
        }
        ctx->pid = 0; // Reset the PID to indicate no process ID is set
    }
}

