        free_context(&ctx);
        return EXIT_FAILURE;
    }

    printf("Process ID: %d\n", ctx.pid);
    printf("Network Address: %s\n", ctx.network_address);

    // Use the context as needed...

    free_context(&ctx);
    return EXIT_SUCCESS;
}
