#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    char *key;
    char *value;
    int active;
} pair_t;

typedef struct {
    pair_t *pairs;
    size_t capacity;
    size_t order;
} bucket_t;

typedef struct {
    bucket_t *buckets;
    size_t count;
} hashtable_t;

size_t hash_str(const char *str) {
    size_t hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

size_t hashmask(size_t hm) {
    return (1U << hm) - 1;
}

pair_t* hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
    for (size_t i = 0; i < bucket->capacity; ++i) {
        pair_t *pair = &bucket->pairs[i];
        if (pair->active && strcmp(pair->key, key) == 0) {
            return pair;
        }
    }
    return NULL;
}

int hashtable_lookup(hashtable_t *hashtable, const char *key, char **value, size_t *collisions) {
    if (!hashtable || !key || !value || !collisions) {
        return -1; // Invalid input parameters
    }

    size_t hash = hash_str(key);
    bucket_t *bucket = &hashtable->buckets[hash & hashmask(hashtable->order)];

    pair_t *pair = hashtable_find_pair(hashtable, bucket, key, hash);
    if (!pair || !pair->active) {
        return 0; // Key not found or value is not active
    }

    *value = pair->value;
    *collisions = (bucket->capacity - 1) - (hash & hashmask(hashtable->order));
    return 1; // Success
}
