// Function to check if the token is expired
int is_token_expired(const char *token) {
    jwt_t *jwt = jwt_decode(token, JWT_DECODE_LEEWAY);
    if (!jwt) {
        return 1; // Token decoding failed
    }

    int exp = jwt_get_claim(jwt, "exp");
    if (exp == -1) {
        jwt_free(jwt);
        return 1; // Expiration claim not found
    }

    time_t now = time(NULL);
    if (exp <= now) {
        jwt_free(jwt);
        return 1; // Token expired
    }

    jwt_free(jwt);
    return 0; // Token is not expired
}

// Function to check if the token has the required scope
int has_required_scope(const char *token, const char *required_scope) {
    jwt_t *jwt = jwt_decode(token, JWT_DECODE_LEEWAY);
    if (!jwt) {
        return 0; // Token decoding failed
    }

    const char *scope = jwt_get_claim(jwt, "scope");
    if (!scope) {
        jwt_free(jwt);
        return 0; // Scope claim not found
    }

    // Check if the scope contains the required scope
    if (strstr(scope, required_scope)) {
        jwt_free(jwt);
        return 1; // Required scope is present
    }

    jwt_free(jwt);
    return 0; // Required scope not found
}

// Function to parse and verify the JWT token
char* parse_and_verify_token(const char *json_str, const char *secret_key, const char *required_scope) {
    jwt_t *jwt = jwt_decode(json_str, JWT_DECODE_LEEWAY);
    if (!jwt) {
        return NULL; // Token decoding failed
    }

    int verified = jwt_verify(jwt, secret_key);
    if (verified != 0) {
        jwt_free(jwt);
        return NULL; // Token verification failed
    }

    if (is_token_expired(json_str)) {
        jwt_free(jwt);
        return NULL; // Token is expired
    }

    if (!has_required_scope(json_str, required_scope)) {
        jwt_free(jwt);
        return NULL; // Token does not have the required scope
    }

    const char *token = jwt_get_claim(jwt, "access_token");
    if (!token) {
        jwt_free(jwt);
        return NULL; // Access token claim not found
    }

    char *result = strdup(token);
    jwt_free(jwt);
    return result;
}
