#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* make_tempname() {
    char temp_filename[] = "/tmp/tempfileXXXXXX";
    int fd;
    char *temp_path;

    // Create a unique temporary filename
    if ((fd = mkstemp(temp_filename)) == -1) {
        perror("mkstemp");
        return NULL;
    }

    // Get the full path of the temporary file
    temp_path = realpath(temp_filename, NULL);
    if (temp_path == NULL) {
        perror("realpath");
        close(fd);
        unlink(temp_filename); // Remove the temporary file
        return NULL;
    }

    // Close the file descriptor to release it immediately
    close(fd);

    return temp_path;
}
