#include <string.h>
#include <limits.h>

void modify_filename(const char *orig_name, int num_digits, const char *file_type, char *buffer) {
    // Find the position of the last dot in the original filename
    const char *last_dot = strrchr(orig_name, '.');
    size_t orig_len = (last_dot != NULL) ? (size_t)(last_dot - orig_name) : strlen(orig_name);

    // Calculate the length of the new filename
    size_t buffer_len = orig_len + num_digits + strlen(file_type) + 1;
    if (buffer_len > PATH_MAX) {
        fprintf(stderr, "Filename too long\n");
        return;
    }

    // Copy the original filename up to the last dot and add the new extension
    strncpy(buffer, orig_name, orig_len);
    buffer[orig_len] = '\0';
    if (last_dot != NULL) {
        strcat(buffer, ".");
        strncat(buffer, file_type, strlen(file_type));
    } else {
        strcat(buffer, file_type);
    }

    // Add the number of digits to the end of the filename
    char num_str[12]; // Enough to hold any int value up to 64-bit
    snprintf(num_str, sizeof(num_str), "%0*d", num_digits, 0); // Assuming cnt is always 0 for simplicity
    strcat(buffer, num_str);
}
