#include <random>
#include <chrono>

void selectRandomAttack() {
    static std::mt19937_64 generator(std::random_device{}());
    static bool canAttack = true;
    static auto lastAttackTime = std::chrono::steady_clock::now();
    const auto cooldownDuration = std::chrono::seconds(9);

