struct Image {
    unsigned char* data;
    int width;
    int height;
};

Image* createBlankImage(int width, int height) {
    if (width <= 0 || height <= 0) {
        std::cerr << "Invalid image dimensions." << std::endl;
        return nullptr; // Return a reset image or nullptr
    }

    Image* img = new Image();
    if (!img) {
