vector<Pair> findBestCombination(const vector<Pair>& pairs, int target) {
    // Initialize the best combination and its sum
    vector<Pair> best_combination;
    int best_sum = numeric_limits<int>::max();

    // Iterate over all possible combinations
    const size_t n = pairs.size();
    for (size_t i = 0; i < (1 << n); ++i) {
        vector<Pair> current_combination;
