        int element = getRandomNumber(ELEMENT_MIN, ELEMENT_MAX);
        originalSet.insert(element);
    }

    // Check invariants of the original set
    if (!std::is_sorted(originalSet.begin(), originalSet.end())) {
        std::cerr << "Original set is not sorted!" << std::endl;
        return false;
