    // Create a new sorted vector set by inserting elements of the original set into a new set
    std::set<int> newSet(originalSet.begin(), originalSet.end());

    // Check invariants of the new set
    if (!std::is_sorted(newSet.begin(), newSet.end())) {
        std::cerr << "New set is not sorted!" << std::endl;
        return false;
    }

    // Check that the two sets are equal
    if (originalSet != newSet) {
        std::cerr << "Sets are not equal!" << std::endl;
        return false;
    }

    return true;
}
