#include <uuid/uuid.h> // For generating unique file names

class MessageWriter {
public:
    virtual void writeMessage(const std::string& message) = 0;
};

class StaticTransformMessage {
public:
    std::string base_link;
    std::string camera_pose;

    StaticTransformMessage(const std::string& base, const std::string& pose)
        : base_link(base), camera_pose(pose) {}
};

void saveTransformsToFile(const std::string& prefix, const std::map<std::string, std::string>& poses, MessageWriter& writer) {
    // Generate a unique file name
    char uuid[37]; // UUID string length + null terminator
    uuid_t uu;
    uuid_generate(uu);
    uuid_unparse(uu, uuid);

    std::string filename = prefix + "_" + uuid + ".txt";

    std::ofstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file for writing.");
    }

    // Write each transform to the file
    for (const auto& pose : poses) {
        StaticTransformMessage message(pose.first, pose.second);
        writer.writeMessage(message.base_link + " " + message.camera_pose + "\n");
    }

    file.close();
}
