class RobotClient {
public:
    RobotClient(const std::string& ip, int port) : ip_(ip), port_(port), sockfd(-1) {}

    ~RobotClient() {
        if (sockfd != -1) {
            close(sockfd);
        }
    }

    bool connectToRobot() {
        // Create socket
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            std::cerr << "Error creating socket" << std::endl;
            return false;
        }

        // Define server address
        struct sockaddr_in serv_addr;
        memset(&serv_addr, '0', sizeof(serv_addr));
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(port_);

        if (inet_pton(AF_INET, ip_.c_str(), &serv_addr.sin_addr) <= 0) {
            std::cerr << "Invalid address/ Address not supported" << std::endl;
            close(sockfd);
            sockfd = -1;
            return false;
        }

        // Connect to server
        if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
            std::cerr << "Connection Failed" << std::endl;
            close(sockfd);
            sockfd = -1;
            return false;
        }

        return true;
    }

    bool sendCommand(const std::string& command) {
        if (sockfd < 0) {
            std::cerr << "Socket not initialized" << std::endl;
            return false;
        }

        // Send command to server
        int bytesSent = send(sockfd, command.c_str(), command.size(), 0);
        if (bytesSent < 0) {
            std::cerr << "Send failed" << std::endl;
            return false;
        }

        return true;
    }

    std::string receiveResponse() {
        const int bufferSize = 1024;
        char buffer[bufferSize] = {0};

        // Receive response from server
        int bytesReceived = recv(sockfd, buffer, bufferSize - 1, 0);
        if (bytesReceived < 0) {
            std::cerr << "Receive failed" << std::endl;
            return "";
        } else if (bytesReceived == 0) {
            std::cout << "Connection closed by server" << std::endl;
            close(sockfd);
            sockfd = -1;
            return "";
        }

        return std::string(buffer, bytesReceived);
    }

private:
    std::string ip_;
    int port_;
    int sockfd;
};

