enum Tile {
    EMPTY = 0,
    WALL = 1,
    FLOOR = 2
};

std::vector<std::vector<Tile>> loadMapFromString(const std::string& mapString, char delimiter) {
    // Validate the input string to ensure it is non-empty and properly formatted.
    if (mapString.empty()) {
        throw std::invalid_argument("Input string is empty.");
    }

