                tileRow.push_back(WALL);
            } else if (tileStr == "FLOOR") {
                tileRow.push_back(FLOOR);
            } else {
                throw std::invalid_argument("Invalid tile value in the input string.");
            }
        }

        map.push_back(tileRow);
    }

    return map;
}
