#include <iostream>
#include <vector>
#include <random>
#include <memory>

class Entity {
public:
    virtual ~Entity() = default;
};

class ComponentManager {
public:
    template<typename T, typename... Args>
    std::shared_ptr<T> createComponent(Args&&... args) {
        auto component = std::make_shared<T>(std::forward<Args>(args)...);
        components_.push_back(component);
        return component;
    }

    template<typename T>
    std::shared_ptr<T> getComponent() const {
        for (const auto& component : components_) {
            if (auto ptr = std::dynamic_pointer_cast<T>(component)) {
                return ptr;
            }
        }
        return nullptr;
    }

private:
    std::vector<std::shared_ptr<Entity>> components_;
};

class EntityManager {
public:
    void subscribeNewEntity(const std::shared_ptr<Entity>& entity) {
        entities_.push_back(entity);
    }

    void updateEntities() {
        for (auto& entity : entities_) {
            // Update logic here
        }
    }

    void destroyRandomEntity() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, entities_.size() - 1);
        int index = dis(gen);
        entities_.erase(entities_.begin() + index);
    }

private:
    std::vector<std::shared_ptr<Entity>> entities_;
};

