#include <unordered_map>
#include <memory>
#include <mutex>

struct Page {
    int id;
    void* data;
};

class PageManager {
public:
    void createPage(int pageId, std::unique_ptr<Page> page) {
        std::lock_guard<std::mutex> lock(mutex_);
        pages_[pageId] = std::move(page);
    }

    std::unique_ptr<Page> getPage(int pageId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = pages_.find(pageId);
        if (it != pages_.end()) {
            return std::move(it->second);
        }
        return nullptr;
    }

    void deletePage(int pageId) {
        std::lock_guard<std::mutex> lock(mutex_);
        pages_.erase(pageId);
    }

private:
    std::unordered_map<int, std::unique_ptr<Page>> pages_;
    std::mutex mutex_;
};
