#include <vector>
#include <stdexcept>

class WireframeGenerator {
public:
    WireframeGenerator(const std::vector<int>& points) : points_(points), pointIndices_(), lineIndices_(), faceIndices_(), lineCount_(0) {
        if (points_.empty()) {
            throw std::invalid_argument("Points array cannot be empty.");
        }
        generateWireframe();
    }

    const std::vector<int>& getPointIndices() const { return pointIndices_; }
    const std::vector<int>& getLineIndices() const { return lineIndices_; }
    const std::vector<int>& getFaceIndices() const { return faceIndices_; }
    int getLineCount() const { return lineCount_; }

private:
    std::vector<int> points_;
    std::vector<int> pointIndices_;
    std::vector<int> lineIndices_;
    std::vector<int> faceIndices_;
    int lineCount_;

    void generateWireframe() {
        // Allocate memory for the indices and copy the input array into it.
        const size_t numPoints = points_.size();
        pointIndices_.reserve(numPoints);
        lineIndices_.reserve(numPoints * 2); // Each point can have up to 2 lines (edges).
        faceIndices_.reserve(0); // Faces are not generated in this example.

        for (size_t i = 0; i < numPoints; ++i) {
            pointIndices_.push_back(static_cast<int>(i));
            if (i > 0) {
                lineIndices_.push_back(static_cast<int>(i - 1));
                lineIndices_.push_back(static_cast<int>(i));
                ++lineCount_;
            }
        }
    }
};
