#include <type_traits>

template<typename Container>
size_t countUniqueElements(const Container& container) {
    std::unordered_set<typename Container::value_type> uniqueElements;
    for (const auto& element : container) {
        uniqueElements.insert(element);
    }
    return uniqueElements.size();
}

