    Graph(size_t numVertices) : adjacencyList(numVertices, nullptr) {
        // Initialize the graph with empty lists
    }

    void addEdge(int from, int to) {
        if (from >= adjacencyList.size() || to >= adjacencyList.size()) {
            throw std::out_of_range("Vertex index out of range");
        }

        // Allocate new node for 'to' vertex and set its degree
        auto newNode = std::make_shared<Vertex>();
        newNode->degree = 1; // Increment the degree of 'to' vertex

        // Insert at the beginning of the list
        newNode->next = adjacencyList[to];
        adjacencyList[to] = newNode;

        // For undirected graph, add edge in both directions
        if (from != to) {
            newNode = std::make_shared<Vertex>();
            newNode->degree = 1; // Increment the degree of 'from' vertex
            newNode->next = adjacencyList[from];
            adjacencyList[from] = newNode;
        }
    }
};

template <typename Iterator>
std::unique_ptr<Graph> createAdjacencyList(Iterator begin, Iterator end) {
    if (begin == end) {
        throw std::invalid_argument("Iterator range is empty");
    }

    // Determine the number of vertices in the graph
    int numVertices = 0;
    for (auto it = begin; it != end; ++it) {
        if (*it < 0 || *it >= numVertices) {
            numVertices = *it + 1;
        }
    }

    // Create the graph with the determined number of vertices
    auto graph = std::make_unique<Graph>(numVertices);

    // Add edges to the adjacency list
    for (auto it = begin; it != end; ++it) {
        if (*it < 0 || *it >= numVertices) {
            throw std::out_of_range("Vertex index out of range");
        }
        auto nextIt = std::next(it);
        while (nextIt != end && *nextIt == *it) {
            graph->addEdge(*it, *nextIt);
            ++nextIt;
        }
    }

    return graph;
}
