#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    int x;
    int y;
} Point;

typedef struct {
    Point *points;
    int count;
    char closed;
} Path;

Path* parse_path(const char *input) {
    // Parse the input string to create a path object
    Path *path = (Path *)malloc(sizeof(Path));
    if (!path) return NULL;

    // Initialize the path structure
    path->count = 0;
    path->closed = 0;
    path->points = NULL;

    const char *p = input;
    while (*p && *p != '\n') {
        if (isspace((unsigned char)*p)) {
            p++;
            continue;
        }

        Point point;
        int res = sscanf(p, "%d,%d", &point.x, &point.y);
        if (res != 2) {
            free(path);
            return NULL;
        }

        path->count++;
        path->points = (Point *)realloc(path->points, path->count * sizeof(Point));
        if (!path->points) {
            free(path);
            return NULL;
        }
        path->points[path->count - 1] = point;

        while (*p && *p != '\n' && !isspace((unsigned char)*p)) {
            p++;
        }
    }

    if (path->count > 0) {
        path->closed = input[strlen(input) - 1] == 'c'; // Check for closing character
    }

    return path;
}

char* serialize_path(const Path *path) {
    if (!path || !path->points) return NULL;

    char *output = (char *)malloc(path->count * 10 + 2); // Allocate enough space
    if (!output) return NULL;

    output[0] = '\0';
    for (int i = 0; i < path->count; i++) {
        char buffer[30];
        snprintf(buffer, sizeof(buffer), "%d,%d", path->points[i].x, path->points[i].y);
        strcat(output, buffer);
        if (i < path->count - 1) {
            strcat(output, ",");
        }
    }

    if (path->closed) {
        strcat(output, "c");
    }

    return output;
}

int main() {
    const char *input = "0,0\n1,1\n2,2\nc";
    Path *path = parse_path(input);
    if (!path) {
        printf("Failed to parse path.\n");
        return 1;
    }

    char *serialized = serialize_path(path);
    if (!serialized) {
        printf("Failed to serialize path.\n");
        free(path->points);
        free(path);
        return 1;
    }

    printf("Serialized Path: %s\n", serialized);

    // Free allocated memory
    free(path->points);
    free(path);
    free(serialized);

    return 0;
}
