int EstimateStorage(double threshold, int numAngles) {
    if (threshold <= 0 || numAngles <= 0) {
        throw std::invalid_argument("Threshold and number of angles must be positive.");
    }

    double storagePerSequence = threshold * numAngles;
    int estimatedStorageBytes = static_cast<int>(std::round(storagePerSequence));

    const double bytesInKB = 1024.0;
    const double bytesInMB = bytesInKB * 1024.0;
    const double bytesInGB = bytesInMB * 1024.0;
    const double bytesInTB = bytesInGB * 1024.0;

    if (estimatedStorageBytes < bytesInKB) {
        return estimatedStorageBytes;
    } else if (estimatedStorageBytes < bytesInMB) {
        return static_cast<int>(std::round(estimatedStorageBytes / bytesInKB)) * 1024;
    } else if (estimatedStorageBytes < bytesInGB) {
