void drawCurve(const std::vector<std::pair<double, double>>& controlPoints, int numSegments = 100) {
    if (controlPoints.empty()) return;

    glBegin(GL_LINE_STRIP);
    for (int i = 0; i <= numSegments; ++i) {
        double t = static_cast<double>(i) / numSegments;
        double x = pow(1 - t, 2) * controlPoints[0].first + 2 * (1 - t) * t * controlPoints[1].first + t * t * controlPoints[2].first;
