#include <stdio.h>
#include <stdlib.h>

void read2DArray(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Read the dimensions from the first 2 bytes of the file
    unsigned short rows, cols;
    fread(&rows, sizeof(unsigned short), 1, file);
    fread(&cols, sizeof(unsigned short), 1, file);

    // Calculate the size of the array and allocate memory
    size_t arraySize = rows * cols * sizeof(float);
    float *array = (float *)malloc(arraySize);
    if (!array) {
        perror("Failed to allocate memory");
        fclose(file);
        return;
    }

    // Read the values into the allocated array
    size_t elementsRead = fread(array, sizeof(float), rows * cols, file);
    if (elementsRead != rows * cols) {
        perror("Failed to read all elements");
        free(array);
        fclose(file);
        return;
    }

    // Print the dimensions of the array
    printf("Array dimensions: %ux%u\n", rows, cols);

    // Free the allocated memory
    free(array);

    fclose(file);
}

int main() {
