#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <cstring>

class Cache {
public:
    Cache(size_t size) : entries(size) {}

    void addEntry(const std::string& key, const std::string& value) {
        if (entries.size() >= 100) {
            throw std::runtime_error("Cache is full");
        }
        entries.emplace_back(key, value);
    }

    void shuffleEntries() {
        std::random_device rd;
        std::mt19937 g(rd());
        std::shuffle(entries.begin(), entries.end(), g);
    }

    std::string openEntry(const std::string& key) const {
        for (const auto& entry : entries) {
            if (entry.first == key) {
                return entry.second;
            }
        }
        throw std::runtime_error("Entry not found");
    }

private:
    std::vector<std::pair<std::string, std::string>> entries;
};

int main() {
    Cache cache(100);

    // Add 100 entries to the cache
    for (int i = 0; i < 100; ++i) {
        std::string key = "key" + std::to_string(i);
        std::string value = "value" + std::to_string(i);
        cache.addEntry(key, value);
    }

    // Shuffle the entries in the cache
    cache.shuffleEntries();

    // Open each entry in the cache
    for (int i = 0; i < 100; ++i) {
        std::string key = "key" + std::to_string(i);
        try {
            std::string value = cache.openEntry(key);
            std::cout << "Key: " << key << ", Value: " << value << std::endl;
        } catch (const std::runtime_error& e) {
            std::cerr << "Error opening entry: " << e.what() << std::endl;
        }
    }

    return 0;
}
