// Define the maximum length for file paths to prevent path traversal attacks and buffer overflows
#define MAX_PATH_LENGTH 4096

char* validate_and_store_filepath(const char *input) {
    if (input == NULL || strlen(input) >= MAX_PATH_LENGTH) {
        fprintf(stderr, "Error: Invalid file path length.\n");
        return NULL;
    }

    // Allocate memory for the output buffer
    char *output = safe_calloc(MAX_PATH_LENGTH + 1, sizeof(char));
    if (output == NULL) {
        perror("Error allocating memory");
        return NULL;
    }

    // Copy the input to the output buffer and validate it
    strncpy(output, input, MAX_PATH_LENGTH);
    if (strchr(output, '/') != NULL || strchr(output, '\\') != NULL) {
        fprintf(stderr, "Error: Invalid file path character.\n");
        free(output);
        return NULL;
    }

    // Normalize the path to prevent directory traversal attacks
    char *normalized_path = realpath(output, NULL);
    if (normalized_path == NULL) {
        perror("Error normalizing file path");
        free(output);
        return NULL;
    }

    // Check if the normalized path is within a safe directory
    const char *safe_directory = "/safe/directory/";
    if (strncmp(normalized_path, safe_directory, strlen(safe_directory)) != 0) {
        fprintf(stderr, "Error: File path outside of allowed directory.\n");
        free(output);
        free(normalized_path);
        return NULL;
    }

    // Free the temporary buffer and return the normalized path
    free(output);
    return normalized_path;
}
