#include <stdlib.h>
#include <string.h>

int parseAndTransformText(const char *inputText) {
    if (inputText == NULL) {
        return 0;
    }

    // Allocate memory for the output text
    size_t inputLength = strlen(inputText);
    char *outputText = (char *)malloc((inputLength + 1) * sizeof(char));
    if (outputText == NULL) {
        return -1; // Allocation failed
    }

    // Copy the input text to the output text
    strcpy(outputText, inputText);

    // Apply rules to parse and transform the text
    // Example rule: replace all occurrences of "foo" with "bar"
    char *pos = strstr(outputText, "foo");
    while (pos != NULL) {
        memmove(pos + 3, pos + 3, strlen(pos + 3) + 1); // Remove "foo"
        memcpy(pos, "bar", 3); // Replace with "bar"
        pos = strstr(pos, "foo");
    }

    // Count the number of paragraphs in the transformed text
    int paragraphCount = 0;
    char *paragraphStart = outputText;
    while (*paragraphStart != '\0') {
        if (*paragraphStart == '\n' && *(paragraphStart + 1) == '\n') {
            paragraphCount++;
            // Skip to the start of the next paragraph
            paragraphStart += 2;
        } else {
            paragraphStart++;
        }
    }

    // Check if the last character is a newline to avoid counting an extra paragraph at the end
    if (*(paragraphStart - 1) == '\n') {
        paragraphCount--;
    }

    free(outputText);
    return paragraphCount;
}
