#include <iostream>
#include <vector>

struct TreeNode {
    int value;
    std::vector<TreeNode*> children;
};

TreeNode* buildTree(int n, const int* c) {
    if (n <= 0) return nullptr;

    // Create nodes and initialize them with values from standard input
    std::vector<TreeNode> nodes(n);
    for (int i = 0; i < n; ++i) {
        nodes[i].value = i; // Assuming value is the node index for simplicity
    }

    // Populate children based on the adjacency list representation
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 2; ++j) {
            int childIndex = c[i * 2 + j];
            if (childIndex >= 0 && childIndex < n) {
                nodes[i].children.push_back(&nodes[childIndex]);
            }
        }
    }

    // Return the root node, which is the first node in the list
    return &nodes[0];
}

int main() {
    int n;
    std::cin >> n;
    if (n <= 0) {
        std::cerr << "Invalid number of nodes." << std::endl;
        return 1;
    }

    // Read the adjacency list representation from standard input
    int* c = new int[2 * n];
    for (int i = 0; i < 2 * n; ++i) {
        std::cin >> c[i];
    }

    TreeNode* root = buildTree(n, c);
    if (!root) {
        std::cerr << "Failed to build the tree." << std::endl;
        delete[] c;
        return 1;
    }

    // For demonstration purposes, print the root value (should be 0 for simplicity)
    std::cout << "Root node value: " << root->value << std::endl;

    delete[] c;
    return 0;
}
