uint64_t GetThreadRandom() {
    uint64_t *rand_val = pthread_getspecific(rand_key);
    if (!rand_val) {
        // Initialize thread-local storage with a new random value
        rand_val = (uint64_t*)malloc(sizeof(uint64_t));
        *rand_val = RandUInt64();
        pthread_setspecific(rand_key, (void*)rand_val);
    }
    return *rand_val;
}

// Function to initialize thread-local storage for random numbers
int InitThreadLocalRandom() {
    if (pthread_key_create(&rand_key, thread_init) != 0) {
        return -1; // Failed to create key
