import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.rendering.PDFRenderer;

public class PPMGenerator {
    public static byte[] generatePPMImage(PageDocument document, int pageNumber, int displayWidth, int displayHeight) throws IOException {
        // Load the PDF document
        try (PDDocument pdfDocument = PDDocument.load(document.getInputStream())) {
            // Create a PDF renderer to render the specified page
            PDFRenderer pdfRenderer = new PDFRenderer(pdfDocument);

            // Render the specified page to an image with the desired display size
            BufferedImage bufferedImage = pdfRenderer.renderImageWithDPI(pageNumber, 300, org.apache.pdfbox.rendering.PageDrawer.RenderingMode.NORMAL);
            BufferedImage scaledImage = scaleImage(bufferedImage, displayWidth, displayHeight);

            // Convert the image to PPM format and write it to a byte array
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            ImageIO.write(scaledImage, "ppm", outputStream);
            return outputStream.toByteArray();
        }
    }

    private static BufferedImage scaleImage(BufferedImage originalImage, int targetWidth, int targetHeight) {
        // Scale the image to fit within the specified display size while maintaining aspect ratio
        double widthRatio = (double) targetWidth / originalImage.getWidth();
        double heightRatio = (double) targetHeight / originalImage.getHeight();
        double scaleFactor = Math.min(widthRatio, heightRatio);

        int scaledWidth = (int) (originalImage.getWidth() * scaleFactor);
        int scaledHeight = (int) (originalImage.getHeight() * scaleFactor);

        BufferedImage scaledImage = new BufferedImage(scaledWidth, scaledHeight, originalImage.getType());
        java.awt.Graphics2D graphics2D = scaledImage.createGraphics();
        graphics2D.drawImage(originalImage, 0, 0, scaledWidth, scaledHeight, null);
        graphics2D.dispose();

        return scaledImage;
    }
}
