#include <iostream>
#include <fstream>
#include <vector>
#include <cstring>

enum class Format { XML, Binary, COLLADA };

void saveData(const std::vector<char>& data, const std::string& filename, Format format) {
    std::ofstream file;
    switch (format) {
        case Format::XML:
            file.open(filename + ".xml");
            break;
        case Format::Binary:
            file.open(filename + ".bin", std::ios::binary);
            break;
        case Format::COLLADA:
            file.open(filename + ".dae");
            break;
    }

    if (!file) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return;
    }

    file.write(data.data(), data.size());
    if (!file) {
        std::cerr << "Error writing to file: " << filename << std::endl;
        file.close();
        return;
    }

    file.close();
    std::cout << "Data saved to " << filename << " in " << (format == Format::XML ? "XML" : format == Format::Binary ? "Binary" : "COLLADA") << " format." << std::endl;
}

int main() {
    std::vector<char> data = {'t', 'e', 's', 't'};
    saveData(data, "testfile", Format::XML);
    return 0;
}
