void flipVertical(unsigned int **pixels, int width, int height, const char *pixelFormat) {
    // Validate pixel format and allocate memory for temporary array
    if (strcmp(pixelFormat, "RGB") != 0 && strcmp(pixelFormat, "RGBA") != 0) {
        return; // Unsupported pixel format
    }

    size_t pixelSize = (strcmp(pixelFormat, "RGB") == 0) ? 3 : 4;
    void *tempArray = malloc(width * height * pixelSize);
