               width * pixelSize);
    }

    // Copy data back to input array in flipped order
    for (int y = 0; y < height; ++y) {
        memcpy((unsigned char *)(*pixels) + y * width * pixelSize,
               (unsigned char *)tempArray + y * width * pixelSize,
               width * pixelSize);
    }

    // Free temporary array
