#include <linux/mm.h> // For PROT_NONE and mprotect

size_t trigger_access_violation() {
    const size_t memory_size = 1024;
    void *memory = malloc(memory_size);
    if (!memory) {
        return 0; // Allocation failed, return 0 indicating no bytes read.
    }

    // Set the memory to a known value to make it distinguishable during comparison.
    memset(memory, 0xAA, memory_size);

    // Protect the page so that it cannot be read or written.
    if (mprotect(memory, getpagesize(), PROT_NONE) != 0) {
        free(memory);
        return 0; // Protection failed, return 0 indicating no bytes read.
    }

    // Allocate another block of memory to compare against.
    void *compare_memory = malloc(memory_size);
    if (!compare_memory) {
        free(memory);
        return 0; // Allocation failed, return 0 indicating no bytes read.
    }

    // Set the compare memory to a different known value.
    memset(compare_memory, 0xBB, memory_size);

    size_t bytes_read = 0;
    int result = memcmp(memory, compare_memory, memory_size);
    if (result == 0) {
        // If the comparison succeeds without triggering an access violation, return the number of bytes read.
        bytes_read = memory_size;
    } else {
        // If the comparison triggers an access violation, determine how many bytes were successfully read before the violation occurred.
        for (size_t i = 0; i < memory_size; ++i) {
            if (((char *)memory)[i] != ((char *)compare_memory)[i]) {
                // The first mismatch indicates where the access violation would have occurred.
                bytes_read = i;
                break;
            }
        }
    }

    free(memory);
    free(compare_memory);
    return bytes_read;
}
