// Function to generate MD5 hash of the input string
unsigned char* compute_md5(const unsigned char* str, size_t len) {
    // Allocate memory for the MD5 hash value
    unsigned char* md5_hash = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    if (!md5_hash) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Compute the MD5 hash
    MD5((const unsigned char*)str, len, md5_hash);

    return md5_hash;
