    if (!hex) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Convert the MD5 hash to a hexadecimal string
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hex[i * 2], "%02x", md5_hash[i]);
    }

    return hex;
}

