#include <libcdio/cdio.h>
#include <stdio.h>
#include <stdlib.h>

char* calculate_discid(CDIO_CD_t *cd) {
    if (cd == NULL) {
        return NULL;
    }

    int track_count = cdio_get_num_tracks(cd);
    if (track_count <= 0) {
        return NULL;
    }

    uint64_t sum_of_lbas = 0;
    for (int i = 0; i < track_count; ++i) {
        CDIO_TRACK_INFO_t *track_info = cdio_get_track_info(cd, i);
        if (track_info == NULL || track_info->lba == 0) {
            continue;
        }
        sum_of_lbas += track_info->lba;
    }

    // Ensure the divisor is not zero
    if (sum_of_lbas == 0) {
        return NULL;
    }

    uint64_t discid = (sum_of_lbas / 0xff) << 24;

    // Allocate memory for the DISCID string
    char *discid_str = (char *)malloc(9); // 8 characters + null terminator
    if (discid_str == NULL) {
        return NULL;
    }

    // Convert discid to a hexadecimal string
    snprintf(discid_str, 9, "%08lx", (unsigned long)discid);

    // Print the computed DISCID to the debug log
    printf("Computed DISCID: %s\n", discid_str);

    return discid_str;
}
