}

std::vector<std::vector<uint8_t>> loadDescriptorsFromFiles(const std::vector<std::string>& filePaths, bool includeAlpha) {
    std::vector<std::vector<uint8_t>> descriptors;

    for (const auto& filePath : filePaths) {
        if (!std::filesystem::exists(filePath)) {
            throw std::runtime_error("File does not exist: " + filePath);
        }

        try {
            std::vector<uint8_t> descriptor = loadDescriptorFromFile(filePath);
