std::unordered_map<int, int> countingSort(const std::vector<int>& input) {
    if (input.empty()) return {};

    // Find the maximum and minimum values in the input list
    int maxVal = *std::max_element(input.begin(), input.end());
    int minVal = *std::min_element(input.begin(), input.end());

    // Create a frequency array to store the count of each integer
