#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void create_board(const char *input, int *rows, int *cols) {
    // Determine the number of rows (length of input string) and columns (maximum length of a row)
    *rows = strlen(input);
    *cols = 0;
    for (int i = 0; i < *rows; i++) {
        int len = snprintf(NULL, 0, "%s", input + i * (*rows));
        if (len > *cols) {
            *cols = len;
        }
    }
}

void initialize_board(char **board, int rows, int cols) {
    // Initialize the board with spaces
    for (int i = 0; i < rows; i++) {
        board[i] = (char *)malloc((cols + 1) * sizeof(char));
        memset(board[i], ' ', cols);
        board[i][cols] = '\0'; // Null-terminate each row
    }
}

void update_board(char **board, const char *input, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (input[i] == 'R') {
                board[i][j] = '/';
            } else {
                board[i][j] = input[i];
            }
        }
    }
}

void print_board(char **board, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        printf("%s\n", board[i]);
        free(board[i]); // Free each row after printing
    }
}

int main() {
    char input[100];
    int rows, cols;

    // Read the string from standard input
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Error reading input\n");
        return 1;
    }

    // Remove newline character if present
    size_t len = strlen(input);
    if (len > 0 && input[len - 1] == '\n') {
        input[len - 1] = '\0';
    }

    // Create the board
    create_board(input, &rows, &cols);

    // Allocate memory for the board
    char *board[rows];
    initialize_board(board, rows, cols);

    // Update the board with the input string
    update_board(board, input, rows, cols);

    // Print the board to standard output
    print_board(board, rows, cols);

    return 0;
}
