int build_graph(char* edges[], int edge_count) {
    if (edge_count > MAX_NODES * MAX_NODES) {
        printf("Too many nodes\n");
        return -1;
    }

    int V = 0;
    for (int i = 0; i < edge_count; ++i) {
        char* edge = edges[i];
        int u, v;
        sscanf(edge, "%d %d", &u, &v);
        if (u >= V) V = u + 1;
        if (v >= V) V = v + 1;
    }

    int* graph[MAX_NODES];
    for (int i = 0; i < MAX_NODES; ++i) {
        graph[i] = (int*)calloc(MAX_NODES, sizeof(int));
    }

    for (int i = 0; i < edge_count; ++i) {
        char* edge = edges[i];
        int u, v;
        sscanf(edge, "%d %d", &u, &v);
        graph[u][v] = 1;
        graph[v][u] = 1;
    }

    if (is_cycle(V, graph)) {
        printf("Graph contains a cycle\n");
        for (int i = 0; i < MAX_NODES; ++i) {
            free(graph[i]);
        }
        return -1;
    }

    int component_count = count_components(V, graph);

    for (int i = 0; i < MAX_NODES; ++i) {
        free(graph[i]);
    }

    return component_count;
}
