#include <string>
#include <vector>
#include <iostream>

class CIMValue {
public:
    enum Type { STRING, ARRAY, NULL_VALUE };
    CIMValue(Type type, std::string value = "") : type(type), value(value) {}
    CIMValue(Type type, const std::vector<CIMValue>& array) : type(type), array(array) {}
    Type getType() const { return type; }
    const std::string& getStringValue() const { return value; }
    const std::vector<CIMValue>& getArrayValue() const { return array; }
private:
    Type type;
    std::string value;
    std::vector<CIMValue> array;
};

void appendCIMValueToString(const CIMValue& cimValue, std::string& result) {
    switch (cimValue.getType()) {
        case CIMValue::STRING:
            result += cimValue.getStringValue();
            break;
        case CIMValue::ARRAY: {
            const auto& array = cimValue.getArrayValue();
            for (const auto& elem : array) {
                appendCIMValueToString(elem, result);
            }
            break;
        }
        case CIMValue::NULL_VALUE:
            // No action needed as null values do not contribute to the string representation.
            break;
    }
}
