#include <vector>
#include <random>
#include <cmath>

std::vector<double> initializeEmbeddingLayer(size_t embeddingSize, size_t labelWidth, size_t numLabelTypes) {
    // Calculate the total number of weights
    size_t totalWeights = embeddingSize * labelWidth * numLabelTypes;

    // Allocate memory for the trainable weights
    std::vector<double> weights(totalWeights);

    // Initialize random engine and distribution
    std::random_device rd;
