typedef struct {
    unsigned int width;
    unsigned int height;
} ImageDimensions;

typedef struct {
    double red, green, blue, alpha;
} Color;

typedef struct {
    ImageDimensions dimensions;
    Color *colormap;
} PlasmaEffectParams;

Image* applyPlasmaEffect(const Image* image, double width, double height, double roughness) {
    // Validate input parameters
    if (image == NULL || width <= 0 || height <= 0 || roughness < 0) {
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Get image dimensions
    unsigned int imgWidth = image->width;
    unsigned int imgHeight = image->height;

    // Create a new image to store the result
    Image* modifiedImage = (Image*)malloc(sizeof(Image));
    if (modifiedImage == NULL) {
        return NULL;
    }
    modifiedImage->width = imgWidth;
    modifiedImage->height = imgHeight;
    modifiedImage->colormap = (Color*)malloc(imgWidth * imgHeight * sizeof(Color));
    if (modifiedImage->colormap == NULL) {
        free(modifiedImage);
        return NULL;
    }

    // Calculate the center of the image
    double centerX = imgWidth / 2.0;
    double centerY = imgHeight / 2.0;

    // Apply plasma effect in four sections
    for (unsigned int y = 0; y < imgHeight; ++y) {
        for (unsigned int x = 0; x < imgWidth; ++x) {
            double distanceToCenterX = fabs(x - centerX);
            double distanceToCenterY = fabs(y - centerY);
            double maxDistance = sqrt(centerX * centerX + centerY * centerY);
            double normalizedDistanceX = distanceToCenterX / (maxDistance / 2.0);
            double normalizedDistanceY = distanceToCenterY / (maxDistance / 2.0);
            double noiseValue = sin((distanceToCenterX - distanceToCenterY) / roughness) + cos((distanceToCenterX + distanceToCenterY) / roughness);
            Color newColor;
            newColor.red = 128 + 127 * noiseValue;
            newColor.green = 128 + 127 * noiseValue;
            newColor.blue = 128 + 127 * noiseValue;
            newColor.alpha = 255; // Fully opaque

            modifiedImage->colormap[y * imgWidth + x] = newColor;
        }
    }

    return modifiedImage;
}
