// Function to convert MD5 hash to hexadecimal string
void md5_to_hex(const unsigned char *hash, char output[33]) {
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&output[i*2], "%02x", hash[i]);
    }
}

// Function to check the length of the input and return appropriate status
int validate_input(const uint8_t *input, size_t length) {
    if (length < 1) {
        return -2; // Input is too short
    }
    return 0; // Input is valid
}

// Function to compute MD5 hash and return as hexadecimal string
int get_md5_hash(const uint8_t *input, size_t length, char output[33]) {
    if (validate_input(input, length) != 0) {
        return -2; // Input validation failed
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input, length, (unsigned char*)hash);

    md5_to_hex(hash, output);
    return 0; // Success
}
