#include <vector>

struct HeightMap {
    int width;
    int height;
    std::vector<int> data;
};

HeightMap* readBitmapAsHeightMap(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open the bitmap file.");
    }

    // Read and validate the bitmap header (simplified for brevity)
    char header[14];
    file.read(header, 14);
    if (file.gcount() != 14 || header[0] != 'B' || header[1] != 'M') {
        throw std::runtime_error("Not a valid bitmap file.");
    }

    // Read the width and height from the bitmap header
    int width = *(int*)(header + 18);
    int height = *(int*)(header + 22);

    // Allocate memory for the height map
    HeightMap* heightMap = new HeightMap();
    heightMap->width = width;
    heightMap->height = height;
    heightMap->data.resize(width * height);

    // Read pixel data and convert to height values
    const int bytesPerPixel = 3; // Assuming 24-bit bitmap (no alpha)
    std::vector<unsigned char> pixels(width * height * bytesPerPixel);
    file.seekg(header[10]); // Skip the header size
    file.read(reinterpret_cast<char*>(pixels.data()), pixels.size());

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            int index = (y * width + x) * bytesPerPixel;
            heightMap->data[y * width + x] = pixels[index]; // Assuming grayscale bitmap
        }
    }

    file.close();
    return heightMap;
}
