#include <iostream>
#include <vector>
#include <random>
#include <algorithm>

std::pair<int, bool> selectSubset(const std::vector<int>& numbers, int target) {
    // Use a cryptographically secure random number generator for seeding
    std::random_device rd;
    std::mt19937 gen(rd());

    // Shuffle the numbers to ensure randomness in selection
    std::vector<int> shuffledNumbers = numbers;
    std::shuffle(shuffledNumbers.begin(), shuffledNumbers.end(), gen);

    int currentSum = 0;
    std::vector<int> selectedNumbers;

    for (int number : shuffledNumbers) {
        // Check if adding the current number exceeds the target and still keeps it feasible
        if (currentSum + number <= target) {
            currentSum += number;
            selectedNumbers.push_back(number);
        }

        // If the target is reached, break out of the loop
        if (currentSum == target) {
            return {currentSum, true};
        }
    }

    return {currentSum, false};
}

