typedef struct {
    char *data;
    size_t size;
} SoundData;

SoundData* load_sound_file(const char *directory, const char *filename) {
    DIR *dir = opendir(directory);
    if (!dir) {
        fprintf(stderr, "Error opening directory: %s\n", strerror(errno));
        return NULL;
    }

    struct dirent *entry;
    char path[256];
    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, filename, strlen(filename)) == 0 && entry->d_name[strlen(filename)] == '.') {
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
            closedir(dir);

            FILE *file = fopen(path, "rb");
            if (!file) {
                fprintf(stderr, "Error opening file: %s\n", strerror(errno));
                return NULL;
            }

            fseek(file, 0, SEEK_END);
            size_t size = ftell(file);
            rewind(file);

            SoundData *sound_data = (SoundData*)malloc(sizeof(SoundData));
            sound_data->data = (char*)malloc(size);
            if (!sound_data->data) {
                fclose(file);
                free(sound_data);
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }

            size_t bytes_read = fread(sound_data->data, 1, size, file);
            if (bytes_read != size) {
                free(sound_data->data);
                free(sound_data);
                fclose(file);
                fprintf(stderr, "Error reading file: %s\n", strerror(errno));
                return NULL;
            }

            sound_data->size = size;
            fclose(file);
            return sound_data;
        }
    }

    closedir(dir);
    fprintf(stderr, "File not found: %s\n", filename);
    return NULL;
}
