char* create_unique_temp_file(const char *prefix, char **temp_filename) {
    // Allocate memory for the temporary filename
    size_t len = strlen(prefix) + 6; // prefix length + "XXXXXX" suffix
    *temp_filename = (char *)malloc(len);
    if (*temp_filename == NULL) {
        return NULL;
    }

    // Create a unique temporary file name
    strncpy(*temp_filename, prefix, len - 6);
    strncat(*temp_filename, "XXXXXX", 6);

