    int fd = mktemp_s(*temp_filename, len - 6);
    if (fd == -1) {
        free(*temp_filename);
        *temp_filename = NULL;
        return NULL;
    }
#endif

    // Ensure the file is created with secure permissions
    fchmod(fd, 0600);

    return *temp_filename;
}

