#include <windows.h>
#include <vector>
#include <string>
#include <algorithm>

std::vector<std::string> listFilesInDirectory(const std::wstring& directoryPath, bool sorted) {
    std::vector<std::string> files;
    HANDLE hFind = INVALID_HANDLE_VALUE;
    WIN32_FIND_DATA ffd;

    // Prepare string for search query.
    wchar_t searchPath[MAX_PATH];
    HRESULT hr = StringCchCopy(searchPath, MAX_PATH, directoryPath.c_str());
    if (FAILED(hr)) {
        return files; // Return empty vector on failure.
    }
    wcscat_s(searchPath, L"\\*");

    // Find the first file in the directory.
    hFind = FindFirstFile(searchPath, &ffd);
    if (hFind == INVALID_HANDLE_VALUE) {
        return files; // Return empty vector on failure.
    }

    do {
        // Skip "." and ".." directories.
        if (wcscmp(ffd.cFileName, L".") != 0 && wcscmp(ffd.cFileName, L"..") != 0) {
            files.push_back(std::string(CW2A(ffd.cFileName)));
        }
    } while (FindNextFile(hFind, &ffd) != 0);

    // Handle any errors from FindNextFile.
    DWORD dwError = GetLastError();
    if (dwError != ERROR_NO_MORE_FILES) {
        return files; // Return empty vector on failure.
    }

    // Close the search handle.
    FindClose(hFind);

    // Optionally sort the file list.
    if (sorted) {
        std::sort(files.begin(), files.end());
    }

    return files;
}
