char* generate_signature(const char* message, const char* secret) {
    // Allocate memory for the signature
    unsigned int length = 20; // HMAC-SHA1 produces a 20-byte hash
    unsigned char digest[length];

    // Create HMAC context
    HMAC_CTX *ctx = HMAC_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Unable to create HMAC context\n");
        return NULL;
    }

    // Initialize HMAC with the secret key
    if (HMAC_Init_ex(ctx, secret, strlen(secret), EVP_sha1(), NULL) != 1) {
        fprintf(stderr, "Unable to initialize HMAC\n");
        HMAC_CTX_free(ctx);
        return NULL;
    }

    // Update the context with the message
    HMAC_Update(ctx, (unsigned char*)message, strlen(message));

    // Finalize and extract the digest
    if (HMAC_Final(ctx, digest, &length) != 1) {
        fprintf(stderr, "Unable to finalize HMAC\n");
        HMAC_CTX_free(ctx);
        return NULL;
    }

    // Free the context
    HMAC_CTX_free(ctx);

    // Encode the digest in Base64
    BIO *bio, *b64;
    BUF_MEM *bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);

    BIO_write(bio, digest, length);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);

    // Allocate memory for the base64 encoded string and copy it
    char *base64_signature = (char *)malloc(bufferPtr->length + 1);
    memcpy(base64_signature, bufferPtr->data, bufferPtr->length);
    base64_signature[bufferPtr->length] = '\0';

    // Clean up
    BIO_free_all(bio);

    return base64_signature;
}
