#include <boost/python.hpp>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string derive_key(const std::string& password, const std::string& master_key, size_t output_length) {
    // Initialize the KDF2 context with SHA-1 hash function
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create KDF2 context");
    }

    if (EVP_DigestInit_ex(ctx, EVP_sha1(), nullptr) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to initialize SHA-1 hash function");
    }

    // Convert password and master key to vectors of bytes
    std::vector<unsigned char> password_bytes(password.begin(), password.end());
    std::vector<unsigned char> master_key_bytes(master_key.begin(), master_key.end());

    // Update the KDF2 context with the master key and password
    if (EVP_DigestUpdate(ctx, master_key_bytes.data(), master_key_bytes.size()) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to update KDF2 context with master key");
    }

    if (EVP_DigestUpdate(ctx, password_bytes.data(), password_bytes.size()) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to update KDF2 context with password");
    }

    // Allocate memory for the derived key
    std::vector<unsigned char> derived_key(output_length);

    // Finalize the KDF2 operation and store the result in derived_key
    unsigned int derived_key_len = 0;
    if (EVP_DigestFinal_ex(ctx, derived_key.data(), &derived_key_len) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to finalize KDF2 operation");
    }

    // Clean up the context
    EVP_MD_CTX_free(ctx);

    // Convert derived key to string and return it
    return std::string(derived_key.begin(), derived_key.end());
}

BOOST_PYTHON_MODULE(kdf2) {
    using namespace boost::python;
    def("derive_key", derive_key);
}
