bool validate_certificate(ParsedCertificate *cert, ParsedCertificate *issuer) {
    // Define supported hash algorithms and their corresponding OIDs
    const EVP_MD* (*hash_algorithms[])(void) = {EVP_md5, EVP_sha1, EVP_sha224, EVP_sha256, EVP_sha384, EVP_sha512};
    const char *oid_names[] = {"md5", "sha1", "sha224", "sha256", "sha384", "sha512"};
