#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Function to read a file and return its contents as a Unicode string
wchar_t* read_file_as_unicode(const char* path) {
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return NULL;
    }

    // Determine the size of the file
    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    if (filesize < 0) {
        fprintf(stderr, "Error determining file size: %s\n", strerror(errno));
        fclose(file);
        return NULL;
    }

    // Allocate memory for the Unicode string buffer
    wchar_t* buffer = (wchar_t*)malloc((filesize + 1) * sizeof(wchar_t));
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        fclose(file);
        return NULL;
    }

    // Read the file content into the buffer
    size_t bytes_read = fread(buffer, sizeof(wchar_t), filesize, file);
    if (bytes_read != filesize) {
        fprintf(stderr, "Error reading file: %s\n", strerror(errno));
        free(buffer);
        buffer = NULL;
        fclose(file);
        return NULL;
    }

    // Null-terminate the buffer
    buffer[filesize] = L'\0';

    // Close the file and return the buffer
    fclose(file);
    return buffer;
}
