int findBestCombination(const std::vector<std::pair<int, bool>>& values, int target) {
    // Seed the random number generator
    std::srand(static_cast<unsigned>(std::time(0)));

    int bestValue = -1;
    int n = values.size();

    // Generate all possible combinations using a bitmask approach
