#include <vector>
#include <cmath>
#include <stdexcept>

class ImageProcessor {
public:
    std::vector<std::vector<double>> convolve(const std::vector<std::vector<double>>& input, const std::vector<std::vector<double>>& filter, double bias) {
        int inputHeight = input.size();
        int inputWidth = input[0].size();
        int filterHeight = filter.size();
        int filterWidth = filter[0].size();

        if (filterHeight > inputHeight || filterWidth > inputWidth) {
            throw std::invalid_argument("Filter size is larger than the input image.");
        }

        int outputHeight = inputHeight - filterHeight + 1;
        int outputWidth = inputWidth - filterWidth + 1;
        std::vector<std::vector<double>> output(outputHeight, std::vector<double>(outputWidth));

        for (int i = 0; i < outputHeight; ++i) {
            for (int j = 0; j < outputWidth; ++j) {
                double sum = bias;
                for (int fi = 0; fi < filterHeight; ++fi) {
                    for (int fj = 0; fj < filterWidth; ++fj) {
                        int inputI = i + fi;
                        int inputJ = j + fj;
                        sum += input[inputI][inputJ] * filter[fi][fj];
                    }
                }
                output[i][j] = std::max(0.0, sum); // ReLU activation function
            }
        }

        return output;
    }
};
