typedef enum {
    TOK_UNKNOWN,
    TOK_NUMBER,
    TOK_STRING,
    TOK_MINUS,
    TOK_QUOTE
} TokenType;

typedef struct {
    TokenType type;
    char *value;
} Token;

int is_whitespace(char c) {
    return c == ' ' || c == '\t' || c == '\n';
}

int is_digit(char c) {
    return c >= '0' && c <= '9';
}

Token get_token(const char **input) {
    while (is_whitespace(**input)) (*input)++;

    if (**input == '\0') {
        Token token;
        token.type = TOK_UNKNOWN;
        token.value = NULL;
        return token;
    }

    if (**input == '-') {
        Token token;
        token.type = TOK_MINUS;
        token.value = strdup("-");
        (*input)++;
        return token;
    }

    if (**input == '"') {
        const char *start = ++(*input);
        while (**input != '\0' && **input != '"') (*input)++;
        if (**input == '"') {
            Token token;
            token.type = TOK_STRING;
            size_t len = (*input) - start;
            char *value = malloc(len + 1);
            strncpy(value, start, len);
            value[len] = '\0';
            token.value = value;
            (*input)++;
            return token;
        }
    }

    if (is_digit(**input)) {
        const char *start = *input;
        while (is_digit(**input)) (*input)++;
        size_t len = *input - start;
        Token token;
        token.type = TOK_NUMBER;
        char *value = malloc(len + 1);
        strncpy(value, start, len);
        value[len] = '\0';
        token.value = value;
        return token;
    }

    Token token;
    token.type = TOK_UNKNOWN;
    token.value = NULL;
    (*input)++;
    return token;
}

Token *parse_multiline_string(const char *input, int *token_count) {
    const char *ptr = input;
    while (is_whitespace(*ptr)) ptr++;
    const char *start = ptr;
    while (*ptr != '\0') ptr++;
    while (is_whitespace(*(ptr - 1))) ptr--;

    int capacity = 10;
    Token *tokens = malloc(capacity * sizeof(Token));
    *token_count = 0;

    while (start < ptr) {
        Token token = get_token(&start);
        if (token.type != TOK_UNKNOWN) {
            if (*token_count >= capacity) {
                capacity *= 2;
                tokens = realloc(tokens, capacity * sizeof(Token));
            }
            tokens[*token_count] = token;
            (*token_count)++;
        }
    }

    return tokens;
}

void free_tokens(Token *tokens, int count) {
    for (int i = 0; i < count; i++) {
        if (tokens[i].value != NULL) {
            free(tokens[i].value);
        }
    }
    free(tokens);
}

int main() {
