struct Option {
    std::string name;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& input) {
    std::vector<Option> options;
    Option option;
    size_t pos = 0;
    size_t commaPos = 0;

    while ((commaPos = input.find(',', pos)) != std::string::npos) {
        std::string token = input.substr(pos, commaPos - pos);
        size_t eqPos = token.find('=');

        if (eqPos == std::string::npos || eqPos == 0 || eqPos == token.size() - 1) {
            // Malformed key-value pair
            continue;
        }

        option.name = token.substr(0, eqPos);
        option.value = token.substr(eqPos + 1);

        // Validate the key and value
        if (option.name.empty() || option.value.empty()) {
            continue;
        }

        options.push_back(option);
        pos = commaPos + 1;
