    std::string lastToken = input.substr(pos);
    size_t eqPos = lastToken.find('=');

    if (eqPos != std::string::npos && eqPos > 0 && eqPos < lastToken.size() - 1) {
        option.name = lastToken.substr(0, eqPos);
        option.value = lastToken.substr(eqPos + 1);

        // Validate the key and value
