#include <iostream>
#include <vector>
#include <string>
#include <regex>

std::vector<std::string> parseURL(const std::string& url) {
    std::vector<std::string> components;
    std::regex url_pattern("^([a-zA-Z]+://)?([^/:]+)(:(\\d+))?(/[\\S]*)?$");
    std::smatch match;

    if (std::regex_search(url, match, url_pattern)) {
        if (match.size() > 0) {
            for (int i = 1; i < match.size(); ++i) {
                components.push_back(match[i].str());
            }
        }
    } else {
        // Handle invalid URL
        std::cerr << "Invalid URL" << std::endl;
        return {};
    }

    if (components.size() < 2) {
        std::cerr << "URL components not found" << std::endl;
        return {};
    }

    // Ensure protocol is present and valid
    if (components[0].empty()) {
        std::cerr << "Protocol missing or invalid" << std::endl;
        return {};
    }

    // Ensure host is present
    if (components[1].empty()) {
        std::cerr << "Host not found in URL" << std::endl;
        return {};
    }

    return components;
