#include <skia/core/SkPathEffect.h>
#include <skia/core/SkScalar.h>
#include <stdlib.h>

struct SkDashPathEffect {
    SkScalar* fIntervals;
    int fCount;
    SkScalar fIntervalLength;
    SkScalar fPhase;
    bool fScaleToFit;
};

SkDashPathEffect* CreateDashPathEffect(const SkScalar intervals[], int count, SkScalar phase, bool scaleToFit) {
    if (count <= 0 || intervals == NULL) {
        return NULL;
    }

    // Allocate memory for the intervals using sk_malloc_throw
    SkScalar* allocatedIntervals = (SkScalar*)sk_malloc_throw(count * sizeof(SkScalar));
    if (!allocatedIntervals) {
        return NULL;
    }

    // Copy the intervals to the newly allocated memory
    for (int i = 0; i < count; ++i) {
        allocatedIntervals[i] = intervals[i];
    }

    // Calculate the total length of the intervals
    SkScalar totalLength = 0;
    for (int i = 0; i < count; ++i) {
        totalLength += intervals[i];
    }

    // Create and initialize the SkDashPathEffect struct
    SkDashPathEffect* effect = (SkDashPathEffect*)sk_malloc_throw(sizeof(SkDashPathEffect));
    if (!effect) {
        sk_free((void*)allocatedIntervals);
        return NULL;
    }

    effect->fIntervals = allocatedIntervals;
    effect->fCount = count;
    effect->fIntervalLength = totalLength;
    effect->fPhase = phase;
    effect->fScaleToFit = scaleToFit;

    return effect;
}
