#include <iostream>
#include <iomanip>
#include <sstream>
#include <vector>
#include <openssl/hmac.h>
#include <openssl/sha.h>

std::string sha256_hmac(const std::string& message, const std::string& secret) {
    unsigned char* digest = HMAC(EVP_sha256(), secret.c_str(), secret.size(), 
                                 reinterpret_cast<const unsigned char*>(message.c_str()), 
                                 message.size(), nullptr, nullptr);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setfill('0') << std::setw(2) << static_cast<int>(digest[i]);
    }
    delete[] digest;
    return ss.str();
}
