#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <sstream>
#include <iomanip>

struct DataPoint {
    double x;
    double y;
};

std::vector<DataPoint> readDataset(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open the file.");
    }

    std::vector<DataPoint> data;
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        DataPoint point;
        if (!(iss >> point.x >> point.y)) {
            throw std::runtime_error("Invalid data format in the file.");
        }
        data.push_back(point);
    }

    return data;
}

void linearRegression(const std::vector<DataPoint>& data, double& slope, double& intercept) {
    if (data.empty()) {
        throw std::invalid_argument("The dataset is empty.");
    }

    double sumX = 0, sumY = 0, sumXY = 0, sumXX = 0;
    size_t n = data.size();

    for (const auto& point : data) {
        sumX += point.x;
        sumY += point.y;
        sumXY += point.x * point.y;
        sumXX += point.x * point.x;
    }

    slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    intercept = (sumY - slope * sumX) / n;
}

int main() {
    std::string filename;
    std::cout << "Enter the filename of the dataset: ";
    std::cin >> filename;

    try {
        auto data = readDataset(filename);
        double slope, intercept;
        linearRegression(data, slope, intercept);

        std::cout << "Number of data points: " << data.size() << std::endl;
        std::cout << "Slope: " << std::fixed << std::setprecision(2) << slope << std::endl;
        std::cout << "Intercept: " << std::fixed << std::setprecision(2) << intercept << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
