template<typename T>
class DynamicArray {
private:
    T* data;
    size_t capacity;
    size_t size;

public:
    DynamicArray(size_t initialCapacity = 10) : capacity(initialCapacity), size(0) {
        data = static_cast<T*>(std::malloc(capacity * sizeof(T)));
        if (!data) {
            throw std::bad_alloc();
        }
    }

    ~DynamicArray() {
        std::free(data);
    }

    void push_back(const T& value) {
        if (size >= capacity) {
            size_t newCapacity = capacity * 2;
            T* newData = static_cast<T*>(std::realloc(data, newCapacity * sizeof(T)));
            if (!newData) {
                throw std::bad_alloc();
            }
            data = newData;
            capacity = newCapacity;
        }
        data[size++] = value;
    }

    T& operator[](size_t index) {
        if (index >= size) {
            throw std::out_of_range("Index out of range");
        }
        return data[index];
    }

    const T& operator[](size_t index) const {
        if (index >= size) {
            throw std::out_of_range("Index out of range");
        }
        return data[index];
    }
};

