    }

    // Equality operator==
    bool operator==(const SecureString& rhs) const {
        return data_ == rhs.data_;
    }

    // Append operator+=
    SecureString& operator+=(const SecureString& rhs) {
        data_.append(rhs.data_);
        return *this;
    }

    // Clear the string
    void clear() {
        for (size_t i = 0; i < data_.length(); ++i) {
            data_[i] = '\0';
        }
        data_.clear();
    }

private:
    std::string data_;

    // Convert Unicode string to ANSI string
    static std::string convertToAnsi(const std::wstring& wstr) {
        if (wstr.empty()) return "";

        int len = WideCharToMultiByte(CP_ACP, 0, wstr.c_str(), -1, NULL, 0, NULL, NULL);
        if (len == 0) return "";

        std::string ansiStr(len, '\0');
        WideCharToMultiByte(CP_ACP, 0, wstr.c_str(), -1, &ansiStr[0], len, NULL, NULL);

        return ansiStr;
    }

    // Helper function to swap two SecureString objects
    friend void swap(SecureString& lhs, SecureString& rhs) {
        using std::swap;
        swap(lhs.data_, rhs.data_);
    }
};
