#include <stdlib.h>
#include <math.h>

typedef struct {
    float x, y, z;
} Point;

Point* compute_normals(Point* points, size_t num_points) {
    // Allocate memory for the normals array using alloca
    Point* normals = (Point*)alloca(num_points * sizeof(Point));

    if (normals == NULL) {
        return NULL; // Allocation failed
    }

    for (size_t i = 0; i < num_points; ++i) {
        Point p1 = points[i];
        Point p0 = points[(i + num_points - 1) % num_points];

        // Calculate the difference vector p1 - p0
        float dx = p1.x - p0.x;
        float dy = p1.y - p0.y;
        float dz = p1.z - p0.z;

        // Compute the length of the difference vector
        float length = sqrtf(dx * dx + dy * dy + dz * dz);

        if (length == 0) {
            return NULL; // Avoid division by zero
        }

        // Calculate the normal vector
        normals[i].x = dx / length;
        normals[i].y = dy / length;
        normals[i].z = dz / length;
    }

    return normals;
}
