#include <stdlib.h>
#include <string.h>

wchar_t* read_file_as_unicode(const wchar_t* path) {
    FILE* file;
    size_t filesize, num_read;
    wchar_t* buffer;

    // Open the file for reading
    if ((file = _wfopen(path, L"r")) == NULL) {
        perror("Error opening file");
        return NULL;
    }

    // Get the size of the file
    if (fseek(file, 0, SEEK_END) != 0 || (filesize = ftell(file)) < 0 || fseek(file, 0, SEEK_SET) != 0) {
        perror("File error");
        fclose(file);
        return NULL;
    }

    // Allocate memory for the buffer
    if ((buffer = (wchar_t*)malloc((filesize + 1) * sizeof(wchar_t))) == NULL) {
        perror("Error allocating memory");
        fclose(file);
        return NULL;
    }

    // Read the file content into the buffer
    num_read = fread(buffer, sizeof(wchar_t), filesize, file);
    if (ferror(file) != 0) {
        perror("Error reading file");
        free(buffer);
        fclose(file);
        return NULL;
    }

