#define MAX_MESSAGE_SIZE 1024

void handle_message(int sock) {
    char buffer[MAX_MESSAGE_SIZE];
    ssize_t bytes_received = recv(sock, buffer, sizeof(buffer), 0);
    if (bytes_received <= 0) {
        perror("recv");
        return;
    }

    // Null-terminate the received data to safely handle it as a string
    buffer[bytes_received] = '\0';

    // Extract user ID from the message
    char user_id[64];
    if (sscanf(buffer, "USERID:%63s", user_id) != 1) {
        fprintf(stderr, "Failed to extract user ID\n");
        return;
    }

    // Append a reply to the message
    char reply[MAX_MESSAGE_SIZE];
    snprintf(reply, sizeof(reply), "REPLY: Hello %s", user_id);

    // Send the reply back to the sender using BREPLYX function (pseudo-function)
    if (send(sock, reply, strlen(reply), 0) < 0) {
        perror("send");
    }
}

