#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_NODES 100

int** createGraph(int nodes) {
    int **graph = (int**)malloc(nodes * sizeof(int*));
    for (int i = 0; i < nodes; i++) {
        graph[i] = (int*)calloc(nodes, sizeof(int));
    }
    return graph;
}

void addEdge(int** graph, int src, int dest) {
    graph[src][dest] = 1;
    graph[dest][src] = 1; // Assuming undirected graph
}

int* bfsShortestPath(int** graph, int nodes, int start) {
    bool visited[MAX_NODES];
    int distance[MAX_NODES];
    int parent[MAX_NODES];

    for (int i = 0; i < nodes; i++) {
        visited[i] = false;
        distance[i] = -1; // Not reachable
        parent[i] = -1;
    }

    int* queue = (int*)malloc(nodes * sizeof(int));
    int front = 0, rear = 0;

    visited[start] = true;
    distance[start] = 0;
    queue[rear++] = start;

    while (front < rear) {
        int current = queue[front++];

        for (int neighbor = 0; neighbor < nodes; neighbor++) {
            if (graph[current][neighbor] == 1 && !visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[current] + 1;
                parent[neighbor] = current;
                queue[rear++] = neighbor;
            }
        }
    }

    free(queue);

    // Reconstruct the path if needed
    int* path = (int*)malloc((nodes) * sizeof(int));
    int pathIndex = 0;
    for (int v = start; v != -1; v = parent[v]) {
        path[pathIndex++] = v;
    }

    // Reverse the path to get it from start to end
    for (int i = 0; i < pathIndex / 2; i++) {
        int temp = path[i];
        path[i] = path[pathIndex - i - 1];
        path[pathIndex - i - 1] = temp;
    }

    // Check if the end node is reachable
    if (distance[path[pathIndex - 1]] == -1) {
        free(path);
        return NULL;
    }

    return path;
}

void destroyGraph(int** graph, int nodes) {
    for (int i = 0; i < nodes; i++) {
        free(graph[i]);
    }
    free(graph);
}

int main() {
    int nodes = 5;
    int** graph = createGraph(nodes);

    addEdge(graph, 0, 1);
    addEdge(graph, 0, 2);
    addEdge(graph, 1, 2);
    addEdge(graph, 1, 3);
    addEdge(graph, 2, 4);

    int* path = bfsShortestPath(graph, nodes, 0);

    if (path != NULL) {
        printf("Shortest path: ");
        for (int i = 0; i < MAX_NODES && path[i] != -1; i++) {
            printf("%d ", path[i]);
        }
        printf("\n");
    } else {
        printf("No path exists.\n");
    }

    destroyGraph(graph, nodes);
    free(path);

    return 0;
}
