#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALPHABET_SIZE 256

typedef struct TrieNode {
    int count;
    struct TrieNode* children[ALPHABET_SIZE];
} TrieNode;

TrieNode* createNode() {
    TrieNode* node = (TrieNode*)malloc(sizeof(TrieNode));
    if (node) {
        node->count = 0;
        for (int i = 0; i < ALPHABET_SIZE; i++) {
            node->children[i] = NULL;
        }
    }
    return node;
}

void insert(TrieNode* root, const char* key) {
    TrieNode* current = root;
    for (int i = 0; i < strlen(key); i++) {
        int index = key[i];
        if (!current->children[index]) {
            current->children[index] = createNode();
        }
        current = current->children[index];
    }
    current->count++;
}

void countOccurrences(TrieNode* root, int* result, int index) {
    if (root->count > 0) {
        result[index] = root->count;
    }
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (root->children[i]) {
            countOccurrences(root->children[i], result, index + 1);
        }
    }
}

int* getCharacterCounts(const char* str) {
    TrieNode* root = createNode();
    for (int i = 0; i < strlen(str); i++) {
        insert(root, &str[i]);
    }

    int* result = (int*)calloc(ALPHABET_SIZE, sizeof(int));
    countOccurrences(root, result, 0);

    // Free the trie nodes to avoid memory leaks
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (root->children[i]) {
            free(root->children[i]);
        }
