int* reduce_and_sort(const int* input, size_t count, size_t *output_count) {
    if (count == 0) {
        *output_count = 0;
        return NULL;
    }

    // Allocate memory for the unique entries and their indexes
    int* unique_entries = malloc(count * sizeof(int));
    int* unique_indexes = malloc(count * sizeof(int));
    if (!unique_entries || !unique_indexes) {
        free(unique_entries);
        free(unique_indexes);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Use a hash set to track unique entries
    int* observed = calloc(count, sizeof(int));
    if (!observed) {
        free(unique_entries);
        free(unique_indexes);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t unique_index = 0;
    for (size_t i = 0; i < count; ++i) {
        int item = input[i];
        // Check if the entry is already observed
        int found = 0;
        for (size_t j = 0; j < unique_index; ++j) {
            if (observed[j] == item) {
                found = 1;
                break;
            }
        }
        if (!found) {
            observed[unique_index] = item;
            unique_entries[unique_index] = item;
            unique_indexes[unique_index] = i;
            ++unique_index;
        }
    }

    // Free the observed array as it's no longer needed
    free(observed);

    // Sort the unique entries by their original index
    for (size_t i = 0; i < unique_index - 1; ++i) {
        for (size_t j = i + 1; j < unique_index; ++j) {
