            std::vector<float>& block = blocks[ch];
            std::vector<float>& searchBlock = searchBlocks[ch];

            size_t blockStart = 0;
            while (blockStart + windowSize <= block.size()) {
                for (int i = 0; i < windowSize; ++i) {
                    audioBus.data[(blockStart + i) * numChannels + ch] += block[blockStart + i];
                }
                blockStart += hopSize;
            }
        }

        return audioBus;
    }

    void addBlock(const std::vector<float>& block, int channel) {
