#include <string.h>

typedef enum {
    ENDPOINT_ID_INVALID,
    ENDPOINT_ID_VALID
} EndpointIdStatus;

EndpointIdStatus validate_endpoint_id(const char *endpoint_id) {
    // Basic validation: check if the endpoint ID is not NULL and has at least one character
    if (endpoint_id == NULL || strlen(endpoint_id) == 0) {
        return ENDPOINT_ID_INVALID;
    }
    return ENDPOINT_ID_VALID;
}

char *parse_endpoint_id(const char *endpoint_id, int *portno, EndpointIdStatus *status) {
    if (validate_endpoint_id(endpoint_id) == ENDPOINT_ID_INVALID) {
        *status = ENDPOINT_ID_INVALID;
        return NULL;
    }

    // Find the position of the colon to separate host and port
    const char *colon = strchr(endpoint_id, ':');
    if (colon == NULL || colon == endpoint_id) {
        *status = ENDPOINT_ID_INVALID;
        return NULL;
    }

    // Extract the port number
    char *endptr;
    long temp_portno = strtol(colon + 1, &endptr, 10);
    if (*endptr != '\0') {
        *status = ENDPOINT_ID_INVALID;
        return NULL;
    }
    *portno = (int)temp_portno;

    // Allocate memory for the host part and copy it
    size_t host_len = colon - endpoint_id;
    char *host = (char *)malloc(host_len + 1);
    if (host == NULL) {
        *status = ENDPOINT_ID_INVALID;
        return NULL;
    }
    strncpy(host, endpoint_id, host_len);
    host[host_len] = '\0';

    *status = ENDPOINT_ID_VALID;
    return host;
}
