#include <vector>
#include <random>
#include <iostream>

class InputDataMatrix {
public:
    enum DataType { DENSE, SPARSE, SEQUENCE };

    InputDataMatrix(int batch_size, int input_dim, DataType type)
        : batch_size_(batch_size), input_dim_(input_dim), type_(type) {
        data_.resize(batch_size * input_dim);
        initializeData();
    }

    const std::vector<double>& getData() const { return data_; }

private:
    void initializeData() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(-1.0, 1.0);

        switch (type_) {
            case DENSE:
                for (auto& value : data_) {
                    value = dis(gen);
                }
                break;
            case SPARSE:
                for (int i = 0; i < batch_size_; ++i) {
                    int index = gen() % input_dim_;
                    data_[i * input_dim_ + index] = dis(gen);
                }
                break;
            case SEQUENCE:
                for (int i = 0; i < batch_size_; ++i) {
                    double value = dis(gen);
                    for (int j = 0; j < input_dim_; ++j) {
                        data_[i * input_dim_ + j] = value;
                    }
                }
                break;
            default:
                std::cerr << "Unknown data type" << std::endl;
                exit(EXIT_FAILURE);
        }
    }

    int batch_size_;
    int input_dim_;
    DataType type_;
    std::vector<double> data_;
};

int main() {
    InputDataMatrix matrix(3, 4, InputDataMatrix::DENSE);
    const auto& data = matrix.getData();
    for (const auto& value : data) {
        std::cout << value << " ";
    }
    return 0;
}
