#include <vector>
#include <cassert>

std::vector<std::vector<double>> addBorderValue(const std::vector<std::vector<double>>& inputArray, double borderValue) {
    // Check if the input array is empty or has zero rows/columns
    if (inputArray.empty() || inputArray[0].empty()) {
        return inputArray;
    }

    int numRows = inputArray.size();
    int numCols = inputArray[0].size();
    std::vector<std::vector<double>> result(numRows + 2 * (borderValue != 0), std::vector<double>(numCols + 2 * (borderValue != 0)));

    for (int i = 0; i < numRows; ++i) {
        for (int j = 0; j < numCols; ++j) {
            result[i + (borderValue != 0)][j + (borderValue != 0)] = inputArray[i][j] + borderValue;
