        for (int i = 0; i < numRows; ++i) {
            result[i][0] += inputArray[i][0];
            result[i][numCols - 1] += inputArray[i][numCols - 1];
        }
        for (int j = 0; j < numCols; ++j) {
            result[0][j] += inputArray[0][j];
            result[numRows - 1][j] += inputArray[numRows - 1][j];
        }
    }

    return result;
}
