#include <vector>
#include <iostream>
#include <cmath>

std::vector<std::vector<uchar>> applyGaussianFilter(const std::vector<std::vector<uchar>>& image, int width, int height, const std::vector<double>& kernel) {
    // Validate inputs
    if (kernel.empty() || width <= 0 || height <= 0 || image.empty()) {
        throw std::invalid_argument("Invalid input parameters");
    }

    // Create output image
    std::vector<std::vector<uchar>> filteredImage(height, std::vector<uchar>(width));

    int kernelSize = kernel.size();
    double sumKernel = 0.0;
    for (double value : kernel) {
        sumKernel += value;
    }

    // Normalize the kernel if necessary
    if (sumKernel != 1.0) {
        for (double& value : kernel) {
            value /= sumKernel;
        }
    }

    // Apply horizontal filter
    std::vector<std::vector<double>> tempImage(height, std::vector<double>(width));
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            double sum = 0.0;
            for (int k = -kernelSize / 2; k <= kernelSize / 2; ++k) {
                int xPos = x + k;
                if (xPos >= 0 && xPos < width) {
                    sum += image[y][xPos] * kernel[kernelSize / 2 + k];
                }
            }
            tempImage[y][x] = sum;
        }
    }

    // Apply vertical filter
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            double sum = 0.0;
            for (int k = -kernelSize / 2; k <= kernelSize / 2; ++k) {
                int yPos = y + k;
                if (yPos >= 0 && yPos < height) {
                    sum += tempImage[yPos][x] * kernel[kernelSize / 2 + k];
                }
            }
            filteredImage[y][x] = static_cast<uchar>(std::round(sum));
        }
    }

    return filteredImage;
}
