#include <librealsense2/rs.hpp>
#include <ros/ros.h>
#include <sensor_msgs/Image.h>
#include <sensor_msgs/PointCloud2.h>
#include <cv_bridge/cv_bridge.h>
#include <opencv2/opencv.hpp>

class RealSenseNode {
public:
    RealSenseNode(ros::NodeHandle& nh) : nh_(nh), it_(nh_) {
        // Initialize RealSense pipeline
        rs2::pipeline pipe;
        rs2::config cfg;
        cfg.enable_stream(RS2_STREAM_DEPTH, 640, 480, RS2_FORMAT_Z16, 30);
        cfg.enable_stream(RS2_STREAM_COLOR, 640, 480, RS2_FORMAT_BGR8, 30);
        pipe.start(cfg);

        // Allocate memory for frame buffers
        depth_frame_buffer_.create(480, 640, CV_16UC1);
        color_frame_buffer_.create(480, 640, CV_8UC3);
    }

private:
    void publishFrames() {
        rs2::frameset frames = pipe_.wait_for_frames();
        rs2::depth_frame depth_frame = frames.get_depth_frame();
        rs2::video_frame color_frame = frames.get_color_frame();

        // Convert RealSense frame to OpenCV format
        cv::Mat depth_image(cv::Size(640, 480), CV_16UC1, (void*)depth_frame.get_data(), cv::Mat::AUTO_STEP);
        cv::Mat color_image(cv::Size(640, 480), CV_8UC3, (void*)color_frame.get_data(), cv::Mat::AUTO_STEP);

        // Publish depth image
        sensor_msgs::ImagePtr depth_msg = cv_bridge::CvImage(std_msgs::Header(), "16UC1", depth_image).toImageMsg();
        depth_pub_.publish(depth_msg);

        // Publish color image
        sensor_msgs::ImagePtr color_msg = cv_bridge::CvImage(std_msgs::Header(), "bgr8", color_image).toImageMsg();
        rgb_pub_.publish(color_msg);
    }

    void advertiseTopics() {
        depth_pub_ = it_.advertise("depth_image", 1);
        rgb_pub_ = it_.advertise("rgb_image", 1);
    }

private:
    ros::NodeHandle nh_;
    image_transport::ImageTransport it_;
    image_transport::Publisher depth_pub_, rgb_pub_;
    cv::Mat depth_frame_buffer_, color_frame_buffer_;
    rs2::pipeline pipe_;
};

int main(int argc, char** argv) {
    ros::init(argc, argv, "realsense_node");
    ros::NodeHandle nh;
    RealSenseNode realsense_node(nh);
    ros::Rate loop_rate(30);

    while (ros::ok()) {
        realsense_node.publishFrames();
        ros::spinOnce();
        loop_rate.sleep();
    }

    return 0;
}
