#include <vector>
#include <unordered_set>

class DisjointSetUnion {
public:
    void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

private:
    std::unordered_map<int, int> parent;
    std::unordered_map<int, int> rank;
};

bool areElementsPairwiseConnected(const std::vector<int>& vec1, const std::vector<int>& vec2) {
    DisjointSetUnion dsu;

    // Initialize DSU with elements from the first vector
    for (int elem : vec1) {
        dsu.makeSet(elem);
    }

    // Union elements in the second vector based on connections found in the first vector
    for (size_t i = 0; i < vec2.size(); ++i) {
        for (size_t j = i + 1; j < vec2.size(); ++j) {
            if (dsu.find(vec2[i]) != dsu.find(vec2[j])) {
                dsu.unionSets(vec2[i], vec2[j]);
            }
        }
    }

    // Check pairwise connections in the second vector
    for (size_t i = 0; i < vec2.size(); ++i) {
        for (size_t j = i + 1; j < vec2.size(); ++j) {
            if (dsu.find(vec2[i]) != dsu.find(vec2[j])) {
                return false; // Found a pair that are not connected
            }
        }
    }

    return true; // All pairs are connected
}
