#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>

// Callback function prototype
typedef void (*LogCallback)(const char *message);

// Function to format a message and call a callback with the formatted message
void log_formatted_message(const char *format, va_list args, LogCallback callback) {
    // Buffer size for the formatted message
    const size_t buffer_size = 1024;
    char buffer[buffer_size];

    // Format the message using vsnprintf
    int result = vsnprintf(buffer, buffer_size, format, args);

    if (result < 0) {
        // Handle error in formatting
        fprintf(stderr, "Error formatting log message\n");
        return;
    }

    // Check if the formatted message fits in the buffer
    if ((size_t)result >= buffer_size) {
        // Allocate memory for the large message
        char *large_message = (char *)malloc(result + 1);
        if (large_message == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Format the message again to ensure it fits in the allocated memory
        result = vsnprintf(large_message, result + 1, format, args);
        if (result < 0) {
            fprintf(stderr, "Error formatting log message\n");
            free(large_message);
            return;
        }

        // Call the callback with the large message
        callback(large_message);

        // Free the allocated memory
        free(large_message);
    } else {
        // Call the callback with the formatted message
        callback(buffer);
    }
}
