public class ConfigurationLoader
{
    public static int LoadConfigValue(string settingName)
    {
        // Ensure the XML file path is within a safe directory
        string xmlFilePath = Path.Combine(AppContext.BaseDirectory, "config.xml");
        if (!Path.GetFullPath(xmlFilePath).StartsWith(AppContext.BaseDirectory))
        {
            throw new ArgumentException("Invalid file path");
        }

        // Create an XmlDocument and load the XML file
        XmlDocument xmlDoc = new XmlDocument();
        try
        {
