        {
            throw new Exception("Failed to load configuration file", ex);
        }

        // Disable external entity loading
        XmlReaderSettings settings = new XmlReaderSettings();
        settings.DtdProcessing = DtdProcessing.Prohibit;
        using (XmlReader reader = XmlReader.Create(new StringReader(xmlDoc.OuterXml), settings))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == "setting")
                {
                    string name = reader["name"];
                    if (name != null && name == settingName)
                    {
                        string valueStr = reader.ReadInnerXml();
                        try
                        {
