                        }
                        catch (FormatException ex)
                        {
                            throw new Exception("Invalid configuration value", ex);
                        }
                    }
                }
            }
        }

        // If the setting is not found, throw an exception
        throw new ArgumentException($"Setting '{settingName}' not found");
    }
}
