using System;
using System.Collections.Generic;
using System.Linq;

public class RandomElementGenerator<T>
{
    private readonly Random _random = new Random();

    public IEnumerable<T> GetRandomElements(IList<T> inputList, int count)
    {
        if (inputList == null || !inputList.Any())
            throw new ArgumentException("Input list cannot be null or empty.");

        if (count <= 0 || count > inputList.Count)
            throw new ArgumentOutOfRangeException(nameof(count), "Count must be between 1 and the size of the input list.");

        var indices = GenerateUniqueRandomIndices(inputList.Count, count);
        return indices.Select(index => inputList[index]);
    }

    private List<int> GenerateUniqueRandomIndices(int maxIndex, int count)
    {
        var indices = new HashSet<int>();
        while (indices.Count < count)
        {
            int index = _random.Next(maxIndex);
            if (!indices.Contains(index))
                indices.Add(index);
        }
        return indices.ToList();
    }
}
