using System;
using System.Security.Cryptography;
using System.Text;

public class TripleDESHelper
{
    public static string DecodeBase64AndDecrypt(string encodedMessage, byte[] key, byte[] iv)
    {
        // Validate input parameters
        if (encodedMessage == null || key == null || iv == null)
        {
            throw new ArgumentNullException("Input parameters cannot be null.");
        }

        try
        {
            // Decode the Base64 encoded message
            byte[] decodedBytes = Convert.FromBase64String(encodedMessage);

            // Create a TripleDES object with the given key and IV
            using (TripleDES tripleDes = TripleDES.Create())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;
                tripleDes.Mode = CipherMode.CBC;
                tripleDes.Padding = PaddingMode.PKCS7;

                // Create a decryptor from the TripleDES object
