                // Decrypt the message
                byte[] decryptedBytes = decryptor.TransformFinalBlock(decodedBytes, 0, decodedBytes.Length);

                // Convert the decrypted bytes to a string and return it
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (Exception ex)
        {
            // Log the exception or handle it as needed
            throw new CryptographicException("Failed to decrypt the message.", ex);
        }
    }
}
