using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

public class CommandExecutor
{
    public async Task ExecuteCommandAsync(string commandFormat, string keyFilePath)
    {
        try
        {
            // Validate the format string and key file path to ensure they are safe for use
            if (string.IsNullOrEmpty(commandFormat) || string.IsNullOrEmpty(keyFilePath))
            {
                throw new ArgumentException("Invalid arguments provided.");
            }

            // Construct the command using the format string and key file path
            string command = string.Format(commandFormat, keyFilePath);

            // Create a ProcessStartInfo object to configure the process
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = "cmd.exe", // Use cmd.exe for Windows (assuming Command Prompt)
                Arguments = $"/c {command}",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            // Start the process
            using (Process process = new Process { StartInfo = startInfo })
            {
                process.Start();

                // Read output and error streams asynchronously
                Task<string> outputTask = process.StandardOutput.ReadToEndAsync();
                Task<string> errorTask = process.StandardError.ReadToEndAsync();

                // Wait for both tasks to complete
                await Task.WhenAll(outputTask, errorTask);

                // Output the results
                Console.WriteLine(outputTask.Result);
                Console.WriteLine("Errors:");
                Console.WriteLine(errorTask.Result);

                // Wait for the process to exit
                await process.WaitForExitAsync();
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
