    {
        _objectRepository = objectRepository ?? throw new ArgumentNullException(nameof(objectRepository));
        _mapper = mapper ?? throw new ArgumentNullException(nameof(mapper));
    }

    public async Task<int> SaveObjectAsync(ViewModel viewModel)
    {
        if (viewModel == null)
        {
            throw new ArgumentNullException(nameof(viewModel));
        }

        // Map the ViewModel to the domain object
        var domainObject = _mapper.Map<DomainObject>(viewModel);

        // Save the domain object to the database using the repository pattern
        await _objectRepository.AddAsync(domainObject);
        await _objectRepository.SaveChangesAsync();

        // Return the saved object's ID
        return domainObject.Id;
    }
}
