using UnityEngine;

public class GameObjectTransformer : MonoBehaviour
{
    public enum IntersectionType
    {
        ThreeWay,
        Turn
    }

    public void RotateTransform(Transform transformComponent, IntersectionType intersectionType)
    {
        switch (intersectionType)
        {
            case IntersectionType.ThreeWay:
                // Randomly rotate by 90 or -90 degrees
                int randomRotation = UnityEngine.Random.Range(0, 2);
                if (randomRotation == 0)
                {
                    transformComponent.Rotate(Vector3.up, 90f);
                }
                else
                {
                    transformComponent.Rotate(Vector3.up, -90f);
                }
                break;
            case IntersectionType.Turn:
                // Always rotate by -90 degrees
                transformComponent.Rotate(Vector3.up, -90f);
                break;
        }
    }
}
