public class SecureCassandraOperations
{
    public void ExecuteInsertStatement(Session session, byte[] incomingPayload, Dictionary<string, byte[]> payloadDictionary)
    {
        // Ensure the incoming payload is not null and has elements
        if (incomingPayload == null || incomingPayload.Length == 0)
        {
            throw new ArgumentException("Incoming payload cannot be null or empty.");
        }

        // Validate that the outgoing payload dictionary contains the expected keys and values
        foreach (var kvp in payloadDictionary)
        {
            if (!payloadDictionary.ContainsKey(kvp.Key))
            {
                throw new ArgumentException($"Outgoing payload is missing key: {kvp.Key}");
            }

            // Compare the contents of the outgoing payload with the incoming payload
            if (payloadDictionary[kvp.Key].Length != incomingPayload.Length)
            {
                throw new ArgumentException("The number of elements in the outgoing and incoming payloads do not match.");
            }

            for (int i = 0; i < incomingPayload.Length; i++)
            {
                if (payloadDictionary[kvp.Key][i] != incomingPayload[i])
                {
                    throw new ArgumentException("The contents of the outgoing and incoming payloads do not match.");
                }
            }
        }

