using System;
using System.Diagnostics;
using System.IO;
using System.Threading;

public class ProcessManager
{
    public void StartProcessWithTracking(ProcessStartInfo startInfo, string trackingFolderPath, int timeout)
    {
        if (!Directory.Exists(trackingFolderPath))
        {
            throw new InvalidOperationException("The tracking folder does not exist.");
        }

        var process = new Process
        {
            StartInfo = startInfo
        };

        string pidFilePath = Path.Combine(trackingFolderPath, "process.pid");

        try
        {
            process.Start();
            File.WriteAllText(pidFilePath, process.Id.ToString());

            var sentinelProcess = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = "sentinel.exe",
                    Arguments = $"{process.Id} {timeout}"
                }
            };

            sentinelProcess.Start();

            if (!process.WaitForExit(timeout))
            {
                process.Kill();
                process.WaitForExit();
                File.Delete(pidFilePath);
                sentinelProcess.Kill();
                sentinelProcess.WaitForExit();
                throw new TimeoutException("The process did not complete within the specified timeout.");
            }
        }
        catch (Exception ex)
        {
            File.Delete(pidFilePath);
            throw;
        }
    }
}
