public class SecureCassandraClient
{
    private readonly Session _session;

    public SecureCassandraClient(Session session)
    {
        _session = session ?? throw new ArgumentNullException(nameof(session));
    }

    public async Task<List<Row>> ExecuteQueryAsync(string query, IDictionary<string, object> parameters)
    {
