public class SecureDecryption
{
    public static string DecryptMessage(string encryptedMessage, string key)
    {
        if (encryptedMessage == null || key == null)
        {
            throw new ArgumentNullException("Input parameters cannot be null.");
        }

        // Ensure the key length is valid for DES
        if (key.Length != 8)
        {
