using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;

public class RequestProcessor : ControllerBase
{
    private readonly ICache _cache;
    private static readonly HashSet<string> ValidMethods = new HashSet<string> { "GET", "POST", "PUT", "DELETE" };

    public RequestProcessor(ICache cache)
    {
        _cache = cache;
    }

    [HttpGet]
    public ActionResult GetRequest([FromQuery] string param1, [FromQuery] int param2)
    {
        // Validate the method
        if (!ValidMethods.Contains(Request.Method))
        {
            return Forbid();
        }

        // Perform validation on parameters
        if (string.IsNullOrEmpty(param1) || param2 <= 0)
        {
            return BadRequest("Invalid parameters");
        }

        // Update cache based on the method and data
        var key = $"{Request.Method}-{param1}-{param2}";
        _cache.Set(key, "value");

        return Ok();
    }

    [HttpPost]
    public ActionResult PostRequest([FromBody] RequestData data)
    {
        // Validate the method
        if (!ValidMethods.Contains(Request.Method))
        {
            return Forbid();
        }

        // Perform validation on parameters
        if (data == null || string.IsNullOrEmpty(data.Param1) || data.Param2 <= 0)
        {
            return BadRequest("Invalid parameters");
        }

        // Update cache based on the method and data
        var key = $"{Request.Method}-{data.Param1}-{data.Param2}";
        _cache.Set(key, "value");

        return Ok();
    }
}

public class RequestData
{
    public string Param1 { get; set; }
    public int Param2 { get; set; }
}
