public class XmlConfigUpdater
{
    public static void AddNewSearcher(string configFilePath, string searcherName)
    {
        try
        {
            // Load the XML configuration file
            XDocument xdoc = XDocument.Load(configFilePath);

            // Define the namespace for XPath queries
            var searchersNamespace = "http://example.com/searchers";

            // Use XPath to select the list of existing searchers
            var searcherElements = xdoc.XPathSelectElements($"//*[local-name()='searchers' and namespace-uri()='{searchersNamespace}']/*[local-name()='searcher']");

