            if (searcherElements.Any(e => e.Attribute("name")?.Value == searcherName))
            {
                throw new InvalidOperationException($"A searcher with the name '{searcherName}' already exists.");
            }

            // Create a new searcher element
            var newSearcher = new XElement("searcher", new XAttribute("name", searcherName));

            // Add the new searcher to the list of searchers
            xdoc.XPathSelectElement($"//*[local-name()='searchers' and namespace-uri()='{searchersNamespace}']").Add(newSearcher);

