    public bool DeleteTrackableItem(string itemCode, int groupId)
    {
        if (string.IsNullOrEmpty(itemCode))
        {
            throw new ArgumentException("Item code cannot be null or empty", nameof(itemCode));
        }

        string query = "DELETE FROM TrackableItems WHERE Code = @code AND GroupID = @groupId";

        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            try
            {
                connection.Open();
                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@code", itemCode);
                    command.Parameters.AddWithValue("@groupId", groupId);
                    int rowsAffected = command.ExecuteNonQuery();

                    if (rowsAffected > 0)
                    {
                        _logger.LogInformation("Trackable item deleted successfully.");
                        return true;
                    }
                    else
                    {
                        _logger.LogWarning("No trackable item found with the given code and group ID.");
                        return false;
                    }
                }
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "An error occurred while deleting the trackable item.");
                throw;
            }
        }
    }
}
