using System;
using System.IO;
using System.Collections.Generic;

public class IniFileHandler
{
    public static Dictionary<string, string> LoadIniFile(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Console.WriteLine("Error: The specified file does not exist.");
            return null;
        }

        try
        {
            var iniData = new Dictionary<string, string>();
            using (StreamReader reader = new StreamReader(filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    if (!string.IsNullOrWhiteSpace(line) && !line.StartsWith(";"))
                    {
                        var parts = line.Split(new[] { '=' }, 2);
                        if (parts.Length == 2)
                        {
                            string key = parts[0].Trim();
                            string value = parts[1].Trim();
                            iniData[key] = value;
                        }
                    }
                }
            }
            return iniData;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading the INI file: {ex.Message}");
            return null;
        }
    }
}
