        // Bind the payload to the statement
        BoundStatement boundStatement = new BoundStatement(preparedStatement);
        if (payload != null)
        {
            boundStatement.Bind(payload);
        }
        else
        {
            throw new ArgumentNullException(nameof(payload), "Payload cannot be null");
        }

        // Execute the statement
        RowSet rowSet = session.Execute(boundStatement);

        // Assert that the incoming payload matches the expected payload
        if (rowSet.FirstOrDefault() == null)
        {
            throw new Exception("Payload does not match the expected payload");
        }
    }
