using System;
using System.Xml;

public class XmlUtility
{
    public static void ImportAndAppendNode(XmlDocument xmlDoc, XmlNode nodeToImport, string path)
    {
        // Check if the XML document was successfully parsed
        if (xmlDoc == null || nodeToImport == null)
        {
            throw new ArgumentNullException("The provided XmlDocument or XmlNode is null.");
        }

        // Import the node into the XML document
        XmlNode importedNode = xmlDoc.ImportNode(nodeToImport, true);
        if (importedNode == null)
        {
            throw new InvalidOperationException("Failed to import the provided XmlNode.");
        }

        // Check if the root element exists before attempting to append
        XmlElement rootElement = xmlDoc.DocumentElement;
        if (rootElement == null)
        {
            throw new InvalidOperationException("The XML document does not have a root element.");
        }

        // Append the imported node either to the root element or to a specific path
        if (string.IsNullOrEmpty(path))
        {
            rootElement.AppendChild(importedNode);
        }
        else
        {
            XmlElement targetElement = GetElementByPath(rootElement, path);
            if (targetElement == null)
            {
                throw new InvalidOperationException($"The specified element path '{path}' does not exist.");
            }
            targetElement.AppendChild(importedNode);
        }
    }

    private static XmlElement GetElementByPath(XmlElement root, string path)
    {
        string[] elements = path.Split('/');
        XmlElement currentElement = root;

        foreach (string elementName in elements)
        {
            XmlNodeList childNodes = currentElement.GetElementsByTagName(elementName);
            if (childNodes.Count == 0)
            {
                return null; // Element not found
            }
            currentElement = (XmlElement)childNodes[0];
        }

        return currentElement;
    }
}
