using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class CommandExecutor
{
    public delegate void OutputDataReceivedEventHandler(object sender, DataReceivedEventArgs e);
    public event OutputDataReceivedEventHandler OutputDataReceived;

    public async Task<int> ExecuteCommandAsync(string command)
    {
        if (string.IsNullOrEmpty(command))
        {
            throw new ArgumentException("Command cannot be null or empty.");
        }

        var processInfo = new ProcessStartInfo("cmd.exe", $"/c {command}")
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process { StartInfo = processInfo })
        {
            process.OutputDataReceived += (sender, e) => OutputDataReceived?.Invoke(this, e);
            process.ErrorDataReceived += (sender, e) => OutputDataReceived?.Invoke(this, e);

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            await Task.Run(() => process.WaitForExit());
            return process.ExitCode;
        }
    }
}
