using System;
using System.Xml.Linq;
using System.Linq;

public class XmlConfigUpdater
{
    public static void AddNewSection(string xmlFilePath, string newSectionName)
    {
        // Load the XML document
        XDocument xdoc = XDocument.Load(xmlFilePath);

        // Define the XPath expression to select the specific section after which we want to add the new one
        string targetSectionXpath = "//*[local-name()='" + newSectionName.Split(' ')[0] + "']";
        var targetSections = xdoc.XPathSelectElements(targetSectionXpath);

        // If no section is found, we add the new section at the end of the document
        if (targetSections.Count() == 0)
        {
            var root = xdoc.Root;
            if (root != null)
            {
                root.Add(new XElement(newSectionName));
            }
        }
        else
        {
            // Add the new section after the last found target section
            foreach (var targetSection in targetSections)
            {
                var parent = targetSection.Parent;
                if (parent != null)
                {
                    parent.AddAfterSelf(new XElement(newSectionName));
                }
            }
        }

        // Save the updated XML document
        xdoc.Save(xmlFilePath);
    }
}
