using System;
using System.Security.Cryptography;
using System.Text;

public class SecurityFunctions
{
    public static string GetMd5Hash(byte[] input)
    {
        // Validate the size of the byte array to ensure it does not exceed a specified limit
        const int MaxByteArraySize = 1024 * 1024; // 1 MB
        if (input.Length > MaxByteArraySize)
        {
            throw new ArgumentException("Input byte array exceeds maximum allowed size.");
        }

        using (MD5 md5Hash = MD5.Create())
        {
            // Compute the hash from the input byte array
            byte[] data = md5Hash.ComputeHash(input);

            // Create a StringBuilder to collect the bytes and create a string
            StringBuilder sBuilder = new StringBuilder();

            // Loop through each byte of the hashed data and format as hexadecimal
            for (int i = 0; i < data.Length; i++)
            {
                sBuilder.Append(data[i].ToString("x2"));
            }

            // Return the hexadecimal string
            return sBuilder.ToString();
        }
    }
}
