    public static void InsertElementAfter(string xmlFilePath, string existingElementXPath, string newElementName, string newElementValue)
    {
        // Load the XML document
        XDocument xdoc = XDocument.Load(xmlFilePath);

        // Select the existing element using XPath
        var existingElements = xdoc.XPathSelectElements(existingElementXPath);

        if (existingElements == null || !existingElements.Any())
