using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class ProcessExecutor
{
    public delegate void OutputDataReceivedHandler(string data);

    public async Task<(int exitCode, string output)> ExecuteProcessAsync(string filePath, string arguments, OutputDataReceivedHandler outputCallback)
    {
        var processInfo = new ProcessStartInfo(filePath, arguments)
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process { StartInfo = processInfo })
        {
            process.OutputDataReceived += (sender, e) => outputCallback(e.Data);
            process.ErrorDataReceived += (sender, e) => outputCallback(e.Data);

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            var taskCompletionSource = new TaskCompletionSource<int>();

            _ = Task.Run(() =>
            {
                try
                {
                    process.WaitForExit();
                    taskCompletionSource.TrySetResult(process.ExitCode);
                }
                catch (Exception ex)
                {
                    taskCompletionSource.TrySetException(ex);
                }
            });

            var exitCode = await taskCompletionSource.Task;
            return (exitCode, string.Empty); // The output is handled by the callback, so we don't need to capture it here.
        }
    }
}
