using System;
using System.Reflection;
using System.Xml;

public class XMLGenerator
{
    public static XmlDocument GenerateXML(Type type)
    {
        XmlDocument xmlDoc = new XmlDocument();
        XmlElement rootElement = xmlDoc.CreateElement("root");
        xmlDoc.AppendChild(rootElement);

        // Retrieve custom attributes
        object[] attributes = type.GetCustomAttributes(false);

        foreach (var attribute in attributes)
        {
            if (attribute is XmlizedClassAttribute || attribute is XmlizedSqlstringIDClassAttribute)
            {
                // Process the attribute to generate XML content
                GenerateXMLContent(rootElement, attribute);
            }
        }

        return xmlDoc;
    }

    private static void GenerateXMLContent(XmlElement parentElement, object attribute)
    {
        Type attrType = attribute.GetType();

        foreach (var prop in attrType.GetProperties())
        {
            if (prop.PropertyType == typeof(string))
            {
                string value = (string)prop.GetValue(attribute);
                XmlElement element = parentElement.OwnerDocument.CreateElement(prop.Name);
                element.InnerText = value;
                parentElement.AppendChild(element);
            }
        }
    }
}

