    public List<TravelItem> ParseGeocachesFromHtml(string htmlFilePath)
    {
        var travelItems = new List<TravelItem>();

        // Load the HTML file from embedded resources
        var assembly = Assembly.GetExecutingAssembly();
        using (var stream = assembly.GetManifestResourceStream("YourNamespace.YourEmbeddedResourceFile.html"))
