    public bool EstablishRemoteConnection(string ipAddress, string username, string password)
    {
        try
        {
            // Validate inputs to prevent command injection or other vulnerabilities
            if (string.IsNullOrEmpty(ipAddress) || string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
            {
