public class ClassFactory
{
    public static T CreateInstance<T>(string className) where T : new()
    {
        Type type = Type.GetType(className);
        if (type == null)
        {
            throw new ArgumentException("Class not found");
        }

        // Ensure the class implements the expected interface or is derived from a base class
        if (!typeof(T).IsAssignableFrom(type))
