using System;
using System.IO;
using System.Xml;

public class XmlValidator
{
    public static bool ValidateXmlAgainstSchema(string xmlContent, string schemaContent)
    {
        // Create an XmlReaderSettings object and set the validation type to Schema
        XmlReaderSettings settings = new XmlReaderSettings();
        settings.ValidationType = ValidationType.Schema;

        // Load the schema from a String reader
        using (StringReader schemaStream = new StringReader(schemaContent))
        {
            settings.Schemas.Add(null, XmlReader.Create(schemaStream));
        }

        // Create an XmlReader object with the settings
        using (XmlReader xmlReader = XmlReader.Create(new StringReader(xmlContent), settings))
        {
            // Move to the first attribute in the document
            while (xmlReader.MoveToNextAttribute())
            {
                // Verify that the prefix of the attribute is empty
                if (!string.IsNullOrEmpty(xmlReader.Prefix))
                {
                    return false; // Attribute has a non-empty prefix
                }
            }
        }

        return true; // All attributes have an empty prefix
    }
}
