class Program
{
    static void Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.WriteLine("Usage: ProcessRunner <executable> <arguments>");
            return;
        }

        string executable = args[0];
        string arguments = args[1];
        int timeout = 30000; // Timeout in milliseconds (30 seconds)

