                // Wait for the process to complete or timeout
                bool completed = process.WaitForExit(timeout);
                if (!completed)
                {
                    // If the process did not complete within the timeout, kill it
                    process.Kill();
                    Console.WriteLine($"Process '{executable} {arguments}' timed out and was killed.");
                }
                else
                {
                    Console.WriteLine($"Process '{executable} {arguments}' completed with exit code {process.ExitCode}.");
