using System;
using Foundation;

public interface ITicker
{
    void Start();
    void Stop();
}

public class MobileTaskPlatform : IDisposable
{
    private NSRunLoop mainRunLoop;
    private NSTimer timer;

    public MobileTaskPlatform()
    {
        mainRunLoop = NSRunLoop.Main;
    }

    public void BeginInvokeOnMainThread(Action action)
    {
        if (action == null)
            throw new ArgumentNullException(nameof(action));

        mainRunLoop.BeginInvokeOnMainThread(() => action());
    }

    public ITicker CreateTicker()
    {
        return new CADisplayLinkTicker();
    }

    private class CADisplayLinkTicker : ITicker
    {
        private CADisplayLink displayLink;

        public void Start()
        {
            if (displayLink == null)
            {
                displayLink = CADisplayLink.Create(() => { });
                displayLink.AddToRunLoop(NSRunLoop.Main, NSDefaultRunLoopMode);
            }
        }

        public void Stop()
        {
            if (displayLink != null)
            {
                displayLink.RemoveFromRunLoop(NSRunLoop.Main, NSDefaultRunLoopMode);
                displayLink.Dispose();
                displayLink = null;
            }
        }
    }

    public void Dispose()
    {
        if (timer != null)
        {
            timer.Invalidate();
            timer = null;
        }
    }
