using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static XmlElement GetFirstElementByName(XmlNode node, string elementName)
    {
        if (node == null || string.IsNullOrEmpty(elementName))
        {
            throw new ArgumentNullException("Invalid input parameters.");
        }

        XPathNavigator navigator = node.CreateNavigator();
        XPathExpression expr = XPathExpression.Compile($"//*[local-name()='{elementName}']");
        XPathNodeIterator iterator = navigator.Select(expr);

        if (iterator == null)
        {
            throw new Exception("No element found with the given name.");
        }

        XmlElement firstElement = null;
        int count = 0;

        while (iterator.MoveNext())
        {
            count++;
            firstElement = iterator.Current as XmlElement;
            if (count > 1)
            {
                throw new Exception("Multiple elements found with the given name.");
            }
        }

        if (firstElement == null)
        {
            throw new Exception("No element found with the given name.");
        }

        return firstElement;
    }
}
