using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

public class CommandExecutor
{
    public async Task ExecuteCommandAsync(string commandLine, string arguments)
    {
        if (string.IsNullOrWhiteSpace(commandLine))
        {
            throw new ArgumentException("Command line cannot be null or empty.", nameof(commandLine));
        }

        try
        {
            var processInfo = new ProcessStartInfo(commandLine, arguments)
            {
                RedirectStandardInput = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true,
                WindowStyle = ProcessWindowStyle.Minimized
            };

            using (var process = new Process { StartInfo = processInfo })
            {
                process.Start();

                var taskOutput = Task.Run(() => process.StandardOutput.ReadToEnd());
                var taskError = Task.Run(() => process.StandardError.ReadToEnd());

                await Task.WhenAll(taskOutput, taskError);

                process.WaitForExit();

                if (process.ExitCode != 0)
                {
                    throw new InvalidOperationException($"Command '{commandLine} {arguments}' failed with exit code {process.ExitCode}. Output: {taskOutput.Result}, Error: {taskError.Result}");
                }
            }
        }
        catch (Exception ex)
        {
            throw new Exception("An error occurred while executing the command.", ex);
        }
    }
}
