using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

public class Resource
{
    public string Hash { get; set; }
    public byte[] Data { get; set; }
    public string MimeType { get; set; }
}

public class Program
{
    public static List<Resource> ProcessResources(List<Tuple<byte[], string>> resources)
    {
        List<Resource> processedResources = new List<Resource>();

        foreach (var resource in resources)
        {
            byte[] data = resource.Item1;
            string mimeType = resource.Item2;

            // Compute MD5 hash of the byte array
            using (MD5 md5 = MD5.Create())
