using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class ProfileReader
{
    public (string hash, string htmlContent) ReadProfile(Stream stream)
    {
        // Ensure the stream has sufficient remaining bytes to read
        if (stream.Length - stream.Position < 4)
        {
            throw new InvalidOperationException("Insufficient data in the stream.");
        }

        using (var sha1 = SHA1.Create())
        {
            byte[] buffer = new byte[4];
            int bytesRead = stream.Read(buffer, 0, 4);
            if (bytesRead != 4)
            {
                throw new InvalidOperationException("Failed to read sufficient data from the stream.");
            }

            // Compute the SHA1 hash of the buffer
