            // Read the remaining profile data (for demonstration purposes, assuming it's HTML content)
            using (var memoryStream = new MemoryStream())
            {
                stream.CopyTo(memoryStream);
                byte[] profileData = memoryStream.ToArray();
                string htmlContent = Encoding.UTF8.GetString(profileData);

                return (hash, htmlContent);
            }
        }
    }
}
