using System;
using System.IO;

public class FileCopier
{
    public void CopyFiles(string sourceDirectory, string targetDirectory, string[] includeExtensions, string[] excludeExtensions)
    {
        // Validate the input paths to prevent directory traversal attacks
        if (!IsValidPath(sourceDirectory) || !IsValidPath(targetDirectory))
        {
            throw new ArgumentException("Invalid path detected.");
        }

        // Ensure target directory exists
        Directory.CreateDirectory(targetDirectory);

        // Get all files in the source directory with their full paths
        string[] files = Directory.GetFiles(sourceDirectory);

        foreach (string file in files)
        {
            string fileName = Path.GetFileName(file);
            if (!IsExtensionAllowed(fileName, includeExtensions, excludeExtensions))
            {
                continue;
            }

            // Determine the target path
            string targetFilePath = Path.Combine(targetDirectory, fileName);

            // Copy the file to the new location
            File.Copy(file, targetFilePath, true);
        }
    }

    private bool IsValidPath(string path)
    {
        // Check for invalid characters in the path
        return !Path.GetInvalidPathChars().Any(path.Contains);
    }

    private bool IsExtensionAllowed(string fileName, string[] includeExtensions, string[] excludeExtensions)
    {
        string extension = Path.GetExtension(fileName).ToLower();

        // Check if the file should be excluded based on its extension
        foreach (string excludeExtension in excludeExtensions)
        {
            if (extension == excludeExtension)
            {
                return false;
            }
        }

        // Include files with no specified extensions or those that match includeExtensions
        if (includeExtensions.Length == 0 || Array.Exists(includeExtensions, ext => ext.ToLower() == extension))
        {
            return true;
        }

        return false;
    }
}
