using System;
using System.Diagnostics;
using System.IO;

public class ProcessExecutor
{
    public static void ExecuteProcess(string fileName, string arguments, Stream outputStream)
    {
        // Validate the file name and ensure it is a valid executable path
        if (string.IsNullOrEmpty(fileName))
        {
            throw new ArgumentException("File name cannot be null or empty.", nameof(fileName));
        }

        if (!File.Exists(fileName))
        {
            throw new FileNotFoundException($"The file '{fileName}' does not exist.");
        }

        // Create the process start info with no shell execution
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = fileName,
            Arguments = arguments,
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        // Start the process and redirect output to the provided stream
        using (Process process = new Process { StartInfo = startInfo })
        {
            if (outputStream == null)
            {
                throw new ArgumentNullException(nameof(outputStream), "Output stream cannot be null.");
            }

            // Ensure we have write permissions to the output stream
            try
            {
                using (StreamWriter writer = new StreamWriter(outputStream))
                {
                    process.OutputDataReceived += (sender, e) =>
                    {
                        if (e.Data != null)
                        {
                            writer.WriteLine(e.Data);
                        }
                    };

                    process.Start();
                    process.BeginOutputReadLine();
                    process.WaitForExit();
                }
            }
            catch (UnauthorizedAccessException ex)
            {
                throw new InvalidOperationException("You do not have the necessary permissions to write to this output stream.", ex);
            }
        }
    }
}
