using System;
using System.Security.Cryptography;
using System.Text;

public class TripleDESExample
{
    public static string Encrypt(string input, Guid keyGuid1, Guid keyGuid2)
    {
        // Convert GUIDs to byte arrays
        byte[] keyBytes1 = keyGuid1.ToByteArray();
        byte[] keyBytes2 = keyGuid2.ToByteArray();

        // Combine the keys into a single 24-byte array (TripleDES requires three 8-byte keys)
        byte[] combinedKey = new byte[24];
        Array.Copy(keyBytes1, 0, combinedKey, 0, 8);
        Array.Copy(keyBytes2, 0, combinedKey, 8, 8);
        Array.Copy(keyBytes1, 0, combinedKey, 16, 8);

        // Create a TripleDES instance and initialize it with the key
        using (TripleDES tripleDes = TripleDES.Create())
        {
            tripleDes.Mode = CipherMode.ECB;
            tripleDes.Padding = PaddingMode.PKCS7;
            ICryptoTransform encryptor = tripleDes.CreateEncryptor(combinedKey, null);

            // Convert the input string to a byte array and encrypt it
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] encryptedBytes = encryptor.TransformFinalBlock(inputBytes, 0, inputBytes.Length);

            // Return the encrypted bytes as a Base64-encoded string
            return Convert.ToBase64String(encryptedBytes);
        }
    }
}
