class Program
{
    static async Task Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Please provide a URL as an argument.");
            return;
        }

        string url = args[0];
        try
        {
            string content = await DownloadContentAsync(url);
            var tempFilePath = Path.GetTempFileName();
            File.WriteAllText(tempFilePath, content);

            Process.Start("notepad.exe", tempFilePath); // Example: Open with Notepad
            Console.WriteLine($"File saved to {tempFilePath}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    static async Task<string> DownloadContentAsync(string url)
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                HttpResponseMessage response = await client.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();
                string content = await response.Content.ReadAsStringAsync();
                return content;
            }
            catch (HttpRequestException ex)
            {
                throw new Exception("Failed to download the URL content.", ex);
            }
        }
    }
}
