using System;
using System.Linq;
using System.Xml.Linq;

public class XmlConfigUpdater
{
    public static void AddIndexProviderSection(string configFilePath, string existingSectionName, string newSectionContent)
    {
        // Load the XML configuration file
        XDocument xdoc = XDocument.Load(configFilePath);

        // Select all elements that match the specified section name
        var sections = xdoc.XPathSelectElements($"//*[local-name()='{existingSectionName}']");

        if (sections == null || !sections.Any())
        {
            throw new ArgumentException("The specified existing section does not exist in the configuration file.");
        }

        // Find the first matching section and insert the new index provider section after it
        foreach (var section in sections)
        {
            var nextSection = section.NextNode as XElement;
            if (nextSection != null && nextSection.Name.LocalName == "indexProvider")
            {
                // Insert the new section content after the existing section
                section.AddAfterSelf(XDocument.Parse(newSectionContent).Root);
                break;
            }
        }

        // Save the updated XML configuration file
        xdoc.Save(configFilePath);
    }
}
