using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public class XmlUpdater
{
    public static string UpdateXml(string xmlFilePath, string elementToRemoveXpath, string insertAfterXpath)
    {
        try
        {
            // Load the XML document
            XPathDocument doc = new XPathDocument(xmlFilePath);
            XPathNavigator nav = doc.CreateNavigator();

            // Validate and prepare to remove the element
            if (string.IsNullOrEmpty(elementToRemoveXpath))
                throw new ArgumentException("Element removal XPath cannot be null or empty.");

            // Remove the element using the provided XPath expression
            XPathNodeIterator nodes = nav.Select(elementToRemoveXpath);
            while (nodes.MoveNext())
            {
                XmlNode nodeToRemove = nodes.Current.Clone();
                if (nodeToRemove != null)
                {
                    nodeToRemove.ParentNode?.RemoveChild(nodeToRemove);
                }
            }

            // Prepare to insert the removed element after a specified XPath expression
            if (!string.IsNullOrEmpty(insertAfterXpath))
            {
                XPathNavigator insertPosition = nav.SelectSingleNode(insertAfterXpath);
                if (insertPosition != null)
                {
                    foreach (XmlNode nodeToInsert in nodes)
                    {
                        XmlNode importedNode = nodeToInsert.Clone();
                        insertPosition.InsertAfter(importedNode);
                    }
                }
            }

            // Save the updated XML document to a string
            using (StringWriter sw = new StringWriter())
            {
                nav.Save(sw);
                return sw.ToString();
            }
        }
        catch (Exception ex)
        {
            throw new Exception("An error occurred while updating the XML file.", ex);
        }
    }
}
