using System;
using System.Diagnostics;

public class ProcessManager
{
    private Process cmdProcess;

    public void StartCmdProcess()
    {
        try
        {
            // Create the process start info with the command to run
            ProcessStartInfo startInfo = new ProcessStartInfo("cmd.exe");
            startInfo.UseShellExecute = false;
            startInfo.RedirectStandardInput = true;
            startInfo.RedirectStandardOutput = true;
            startInfo.RedirectStandardError = true;

            // Create the process and start it
            cmdProcess = new Process();
            cmdProcess.StartInfo = startInfo;
            cmdProcess.EnableRaisingEvents = true;
            cmdProcess.Exited += OnCmdProcessExited;
            cmdProcess.Start();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error starting command prompt process: {ex.Message}");
        }
    }

    private void OnCmdProcessExited(object sender, EventArgs e)
    {
        // Handle the process exit event if needed
        Console.WriteLine("Command prompt process has exited.");
    }

    public void TerminateCmdProcess()
    {
        if (cmdProcess != null && !cmdProcess.HasExited)
        {
            try
            {
                cmdProcess.Kill();
                cmdProcess.WaitForExit(); // Wait for the process to exit gracefully
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error terminating command prompt process: {ex.Message}");
            }
        }
    }
}
