using System;
using System.Xml.Linq;
using System.Linq;

public class XmlUpdater
{
    public static string UpdateXml(string filePath, string existingXPath, XElement newElement, string insertAfterXPath)
    {
        // Load the XML file
        XDocument xmlDoc = XDocument.Load(filePath);

        // Find the element to insert after
        var targetElement = xmlDoc.XPathSelectElement(insertAfterXPath);
        if (targetElement == null)
        {
            throw new ArgumentException("The specified element to insert after does not exist.");
        }

        // Find the existing element
        var existingElement = xmlDoc.XPathSelectElement(existingXPath);
        if (existingElement == null)
        {
            throw new ArgumentException("The specified existing element does not exist.");
        }

        // Insert the new element after the existing element
        targetElement.AddAfterSelf(newElement);

        // Save the updated XML file
        xmlDoc.Save(filePath);

        // Return the updated XML as a string
        return xmlDoc.ToString();
    }
}
