using System;
using System.Reflection;
using System.Xml;

public class XmlizedPropertyAttribute : Attribute
{
    public string Path { get; set; }
}

public interface IExportToXmlable
{
    XmlNode ExportToXml();
}

public static class ObjectToXmlConverter
{
    public static XmlDocument ConvertObjectToXml(object obj)
    {
        var xmlDoc = new XmlDocument();
        var rootElement = xmlDoc.CreateElement("root");
        xmlDoc.AppendChild(rootElement);

        Type type = obj.GetType();
        foreach (PropertyInfo property in type.GetProperties())
        {
            object[] attributes = property.GetCustomAttributes(typeof(XmlizedPropertyAttribute), false);
            if (attributes.Length > 0)
            {
                XmlizedPropertyAttribute xmlizedPropertyAttribute = (XmlizedPropertyAttribute)attributes[0];
                string path = xmlizedPropertyAttribute.Path;

                object propertyValue = property.GetValue(obj, null);
                XmlNode node;

                if (propertyValue is IExportToXmlable exportable)
                {
                    node = exportable.ExportToXml();
                }
                else
                {
                    node = xmlDoc.CreateElement(path);
                    node.InnerText = propertyValue?.ToString() ?? string.Empty;
                }

                rootElement.AppendChild(node);
            }
        }

        return xmlDoc;
    }
}
