using System;
using System.Xml;

public class XmlParser
{
    public string GetHttpParameterDocumentation(XmlNode methodNode, string parameterName)
    {
        // Validate that the method node is not null and has child nodes
        if (methodNode == null || methodNode.ChildNodes.Count == 0)
        {
            throw new ArgumentException("Invalid method node provided.");
        }

        // Iterate through the child nodes of the method node to find the parameter node
        foreach (XmlNode node in methodNode.ChildNodes)
        {
            if (node.Name == "parameter" && node.Attributes["name"]?.Value == parameterName)
            {
                // Return the value of the specific parameter node
                return node.InnerText;
            }
        }

        // If the parameter is not found, throw an exception
        throw new ArgumentException($"Parameter '{parameterName}' not found.");
    }
}
