using System.Text;

public class HashAlgorithmWrapper
{
    public string Name { get; private set; }
    public HashAlgorithm Algorithm { get; private set; }

    public HashAlgorithmWrapper(string name, HashAlgorithm algorithm)
    {
        Name = name;
        Algorithm = algorithm;
    }

    public static HashAlgorithmWrapper CreateMD5()
    {
        return new HashAlgorithmWrapper("MD5", MD5.Create());
    }

    public static HashAlgorithmWrapper CreateSHA1()
    {
        return new HashAlgorithmWrapper("SHA1", SHA1.Create());
    }

    public static HashAlgorithmWrapper CreateSHA256()
    {
        return new HashAlgorithmWrapper("SHA256", SHA256.Create());
    }

    public static HashAlgorithmWrapper CreateSHA512()
    {
        return new HashAlgorithmWrapper("SHA512", SHA512.Create());
    }

    public string ComputeHash(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }

        using (Algorithm)
        {
            var inputBytes = Encoding.UTF8.GetBytes(input);
            var hashBytes = Algorithm.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}
