using System;
using System.Xml;

public class ConfigurationManager
{
    public void UpdateConfiguration(string xmlFilePath, string keyValue)
    {
        try
        {
            // Load the XML document
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFilePath);

            // Check if the root element exists
            XmlElement root = doc.DocumentElement;
            if (root == null)
            {
                throw new Exception("The XML document does not have a valid root element.");
            }

            // Remove the node with the specified key value
            XmlNode nodeToRemove = root.SelectSingleNode($"//*[@key='{keyValue}']");
            if (nodeToRemove != null)
            {
                root.RemoveChild(nodeToRemove);
            }
            else
            {
                throw new Exception("The specified key does not exist in the XML document.");
            }

            // Create a new configuration node with the same key value
            XmlElement newNode = doc.CreateElement("configuration");
            newNode.SetAttribute("key", keyValue);
            root.AppendChild(newNode);

            // Save the updated XML document
            doc.Save(xmlFilePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
            throw;
        }
    }
}
