using System;
using System.Security.Cryptography;

public class EncryptionTest
{
    public static void TestEncryption(SymmetricAlgorithm algorithm, byte[] key, byte[] plaintext)
    {
        // Validate the key size
        if (key.Length * 8 != algorithm.KeySize)
        {
            throw new ArgumentException("Invalid key size");
        }

        // Initialize the cipher with ECB mode and zero padding
        algorithm.Mode = CipherMode.ECB;
        algorithm.Padding = PaddingMode.Zeros;
        ICryptoTransform encryptor = algorithm.CreateEncryptor(key, null);
        ICryptoTransform decryptor = algorithm.CreateDecryptor(key, null);

        // Validate the block size
        if (algorithm.BlockSize != 128)
        {
            throw new ArgumentException("Invalid block size");
        }

        // Encrypt the plaintext message
        byte[] ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);

        // Decrypt the ciphertext message
        byte[] decryptedText = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);

        // Check if the decrypted text is equal to the original plaintext
        if (!AreByteArraysEqual(decryptedText, plaintext))
        {
            throw new Exception("Decryption failed");
        }
    }

