        }

        // Validate the path to ensure it is within a safe directory structure
        var safeDirectory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", ".."));
        if (!configFilePath.StartsWith(safeDirectory))
        {
            throw new ArgumentException("Invalid config file path.");
        }

