import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class GaussianMutator {
    public static double mutateValue(Random randomGenerator, double value, double stdDevFactor, double minRange, double maxRange) {
        // Generate a random number from a normal (Gaussian) distribution with mean 0 and standard deviation 1
        double gaussianValue = randomGenerator.nextGaussian();

        // Scale the Gaussian value by the standard deviation factor
        double scaledGaussianValue = gaussianValue * stdDevFactor;

        // Apply the mutation to the original value
        double mutatedValue = value + scaledGaussianValue;

        // Ensure the mutated value is within the specified range
        if (mutatedValue < minRange) {
            mutatedValue = minRange;
        } else if (mutatedValue > maxRange) {
            mutatedValue = maxRange;
        }

        return mutatedValue;
    }

    public static List<Double> generateDiscreteValues(Random randomGenerator, double mean, double stdDev, int numValues, double minRange, double maxRange) {
        List<Double> values = new ArrayList<>();

        for (int i = 0; i < numValues; i++) {
            double value = mutateValue(randomGenerator, mean, stdDev, minRange, maxRange);
            values.add(value);
        }

        return values;
    }
}
