import java.security.SecureRandom;

public class RandomValueGenerator {

    private static final SecureRandom secureRandom = new SecureRandom();

    public static Object getRandomValue(String type) {
        switch (type) {
            case "Integer":
                return secureRandom.nextInt(100); // Random integer between 0 and 99
            case "Double":
                return secureRandom.nextDouble() * 100; // Random double between 0.0 and 100.0
            case "Boolean":
                return secureRandom.nextBoolean(); // Random boolean value
            case "String":
                return generateRandomString(10); // Random string of length 10
            default:
                throw new IllegalArgumentException("Unsupported type: " + type);
        }
    }

    private static String generateRandomString(int length) {
        StringBuilder sb = new StringBuilder(length);
        String characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        for (int i = 0; i < length; i++) {
            int index = secureRandom.nextInt(characters.length());
            sb.append(characters.charAt(index));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(getRandomValue("Integer"));
        System.out.println(getRandomValue("Double"));
        System.out.println(getRandomValue("Boolean"));
        System.out.println(getRandomValue("String"));
    }
}
