import java.security.SecureRandom;
import java.util.Random;
import java.math.BigDecimal;

public class RandomValueGenerator {

    public static Object generateRandomValue(Class<?> type, SecureRandom random) {
        if (type == Byte.class || type == short.class || type == int.class || type == long.class) {
            return switch ((Class<?>) type) {
                case Byte.class -> (byte) random.nextInt();
                case Short.class -> (short) random.nextInt();
                case Integer.class -> random.nextInt();
                case Long.class -> random.nextLong();
                default -> throw new IllegalArgumentException("Unsupported type: " + type);
            };
        } else if (type == Float.class || type == double.class) {
            return switch ((Class<?>) type) {
                case Float.class -> random.nextFloat();
                case Double.class -> random.nextDouble();
                default -> throw new IllegalArgumentException("Unsupported type: " + type);
            };
        } else if (type == Character.class) {
            char[] buffer = new char[1];
            random.nextBytes(buffer);
            return buffer[0];
        } else if (type == String.class) {
            byte[] bytes = new byte[20]; // 20 characters is arbitrary, adjust as needed
            random.nextBytes(bytes);
            return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
        } else if (type == BigDecimal.class) {
            long unscaledVal = random.nextLong();
            int scale = random.nextInt(20); // Scale between 0 and 19
            return new BigDecimal(unscaledVal, scale);
        } else {
            throw new IllegalArgumentException("Unsupported type: " + type);
        }
    }
}
