import org.apache.lucene.document.*;
import org.apache.lucene.index.*;
import org.apache.lucene.search.*;
import org.hamcrest.MatcherAssert;
import org.hamcrest.Matchers;

public class DocumentComparator {
    public static void compareNumericFields(IndexReader reader, int docId1, int docId2, String field1, String field2) throws IOException {
        NumericDocValues values1 = MultiDocValues.getNumeric(reader, field1);
        NumericDocValues values2 = MultiDocValues.getNumeric(reader, field2);

        // Check if both fields exist in the documents
        if (values1 == null || values2 == null) {
            throw new IllegalArgumentException("One or both fields do not exist in the specified documents.");
        }

        // Ensure that both fields have the same number of values
        int count1 = 0;
        int count2 = 0;
        while (values1.advanceExact(docId1) && values2.advanceExact(docId2)) {
            count1++;
            count2++;
        }

        if (count1 != count2) {
            throw new IllegalArgumentException("The number of values in the fields do not match.");
        }

        // Compare each value in the fields
        for (int i = 0; i < count1; i++) {
            values1.advanceExact(docId1);
            values2.advanceExact(docId2);
            double val1 = values1.doubleValue();
            double val2 = values2.doubleValue();
            MatcherAssert.assertThat("Values do not match at position " + i, val1, Matchers.is(val2));
        }
    }
}
