import java.util.*;

public class PairProcessor {
    public static void processPairs(List<Pair> pairs, double percentage) {
        int totalPairs = pairs.size();
        int targetProcessed = (int) (totalPairs * percentage);
        Random random = new Random();
        Set<Integer> processedIndices = new HashSet<>();

        while (processedIndices.size() < targetProcessed) {
            for (int i = 0; i < totalPairs; i++) {
                if (!processedIndices.contains(i)) {
                    boolean isLastPair = (i == totalPairs - 1);
                    System.out.println("Processing pair " + i + ": " + (isLastPair ? "last" : "not last"));

                    if (!isLastPair) {
                        int previousIndex = random.nextInt(i);
                        Collections.swap(pairs, i, previousIndex);
                    }

                    processedIndices.add(i);
                }

                if (processedIndices.size() >= targetProcessed) {
                    break;
                }
            }
        }
    }

    static class Pair {
        int randomInt;
        boolean boolValue;

        Pair(int randomInt, boolean boolValue) {
            this.randomInt = randomInt;
            this.boolValue = boolValue;
        }
    }
}
