import com.codahale.metrics.MetricRegistry;
import com.codahale.metrics.graphite.GraphiteReporter;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class MetricNotificationService {
    private final GraphiteReporter graphiteReporter;
    private final MetricRegistry metricRegistry;
    private final Map<String, MetricGauge> metricMap;

    private static volatile MetricNotificationService instance;

    private MetricNotificationService(String hostname, int port) {
        this.metricRegistry = new MetricRegistry();
        this.graphiteReporter = GraphiteReporter.forRegistry(this.metricRegistry)
                .convertDurationsTo(java.util.concurrent.TimeUnit.SECONDS)
                .build(new com.codahale.metrics.graphite.Graphite(hostname, port));
        this.metricMap = new ConcurrentHashMap<>();
    }

    public static MetricNotificationService getInstance(String hostname, int port) {
        if (instance == null) {
            synchronized (MetricNotificationService.class) {
                if (instance == null) {
                    instance = new MetricNotificationService(hostname, port);
                }
            }
        }
        return instance;
    }

    public void registerMetric(String name, Gauge<?> gauge) {
        this.metricRegistry.register(name, gauge);
        this.metricMap.put(name, new MetricGauge(gauge));
    }
}

class MetricGauge implements Gauge<Double> {
    private final Gauge<?> gauge;

    public MetricGauge(Gauge<?> gauge) {
        this.gauge = gauge;
    }

    @Override
    public Double getValue() {
        Object value = gauge.getValue();
        if (value instanceof Number) {
            return ((Number) value).doubleValue();
        } else {
            throw new IllegalStateException("Gauge value is not a number");
        }
    }
}
