import java.net.InetSocketAddress;
import java.util.ArrayList;
import java.util.List;

public class NetworkUtils {
    public static List<InetSocketAddress> createSocketAddresses(
            List<String> hostnamesAndPorts, String username, String password, 
            String serverID, boolean enrichConnectionFlag, String driverLocation, 
            String driverName, int connectionTimeout) throws ArrayIndexOutOfBoundsException {

        List<InetSocketAddress> socketAddresses = new ArrayList<>();

        for (String hostAndPort : hostnamesAndPorts) {
            String[] parts = hostAndPort.split(":");

            if (parts.length != 2) {
                throw new ArrayIndexOutOfBoundsException("Input must be in the format of host:port");
            }

            String hostname = parts[0];
            String portStr = parts[1];

            try {
                int port = Integer.parseInt(portStr);
                InetSocketAddress socketAddress = new InetSocketAddress(hostname, port);
                socketAddresses.add(socketAddress);
            } catch (NumberFormatException e) {
                throw new ArrayIndexOutOfBoundsException("Invalid port number: " + portStr);
            }
        }

        return socketAddresses;
    }
}
