import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.FileSystem;
import java.security.SecureRandom;

public class SecureFileGenerator {
    public static File generateBinaryDataFile(FileSystem fileSystem, String folderPath, String fileName, int length) throws IOException {
        // Ensure the folder exists and is writable
        File folder = new File(folderPath);
        if (!folder.exists() && !folder.mkdirs()) {
            throw new IOException("Failed to create directory: " + folderPath);
        }

        File file = new File(folder, fileName);
        try (FileOutputStream fos = new FileOutputStream(file)) {
            SecureRandom random = new SecureRandom();
            byte[] buffer = new byte[8192]; // Use a buffer to improve performance
            int bytesRead;

            while (length > 0) {
                if (length < buffer.length) {
                    bytesRead = length;
                } else {
                    bytesRead = buffer.length;
                }
                random.nextBytes(buffer); // Fill the buffer with secure random bytes
                fos.write(buffer, 0, bytesRead);
                length -= bytesRead;
            }
        }

        return file;
    }
