import java.util.*;

public class RandomGaussianReplacement {
    private static final double MEAN = 0;
    private static final double STANDARD_DEVIATION = 0.2;

    public List<Object> replaceRandomObjects(List<Object> originalList) {
        if (originalList == null || originalList.isEmpty()) {
            throw new IllegalArgumentException("The input list must not be null or empty.");
        }

        Random random = new SecureRandom();
        double stdDevSizeRatio = STANDARD_DEVIATION * originalList.size();
        List<Object> resultList = new ArrayList<>(originalList);
        Set<Double> discreteValues = new HashSet<>();

        for (int i = 0; i < originalList.size(); i++) {
            if (random.nextDouble() < 1 / Math.sqrt(2 * Math.PI * stdDevSizeRatio * stdDevSizeRatio)) {
                double newValue = random.nextGaussian() * stdDevSizeRatio + MEAN;
                discreteValues.add(newValue);
                resultList.set(i, newValue);
            } else {
                discreteValues.add((double) originalList.get(i));
            }
        }

        return resultList;
    }

    public Set<Double> getDiscreteValues() {
        return new HashSet<>(discreteValues);
    }
}
