import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import java.io.File;
import java.io.IOException;

public class ThemeManager {
    private File cacheDir;
    private static final String DEFAULT_THEME_DIR = "/sdcard/themes";

    public void setCacheDir(File cacheDir) {
        this.cacheDir = cacheDir;
    }

    public Bitmap loadThemeFromCache(String themeName) {
        if (cacheDir == null || !cacheDir.exists() || !cacheDir.isDirectory()) {
            return null;
        }

        File themeFile = new File(cacheDir, themeName + ".png");
        if (!themeFile.exists() || !themeFile.canRead()) {
            return null;
        }

        Bitmap bitmap = BitmapFactory.decodeFile(themeFile.getAbsolutePath());
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
            bitmap = null;
        }

        return bitmap;
    }

    public boolean saveThemeToCache(String themeName, Bitmap themeBitmap) {
        if (cacheDir == null || !cacheDir.exists() || !cacheDir.isDirectory()) {
            cacheDir = new File(DEFAULT_THEME_DIR);
        }

        if (!cacheDir.exists() && !cacheDir.mkdirs()) {
            return false;
        }

        File themeFile = new File(cacheDir, themeName + ".png");
        try (OutputStream os = new FileOutputStream(themeFile)) {
            themeBitmap.compress(Bitmap.CompressFormat.PNG, 100, os);
            return true;
        } catch (IOException e) {
            return false;
        } finally {
            if (themeBitmap != null && !themeBitmap.isRecycled()) {
                themeBitmap.recycle();
            }
        }
    }
}
