import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class GraphTraversal {
    private static final int MAX_THREADS = 10;
    private AtomicInteger numVertices = new AtomicInteger(0);
    private AtomicInteger numEdges = new AtomicInteger(0);
    private AtomicInteger completedThreads = new AtomicInteger(0);

    public void addVertex() {
        numVertices.incrementAndGet();
    }

    public void addEdge() {
        numEdges.incrementAndGet();
    }

    public void traverseGraph(int id) {
        try {
            // Simulate graph traversal work
            Thread.sleep((long) (Math.random() * 1000));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            completedThreads.incrementAndGet();
        }
    }

    public static void main(String[] args) {
        GraphTraversal graph = new GraphTraversal();
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

        for (int i = 0; i < MAX_THREADS; i++) {
            int finalI = i;
            executor.submit(() -> {
                graph.traverseGraph(finalI);
            });
        }

        // Wait for all threads to complete
        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Number of vertices: " + graph.numVertices.get());
        System.out.println("Number of edges: " + graph.numEdges.get());
        System.out.println("Completed threads: " + graph.completedThreads.get());
    }
}
