        // Notify any waiting threads that the service is now ready
        serviceLock.lock();
        try {
            serviceCondition.signalAll();
        } finally {
            serviceLock.unlock();
        }
    }

    public boolean isServiceEnabled() {
        return isServiceEnabled;
    }

    public ServerSocket getServerSocket() {
        return serverSocket;
    }
}
