import java.io.IOException;
import java.util.Map;

public class JsonGenerator {

    public static String toJson(Object object) throws IOException {
        StringBuilder jsonBuilder = new StringBuilder();
        writeValue(jsonBuilder, object);
        return jsonBuilder.toString();
    }

    private static void writeValue(StringBuilder jsonBuilder, Object value) throws IOException {
        if (value == null) {
            jsonBuilder.append("null");
        } else if (value instanceof String) {
            jsonBuilder.append('"');
            escapeJsonString((String) value, jsonBuilder);
            jsonBuilder.append('"');
        } else if (value instanceof Number) {
            jsonBuilder.append(String.valueOf(value));
        } else if (value instanceof Boolean) {
            jsonBuilder.append(value.toString());
        } else if (value instanceof Character) {
            jsonBuilder.append('"');
            escapeJsonString(String.valueOf(value), jsonBuilder);
            jsonBuilder.append('"');
        } else if (value instanceof Iterable) {
            jsonBuilder.append('[');
            boolean first = true;
            for (Object item : (Iterable<?>) value) {
                if (!first) {
                    jsonBuilder.append(',');
                }
                writeValue(jsonBuilder, item);
                first = false;
            }
            jsonBuilder.append(']');
        } else if (value instanceof Map) {
            jsonBuilder.append('{');
            boolean first = true;
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) value).entrySet()) {
                if (!first) {
                    jsonBuilder.append(',');
                }
                jsonBuilder.append('"');
                escapeJsonString(entry.getKey().toString(), jsonBuilder);
                jsonBuilder.append('"');
                jsonBuilder.append(':');
                writeValue(jsonBuilder, entry.getValue());
                first = false;
            }
            jsonBuilder.append('}');
        } else {
            throw new IOException("Unsupported type: " + value.getClass().getName());
        }
    }

    private static void escapeJsonString(String str, StringBuilder jsonBuilder) {
        for (char c : str.toCharArray()) {
            switch (c) {
                case '"':
                    jsonBuilder.append("\\\"");
                    break;
                case '\\':
                    jsonBuilder.append("\\\\");
                    break;
                case '\b':
                    jsonBuilder.append("\\b");
                    break;
                case '\f':
                    jsonBuilder.append("\\f");
                    break;
                case '\n':
                    jsonBuilder.append("\\n");
                    break;
                case '\r':
                    jsonBuilder.append("\\r");
                    break;
                case '\t':
                    jsonBuilder.append("\\t");
                    break;
                default:
                    if (c < ' ') {
                        jsonBuilder.append(String.format("\\u%04x", (int) c));
                    } else {
                        jsonBuilder.append(c);
                    }
            }
        }
    }
