import java.util.*;
import java.util.function.Function;

public class WeightedItemNormalizer {
    public static <T> Map<T, Double> normalizeWeights(List<WeightedItem<T>> items, Function<T, Double> weightFunction) {
        // Calculate the total weight of all items
        double totalWeight = 0.0;
        for (WeightedItem<T> item : items) {
            totalWeight += weightFunction.apply(item.getItem());
        }

        // Check for potential integer overflow
        if (Double.isInfinite(totalWeight) || Double.isNaN(totalWeight)) {
            throw new IllegalArgumentException("Total weight is invalid.");
        }

        // Create a map to store the normalized weights
        Map<T, Double> normalizedWeights = new HashMap<>();

        // Calculate and store the normalized weights for each item
        for (WeightedItem<T> item : items) {
            T currentItem = item.getItem();
            double weight = weightFunction.apply(currentItem);
            double normalizedWeight = weight / totalWeight;

            // Check for potential integer overflow in the division
            if (Double.isInfinite(normalizedWeight) || Double.isNaN(normalizedWeight)) {
                throw new IllegalArgumentException("Normalized weight is invalid.");
            }

            normalizedWeights.put(currentItem, normalizedWeight);
        }

        return normalizedWeights;
    }

    // Define a class to represent weighted items
    public static class WeightedItem<T> {
        private final T item;
        private final double weight;

        public WeightedItem(T item, double weight) {
            this.item = item;
            this.weight = weight;
        }

        public T getItem() {
            return item;
        }

        public double getWeight() {
            return weight;
        }
    }
}
