import java.util.*;

public class DisjointPairs {
    private int[] parent;
    private int[] rank;

    public DisjointPairs(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    private int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]); // Path compression
        }
        return parent[p];
    }

    private void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP != rootQ) {
            if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }

    public int countDisjointPairs(int[] nums) {
        int n = nums.length;
        DisjointPairs uf = new DisjointPairs(n);
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                if (uf.find(i) != uf.find(j)) {
                    uf.union(i, j);
                }
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");
        return n * (n - 1) / 2; // Number of pairs in a set of size n
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 4, 5};
        DisjointPairs dp = new DisjointPairs();
        System.out.println("Number of disjoint pairs: " + dp.countDisjointPairs(nums));
    }
}
