import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class UrlHashGenerator {
    public static String generateSha1Hash(String url) throws NoSuchAlgorithmException {
        // Check if the URL is null or empty
        if (url == null || url.isEmpty()) {
            throw new IllegalArgumentException("URL must not be blank");
        }

        // Create a MessageDigest instance for SHA-1
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");

        // Compute the hash of the URL string
        byte[] hashBytes = sha1.digest(url.getBytes());

        // Convert the byte array to a hexadecimal string
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    }
}
