import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class TraceIdentifierGenerator {
    private static final int TIMESTAMP_LENGTH = 16;
    private static final int RANDOM_LENGTH = 16;

    public String generateTraceIdentifier() {
        // Generate timestamp
        SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMddHHmmssSSS", Locale.US);
        sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
        String timestamp = sdf.format(new Date());

        // Ensure timestamp length is 16 characters (hex digits)
        if (timestamp.length() != TIMESTAMP_LENGTH * 2) {
            throw new IllegalStateException("Timestamp format error: " + timestamp);
        }

        // Generate random number
        SecureRandom secureRandom = new SecureRandom();
        StringBuilder randomHex = new StringBuilder(RANDOM_LENGTH);
        for (int i = 0; i < RANDOM_LENGTH; i++) {
            int nextInt = secureRandom.nextInt(16);
            randomHex.append(Integer.toHexString(nextInt));
        }

        // Combine timestamp and random number to form the trace identifier
        StringBuilder traceIdentifier = new StringBuilder();
        traceIdentifier.append(timestamp);
        traceIdentifier.append(randomHex.toString());

        return traceIdentifier.toString();
    }
}
