import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public class GeoPointComparator {
    public static void compareGeoPoints(List<Double> set1, List<Double> set2, double tolerance) throws Exception {
        if (set1 == null || set2 == null) {
            throw new IllegalArgumentException("Sets must not be null");
        }

        if (set1.size() != set2.size()) {
            throw new Exception("Set sizes are different");
        }

        List<Double> sortedSet1 = new ArrayList<>(set1);
        Collections.sort(sortedSet1);

        List<Double> sortedSet2 = new ArrayList<>(set2);
        Collections.sort(sortedSet2);

        for (int i = 0; i < sortedSet1.size(); i++) {
            if (Math.abs(sortedSet1.get(i) - sortedSet2.get(i)) > tolerance) {
                throw new Exception("Values at position " + i + " are not within the specified tolerance");
            }
        }
    }
}
