import java.util.Properties;

public class EventService {
    private EntityManagerFactory entityManagerFactory;

    public EventService(Properties properties) {
        this.entityManagerFactory = Persistence.createEntityManagerFactory("myPersistenceUnit", properties);
    }

    public long saveEvent(String tipo, String descricao) {
        EntityManager em = entityManagerFactory.createEntityManager();
        try {
            em.getTransaction().begin();
            Event event = new Event();
            event.setTipo(tipo);
            event.setDescricao(descricao);
            em.persist(event);
            em.getTransaction().commit();
            return event.getId();
        } catch (Exception e) {
            em.getTransaction().rollback();
            throw new IllegalArgumentException("Invalid parameters or database error: " + e.getMessage());
        } finally {
            em.close();
        }
    }
}

