    public boolean verifyDelegationToken(String tokenIdentifier) {
        if (tokenIdentifier == null || !tokens.containsKey(tokenIdentifier)) {
            throw new IllegalArgumentException("Invalid token identifier");
        }

        // Check if the token is valid and not expired
        return tokens.get(tokenIdentifier) != null;
    }

    public boolean renewDelegationToken(String tokenIdentifier, String userCredentials) {
        if (tokenIdentifier == null || userCredentials == null) {
            throw new IllegalArgumentException("Invalid input: credentials and token identifier must not be null");
        }

        // Validate the token and ensure it matches the provided user credentials
        if (!tokens.containsKey(tokenIdentifier) || !tokens.get(tokenIdentifier).equals(userCredentials)) {
            return false;
        }

        // Renew the token by generating a new one
        String newToken = generateToken();
        tokens.put(tokenIdentifier, userCredentials);
        return true;
    }

    public boolean cancelDelegationToken(String tokenIdentifier) {
        if (tokenIdentifier == null || !tokens.containsKey(tokenIdentifier)) {
            throw new IllegalArgumentException("Invalid token identifier");
        }

        // Remove the token from the map
        tokens.remove(tokenIdentifier);
        return true;
    }

    private String generateToken() {
        // Generate a random token string (for demonstration purposes)
        return java.util.UUID.randomUUID().toString();
    }
