import java.util.ArrayList;
import java.util.List;
import java.security.SecureRandom;

class LocationTime {
    double time;
    double latitude;
    double longitude;

    LocationTime(double time, double latitude, double longitude) {
        this.time = time;
        this.latitude = latitude;
        this.longitude = longitude;
    }
}

class SensorData {
    long timestamp;
    String type;
    double[] data;

    SensorData(long timestamp, String type, double[] data) {
        this.timestamp = timestamp;
        this.type = type;
        this.data = data;
    }
}

public class SensorDataGenerator {
    public static List<SensorData> generateSensorData(List<LocationTime> locations, List<double[]> stdDevs, double stepsPerSecond) {
        if (locations == null || stdDevs == null || locations.isEmpty() || stdDevs.size() != locations.size()) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        SecureRandom random = new SecureRandom();
        List<SensorData> sensorDataList = new ArrayList<>();

        for (int i = 0; i < locations.size(); i++) {
            LocationTime location = locations.get(i);
            double[] stdDev = stdDevs.get(i);

            // Generate random accelerometer readings using normal distribution with given standard deviations
            double accX = random.nextGaussian() * stdDev[0];
            double accY = random.nextGaussian() * stdDev[1];
            double accZ = random.nextGaussian() * stdDev[2];

            // Calculate the timestamp in milliseconds
            long timestamp = Math.round(location.time * stepsPerSecond * 1000);

            // Create SensorData object and add it to the list
            sensorDataList.add(new SensorData(timestamp, "ACC", new double[]{accX, accY, accZ}));
        }

        return sensorDataList;
    }
}
