public class AESEncryption {

    public static void main(String[] args) throws Exception {
        String algorithm = "AES";
        int keySize = 128; // AES-128
        String inputMessage = "Hello, World!";

        // Generate a secure random key
        byte[] rawKey = generateKey(keySize);

        // Encrypt the message using CTR mode
        byte[] encryptedBytes = encryptCTR(rawKey, inputMessage.getBytes(StandardCharsets.UTF_8));

