    }

    private static byte[] generateKey(int keySize) throws NoSuchAlgorithmException {
        KeyGenerator keyGen = KeyGenerator.getInstance(algorithm);
        keyGen.init(keySize, SecureRandom.getInstanceStrong());
        return keyGen.generateKey().getEncoded();
    }

    private static byte[] encryptCTR(byte[] rawKey, byte[] inputBytes) throws Exception {
        // Generate a random IV (Initialization Vector)
        byte[] iv = new byte[16];
        SecureRandom.getInstanceStrong().nextBytes(iv);

        // Create a SecretKeySpec from the raw key
        SecretKeySpec skeySpec = new SecretKeySpec(rawKey, algorithm);

        // Initialize the cipher in CTR mode with the IV
        Cipher cipher = Cipher.getInstance("AES/CTR/PKCS5Padding");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, skeySpec, ivSpec);

        // Encrypt the input bytes
        return cipher.doFinal(inputBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
