public class DateIntervalHasher {
    public static String hashAndPrefixInterval(String dateRange) throws ParseException, NoSuchAlgorithmException {
        // Validate the input format
        if (!dateRange.matches("\\d{4}-\\d{2}-\\d{2}/\\d{4}-\\d{2}-\\d{2}")) {
            throw new IllegalArgumentException("Invalid date range format. Expected 'startDate/endDate' in the format 'YYYY-MM-DD/YYYY-MM-DD'.");
