import java.io.*;
import java.net.*;

public class FileDownloader {
    public static URI downloadFile(String fileUrl, int connectTimeout) throws IOException {
        URL url = new URL(fileUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        // Set the connect timeout
        connection.setConnectTimeout(connectTimeout);

        // Send a request and get the response code
        int responseCode = connection.getResponseCode();

        // Check if the response is successful
        if (responseCode == HttpURLConnection.HTTP_OK) {
            // Get the file name from the URL
            String fileName = url.getFile().substring(url.getFile().lastIndexOf('/') + 1);

            // Open an output stream to write the file
            FileOutputStream fos = new FileOutputStream(fileName);
            BufferedOutputStream bos = new BufferedOutputStream(fos);

            // Read from the connection and write to the output stream
            InputStream is = connection.getInputStream();
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                bos.write(buffer, 0, bytesRead);
            }

            // Close the streams
            bos.close();
            fos.close();
            is.close();

            // Return the URI of the downloaded file
            return new File(fileName).toURI();
        } else {
            // Handle unsuccessful response codes
            System.out.println("Failed to download file: " + responseCode);
            return null;
        }
    }
}
