import java.io.*;
import java.util.Hashtable;
import java.util.ArrayList;
import java.util.List;

public class FileDataFilter {
    public static void main(String[] args) {
        // List to store files containing the specified type of data
        List<File> filteredFiles = new ArrayList<>();

        // Path to the directory containing the files
        String pathToDirectory = "path/to/directory";

        // Create a list of files in the directory
        File[] files = new File(pathToDirectory).listFiles();

        if (files == null || files.length == 0) {
            System.out.println("No files found in the directory.");
            return;
        }

        // Iterate through each file and check for specific data type
        for (File file : files) {
            if (file.isDirectory()) continue; // Skip directories

            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                Hashtable<String, String> dataTable = new Hashtable<>();

                while (true) {
                    try {
                        Object obj = ois.readObject();
                        // Assuming the object is of a specific type that we are interested in
                        if (obj instanceof SpecificDataType) {
                            // Add to hashtable for storage and processing
                            dataTable.put(file.getName(), obj.toString());
                        }
                    } catch (ClassNotFoundException | EOFException e) {
                        break; // Exit loop on end of file or class not found
                    }
                }

                if (!dataTable.isEmpty()) {
                    filteredFiles.add(file);
                }
            } catch (FileNotFoundException e) {
                System.out.println("File not found: " + file.getName());
            } catch (IOException e) {
                System.out.println("IO error occurred while reading the file: " + file.getName());
            }
        }

        // Output the list of files containing the specified type of data
        for (File filteredFile : filteredFiles) {
            System.out.println("Filtered File: " + filteredFile.getName());
        }
    }
}
