public class UrlValidator {
    public static List<InetSocketAddress> validateAndResolveUrls(List<String> urls) {
        List<InetSocketAddress> addresses = new ArrayList<>();

        for (String urlStr : urls) {
            try {
                URL url = new URL(urlStr);

                // Validate the URL to ensure it is not blank or null
                if (url.getHost() == null || url.getHost().isEmpty()) {
                    throw new MalformedURLException("Invalid host");
                }

                // Resolve the hostname to an InetAddress
                InetAddress address = InetAddress.getByName(url.getHost());
                String host = address.getHostName();

                // Validate the resolved hostname
                if (host == null || host.isEmpty()) {
                    throw new UnknownHostException("Failed to resolve host");
                }

                // Get the port number, defaulting to 80 for HTTP and 443 for HTTPS
                int port = url.getPort();
                if (port == -1) {
                    port = url.getDefaultPort();
                }

                // Create an InetSocketAddress object with the validated host and port
                InetSocketAddress socketAddress = new InetSocketAddress(host, port);
                addresses.add(socketAddress);
            } catch (MalformedURLException | UnknownHostException e) {
                System.err.println("Error validating or resolving URL: " + urlStr + ": " + e.getMessage());
            }
        }

        return addresses;
    }
}
