public class FileHashCalculator {
    public String calculateFileHash(Path filePath) throws IOException, NoSuchAlgorithmException {
        // Check if the file exists and is readable
        if (filePath == null || !Files.exists(filePath) || !Files.isReadable(filePath)) {
            return null; // Return null for invalid paths to avoid path traversal vulnerabilities
        }

        // Read the content of the file
        byte[] fileBytes = Files.readAllBytes(filePath);

        // Calculate the SHA-1 hash of the file content
        MessageDigest sha1Digest = MessageDigest.getInstance("SHA-1");
        byte[] hashBytes = sha1Digest.digest(fileBytes);

        // Convert the hash bytes to a hexadecimal string representation
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    }
}
