import org.apache.zookeeper.server.ServerCnxnFactory;
import org.apache.zookeeper.server.ZooKeeperServer;
import java.io.File;
import java.net.BindException;
import java.net.InetSocketAddress;

public class ZooKeeperSetup {
    public static void main(String[] args) {
        String logDirectory = "/path/to/log/directory"; // Specify the directory for the transaction log
        int minPort = 2181; // Minimum port number in the range
        int maxPort = 2190; // Maximum port number in the range
        int tickTime = 2000; // Tick time for the server (in milliseconds)
        int sessionTimeout = 30000; // Session timeout for the server (in milliseconds)

        File logFile = new File(logDirectory);
        ZooKeeperServer zkServer = new ZooKeeperServer(logFile, logFile, tickTime);

        ServerCnxnFactory factory = null;
        try {
            for (int port = minPort; port <= maxPort; port++) {
                try {
                    factory = ServerCnxnFactory.createFactory(new InetSocketAddress(port), 0);
                    factory.configure(zkServer, sessionTimeout);
                    zkServer.setSessionTracker(factory.getSessionTracker());
                    break; // Successfully bound to a port, exit the loop
                } catch (BindException e) {
                    // Ignore BindException and try the next port
                    continue;
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        if (factory == null) {
            System.err.println("Failed to bind to any port in the specified range.");
            return;
        }

        zkServer.setSessionTracker(factory.getSessionTracker());
    }
}
