import org.apache.mina.core.future.ConnectFuture;
import org.apache.mina.filter.codec.ProtocolCodecFilter;
import org.apache.mina.filter.executor.ExecutorFilter;
import org.apache.mina.transport.socket.nio.NioSocketConnector;

import java.net.URI;
import java.util.concurrent.Executors;

public class SecureSocketConnection {
    public static NioSocketConnector setupSocketConnection(URI uri, int maxPoolSize) {
        // Validate the URI to ensure it is not blank or null
        if (uri == null || uri.toString().trim().isEmpty()) {
            throw new IllegalArgumentException("Invalid URI: URL must not be blank");
        }

        NioSocketConnector connector = new NioSocketConnector();
        connector.setConnectTimeoutMillis(5000); // Set connection timeout to 5 seconds

        // Create a worker pool executor with the specified maximum pool size
        connector.getFilterChain().addLast("executor", new ExecutorFilter(Executors.newFixedThreadPool(maxPoolSize)));

        // Add filters to the connector (example: ProtocolCodecFilter for encoding/decoding)
        connector.getFilterChain().addLast("codec", new ProtocolCodecFilter());

        // Connect to the specified host and port
        String host = uri.getHost();
        int port = uri.getPort();
        if (host == null || port <= 0) {
            throw new IllegalArgumentException("Invalid URI: Host or Port not found");
        }

        ConnectFuture future = connector.connect(new java.net.InetSocketAddress(host, port));

        // Wait for the connection to be established
        future.awaitUninterruptibly();

        return connector;
    }
}
