import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.KeyPair;
import java.security.KeyStore;
import java.security.NoSuchAlgorithmException;
import java.security.cert.CertificateException;
import java.util.Base64;

public class KeyStoreGenerator {

    public static void main(String[] args) {
        if (args.length != 1) {
            System.err.println("Usage: java KeyStoreGenerator <hostname>");
            return;
        }

        String hostname = args[0];
        Path tempDirPath = null;
        Path keystoreFilePath = null;
        try {
            // Create a temporary directory
            tempDirPath = Files.createTempDirectory("keystore");
            keystoreFilePath = tempDirPath.resolve(hostname + ".keystore");

            // Define the store password (should be strong and stored securely)
            String storePassword = "storepass123";

            // Initialize KeyStore
            KeyStore keyStore = KeyStore.getInstance("JKS");
            keyStore.load(null, null);

            // Generate a key pair
            KeyPair keyPair = generateKeyPair();

            // Store the key pair in the keystore
            keyStore.setKeyEntry(hostname, keyPair.getPrivate(), storePassword.toCharArray(), new java.security.cert.Certificate[]{keyPair.getPublic()});

            // Save the keystore to a file
            try (java.io.OutputStream out = Files.newOutputStream(keystoreFilePath)) {
                keyStore.store(out, storePassword.toCharArray());
            }

            System.out.println("Keystore file created at: " + keystoreFilePath);

            // Wait for the command to complete (simulate this by sleeping)
            Thread.sleep(5000);
        } catch (IOException | NoSuchAlgorithmException | CertificateException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            if (tempDirPath != null && Files.exists(tempDirPath)) {
                try {
                    Files.deleteIfExists(keystoreFilePath);
                    Files.deleteIfExists(tempDirPath);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private static KeyPair generateKeyPair() throws NoSuchAlgorithmException {
        java.security.KeyPairGenerator keyPairGenerator = java.security.KeyPairGenerator.getInstance("RSA");
        keyPairGenerator.initialize(2048);
        return keyPairGenerator.generateKeyPair();
    }
}
