import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;
import javax.swing.JFrame;
import javax.swing.JLabel;

public class ImageRotator {

    public static void main(String[] args) {
        if (args.length != 2) {
            System.err.println("Usage: java ImageRotator <image_path> <angle>");
            System.exit(1);
        }

        String imagePath = args[0];
        String angle = args[1];

        try {
            // Rotate the image using an external tool (e.g., ImageMagick)
            Process process = new ProcessBuilder("convert", imagePath, "-rotate", angle, imagePath).start();
            int exitCode = process.waitFor();

            if (exitCode != 0) {
                System.err.println("Error: Failed to rotate the image.");
                System.exit(1);
            }

            // Load and display the rotated image
            BufferedImage rotatedImage = ImageIO.read(new File(imagePath));
            JFrame frame = new JFrame();
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.getContentPane().add(new JLabel(new ImageIcon(rotatedImage)));
            frame.pack();
            frame.setVisible(true);

        } catch (IOException | InterruptedException e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(1);
        }
    }
}
