import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HashFunctionGenerator {
    public static String generateHash(String input, String algorithm) throws NoSuchAlgorithmException {
        // Validate the input string to ensure it is not null or empty
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string must not be null or empty");
        }

        // Convert the input string to bytes
        byte[] inputBytes = input.getBytes();

        // Get the MessageDigest instance for the specified algorithm
        MessageDigest messageDigest = MessageDigest.getInstance(algorithm);

        // Compute the hash of the input data
        byte[] hashBytes = messageDigest.digest(inputBytes);

        // Convert the byte array to a hexadecimal string representation
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        // Return the hexadecimal string representation of the hash
        return hexString.toString();
    }

    public static void main(String[] args) {
