import java.security.NoSuchAlgorithmException;

public class FileHashGenerator {

    public static void generateMd5Hash(String filePath) {
        try {
            // Read the file content
            byte[] fileContent = readFileContent(filePath);

            // Generate MD5 hash of the file content
            String md5Hash = calculateMd5Hash(fileContent);

            // Create a new file with .md5 extension and write the hash to it
            String md5FilePath = filePath + ".md5";
            writeToFile(md5FilePath, md5Hash);

            System.out.println("MD5 hash generated successfully for file: " + filePath);
