import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Date;
import java.util.TreeMap;

public class ETagGenerator {
    public static String generateETag(Change change, ProjectState projectState) {
        // Collect data for the hash calculation
        long lastUpdatedTimestamp = new Date().getTime();
        int rowVersion = change.getRowVersion();
        String accountId = change.getCurrentUserAccountId();

        StringBuilder sb = new StringBuilder();
        sb.append(lastUpdatedTimestamp).append(".").append(rowVersion).append(".").append(accountId);

        // Iterate over project revisions and append revision ID to the hash string
        for (Revision revision : projectState.getRevisions()) {
            sb.append(".").append(revision.getId());
        }

        // Generate MD5 hash of the collected data
        return computeMD5Hash(sb.toString());
    }

    private static String computeMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] resultBytes = md.digest(input.getBytes());

            // Convert the byte array to a hexadecimal string
            StringBuilder sb = new StringBuilder();
            for (byte b : resultBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not available.", e);
        }
    }
}
