import java.net.InetSocketAddress;
import java.nio.channels.DatagramChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DatagramConnector {
    public static DatagramConnector create(String uri, boolean transferExchange) throws IllegalArgumentException {
        if (transferExchange) {
            throw new IllegalArgumentException("Transfer exchange is set to true");
        }

        // Validate the URI and ensure it is not blank or null
        if (uri == null || uri.trim().isEmpty()) {
            throw new IllegalArgumentException("Invalid URI: URI cannot be null or empty");
        }

        // Split the URI to extract host and port information
        String[] parts = uri.split(":");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid URI: URI must contain both host and port separated by ':'");
        }

        String host = parts[0];
        int port;
        try {
            port = Integer.parseInt(parts[1]);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid URI: Port must be a valid integer");
        }

        // Create and configure the DatagramChannel
        DatagramChannel channel = null;
        try {
            channel = DatagramChannel.open();
            InetSocketAddress address = new InetSocketAddress(host, port);
            channel.bind(address);

            // Configure the processor count (number of available processors)
            int processorCount = Runtime.getRuntime().availableProcessors();
            ExecutorService executor = Executors.newFixedThreadPool(processorCount);
            channel.configureBlocking(false);
            channel.setOption(StandardSocketOptions.SO_REUSEADDR, true);
            channel.register(channel.provider(), 0, new DatagramChannelAttachment(channel, executor));
        } catch (Exception e) {
            if (channel != null) {
                try {
                    channel.close();
                } catch (Exception ignore) {}
            }
            throw new IllegalArgumentException("Failed to create datagram connection: " + e.getMessage());
        }

        return new DatagramConnector(channel, executor);
    }

    private final DatagramChannel channel;
    private final ExecutorService executor;

    private DatagramConnector(DatagramChannel channel, ExecutorService executor) {
        this.channel = channel;
        this.executor = executor;
    }

    public DatagramChannel getChannel() {
        return channel;
    }

    public ExecutorService getExecutor() {
        return executor;
    }
}
