import java.io.*;

public class SerializationVerifier {
    public static <T> T serializeAndDeserialize(T obj) throws IOException, ClassNotFoundException {
        // Serialize the object to a byte array
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);
        objectOutputStream.writeObject(obj);
        objectOutputStream.close();

        // Deserialize the object from the byte array
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(byteArrayOutputStream.toByteArray());
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);
        @SuppressWarnings("unchecked")
        T deserializedObj = (T) objectInputStream.readObject();
        objectInputStream.close();

        // Verify that the deserialized object has the same properties as the original object
        if (!obj.equals(deserializedObj)) {
            throw new IllegalStateException("Deserialized object does not match the original object.");
        }

        return deserializedObj;
    }
}
