import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.anarres.lzo.*;

public class FileCompressor {
    public static String compressFileWithLZO(String filePath, int compressionLevel) throws IOException, NoSuchAlgorithmException {
        // Read the file content
        byte[] fileContent = readFileContent(filePath);

        // Compress the file content using LZO
        byte[] compressedContent = compressContentWithLZO(fileContent, compressionLevel);

        // Calculate the MD5 hash of the compressed content
        String md5Hash = calculateMD5Hash(compressedContent);

        return md5Hash;
    }

    private static byte[] readFileContent(String filePath) throws IOException {
        File file = new File(filePath);
        try (InputStream is = new FileInputStream(file)) {
            ByteArrayOutputStream buffer = new ByteArrayOutputStream();
            int nRead;
            byte[] data = new byte[16384];
            while ((nRead = is.read(data, 0, data.length)) != -1) {
                buffer.write(data, 0, nRead);
            }
            return buffer.toByteArray();
        }
    }

    private static byte[] compressContentWithLZO(byte[] content, int compressionLevel) throws IOException {
        LzoAlgorithm algorithm = LzoAlgorithm.LZO1X;
        LzoCompressor compressor = new LzoLibrary().newCompressor(algorithm, null);
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        LzoOutputStream lzoOutputStream = new LzoOutputStream(outputStream, compressor);
        lzoOutputStream.write(content);
        lzoOutputStream.close();
        return outputStream.toByteArray();
    }

    private static String calculateMD5Hash(byte[] content) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(content);
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
