import javax.security.auth.Subject;
import javax.security.auth.login.LoginContext;
import javax.security.auth.login.LoginException;
import java.net.InetAddress;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.security.PrivilegedAction;
import java.util.concurrent.TimeUnit;

public class KerberosSocketConnection {

    public static Socket connectWithKerberos(String host, int port, String localAddress, int timeout, int pingInterval) throws Exception {
        Subject subject = null;
        try {
            LoginContext lc = new LoginContext("KerberosClient");
            lc.login();
            subject = lc.getSubject();
        } catch (LoginException e) {
            throw new Exception("Kerberos authentication failed", e);
        }

        return Subject.doAs(subject, (PrivilegedAction<Socket>) () -> {
            Socket socket = null;
            try {
                InetAddress localInetAddress = InetAddress.getByName(localAddress);
                if (localInetAddress.isAnyLocalAddress() || localInetAddress.isLoopbackAddress() || localInetAddress.isSiteLocalAddress()) {
                    socket = new Socket();
                    socket.bind(new java.net.InetSocketAddress(localInetAddress, 0));
                } else {
                    throw new UnknownHostException("Invalid local address");
                }

                socket.setSoTimeout(timeout);
                socket.connect(new java.net.InetSocketAddress(host, port), timeout);
                socket.setKeepAlive(true);
                socket.setSoLinger(true, pingInterval);

                return socket;
            } catch (SocketTimeoutException e) {
                throw new RuntimeException("Connection timed out", e);
            } catch (UnknownHostException e) {
                throw new RuntimeException("Unknown host", e);
            } catch (Exception e) {
                throw new RuntimeException("Failed to establish connection", e);
            }
        });
    }
}
