public class SigningTool {
    private static final String KEY_ALGORITHM = "AES";
    private static final int KEY_SIZE = 128;

    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.out.println("Usage: java SigningTool <file>");
            return;
        }

        String filePath = args[0];
        File file = new File(filePath);
        if (!file.exists() || !file.isFile()) {
            System.out.println("The specified file does not exist or is not a file.");
            return;
        }

        // Generate a secret key for signing
        SecretKey secretKey = generateSecretKey();
        byte[] encodedKey = secretKey.getEncoded();

        // Initialize the cipher with the secret key
        Cipher cipher = Cipher.getInstance(KEY_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(encodedKey, KEY_ALGORITHM));

        // Read the file content
        byte[] fileContent = readFileBytes(file);

        // Encrypt the file content with the secret key
        byte[] encryptedContent = cipher.doFinal(fileContent);

        // Write the encrypted content to a new file (signature)
        File outputFile = new File(filePath + ".sig");
        try (OutputStream os = new FileOutputStream(outputFile)) {
            os.write(encryptedContent);
        }

        System.out.println("Signing completed successfully.");
    }

