import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class PackageManagerExecutor {

    public List<String> getInstalledPackages() throws IOException, InterruptedException {
        List<String> installedPackages = new ArrayList<>();
        String command = "dpkg-query -l"; // Example for Debian/Ubuntu package manager

        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

        String line;
        while ((line = reader.readLine()) != null) {
            installedPackages.add(line);
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Command execution failed with exit code: " + exitCode);
        }

        return installedPackages;
    }
}
