import org.xml.sax.*;
import org.xml.sax.helpers.*;
import java.util.*;
import java.io.*;

public class PrefixExtractor extends DefaultHandler {
    private Map<String, Integer> prefixFrequencyMap;

    public PrefixExtractor() {
        prefixFrequencyMap = new HashMap<>();
    }

    @Override
    public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
        // Extract the prefix from the URI if it exists
        int colonIndex = uri.indexOf(':');
        if (colonIndex != -1) {
            String prefix = uri.substring(0, colonIndex);
            prefixFrequencyMap.put(prefix, prefixFrequencyMap.getOrDefault(prefix, 0) + 1);
        }
    }

    public void printPrefixFrequencies() {
        for (Map.Entry<String, Integer> entry : prefixFrequencyMap.entrySet()) {
            System.out.println("Prefix: " + entry.getKey() + ", Frequency: " + entry.getValue());
        }
    }

    public static void main(String[] args) throws Exception {
        SAXParserFactory factory = SAXParserFactory.newInstance();
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        factory.setNamespaceAware(true);

        PrefixExtractor handler = new PrefixExtractor();
        SAXParser parser = factory.newSAXParser();
        for (String fileName : args) {
            parser.parse(new File(fileName), handler);
        }
        handler.printPrefixFrequencies();
    }
}
