import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Map;

public class PathHasher {
    public static String generateHash(Map<String, String> paths, String moduleName, boolean createSymlinks, boolean createHeaderMap) {
        StringBuilder input = new StringBuilder();

        // Append module name and symlink state
        input.append(moduleName).append(createSymlinks);

        // Append header map state if needed
        if (createHeaderMap) {
            for (String key : paths.keySet()) {
                input.append(key).append(paths.get(key));
            }
        }

        // Convert the input string to a byte array
        byte[] inputBytes = input.toString().getBytes();

        try {
            // Create SHA-1 hash object
            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");

            // Compute the hash of the input bytes
            byte[] hashBytes = sha1.digest(inputBytes);

            // Convert the hash bytes to a hexadecimal string
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-1 algorithm not available", e);
        }
    }
}
