import java.util.Arrays;

public class CoordinateParser {
    public static double[] parseCoordinates(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string must not be empty or null.");
        }

        String[] parts = input.split(",");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Input string must contain exactly two coordinates separated by a comma.");
        }

        double[] coordinates = new double[2];
        try {
            for (int i = 0; i < parts.length; i++) {
                coordinates[i] = Double.parseDouble(parts[i].trim());
            }
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid coordinate value.");
        }

        assert coordinates[0] == expectedX && coordinates[1] == expectedY : "Coordinates do not match expected values.";

        return coordinates;
    }
}
