import java.io.*;
import java.util.concurrent.atomic.AtomicReference;

public class SingletonLoader<T> {
    private final Class<T> clazz;
    private static final String FILE_NAME = "singletonInstance.ser";

    public SingletonLoader(Class<T> clazz) {
        this.clazz = clazz;
    }

    public T getInstance() throws IOException, ClassNotFoundException {
        AtomicReference<T> instanceRef = new AtomicReference<>();
        File file = new File(FILE_NAME);

        if (file.exists()) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                instanceRef.set((T) ois.readObject());
            } catch (IOException e) {
                throw new IOException("Failed to read serialized singleton instance", e);
            }
        } else {
            T newInstance = clazz.getDeclaredConstructor().newInstance();
            try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(file))) {
                oos.writeObject(newInstance);
            } catch (IOException | IllegalAccessException | InstantiationException | NoSuchMethodException | InvocationTargetException e) {
                throw new IOException("Failed to create and serialize singleton instance", e);
            }
            instanceRef.set(newInstance);
        }

        return instanceRef.get();
    }
}
