import javax.crypto.Cipher;
import java.security.KeyFactory;
import java.security.PublicKey;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;

public class RSAEncryption {
    public static String encryptString(String input, String base64EncodedPublicKey) throws Exception {
        // Decode the Base64 encoded public key
        byte[] publicKeyBytes = Base64.getDecoder().decode(base64EncodedPublicKey);

        // Get an instance of the RSA public key from the provided bytes
        KeyFactory keyFactory = KeyFactory.getInstance("RSA");
        X509EncodedKeySpec publicKeySpec = new X509EncodedKeySpec(publicKeyBytes);
        PublicKey publicKey = keyFactory.generatePublic(publicKeySpec);

        // Initialize the cipher for encryption using ECB mode and PKCS1Padding
        Cipher cipher = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipher.init(Cipher.ENCRYPT_MODE, publicKey);

        // Encrypt the input string
        byte[] encryptedBytes = cipher.doFinal(input.getBytes());

        // Return the Base64 encoded encrypted string
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }
}
