import java.io.InputStream;
import java.io.OutputStream;
import java.util.Optional;

public class CommandExecutor {
    public int executeCommand(String[] command, InputStream inputStream, OutputStream outputStream, Optional<Long> timeout) throws Exception {
        Process process = Runtime.getRuntime().exec(command);

        // Handle input stream if provided
        if (inputStream != null) {
            try {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
            } catch (Exception e) {
                throw new Exception("Error reading from input stream", e);
            }
        }

        // Set a timeout if provided
        long timeOutMillis = timeout.orElse(60000L); // Default to 60 seconds if no timeout is specified

        try {
            int exitCode = process.waitFor();
            return exitCode;
        } catch (InterruptedException e) {
            throw new Exception("Process was interrupted", e);
        } finally {
            // Ensure the input stream is closed
            if (inputStream != null) {
                try {
                    inputStream.close();
                } catch (Exception e) {
                    throw new Exception("Error closing input stream", e);
                }
            }
        }
    }
}
