import java.io.*;

public class NFA implements Serializable {
    private int windowLength;

    public NFA(int windowLength) {
        this.windowLength = windowLength;
    }

    // Method to serialize the NFA object
    public byte[] serialize() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        oos.writeObject(this);
        return bos.toByteArray();
    }

    // Method to deserialize the NFA object
    public static NFA deserialize(byte[] data) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bis);
        return (NFA) ois.readObject();
    }

    // Method to compare two NFAs for equality
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        NFA nfa = (NFA) obj;
        return windowLength == nfa.windowLength;
    }

    // Override hashCode method to ensure consistent behavior with equals
    public int hashCode() {
        return Integer.hashCode(windowLength);
    }
}
