import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Filter implements Filter {
    private int frequency;

    public MD5Filter(int frequency) {
        this.frequency = frequency;
    }

    @Override
    public byte[] filter(byte[] data) throws NoSuchAlgorithmException {
        // Validate the input data
        if (data == null || data.length == 0) {
            throw new IllegalArgumentException("Input data must not be null or empty");
        }

        // Get an instance of the MD5 message digest algorithm
        MessageDigest md = MessageDigest.getInstance("MD5");

        // Calculate the MD5 hash of the input data
        byte[] hash = md.digest(data);

        // Check if the frequency condition is met
        if (frequency > 0 && Math.random() < 1.0 / frequency) {
            return hash;
        } else {
            return new byte[0]; // Return an empty array if the condition is not met
        }
    }
}
