        String sourceCode = "public class HelloWorld { public static void main(String[] args) { System.out.println(\"Hello, World!\"); } }";
        String className = "HelloWorld";
        String fileName = className + ".java";
        String outputDir = System.getProperty("user.dir");

        try {
            // Write the source code to a file
            File sourceFile = new File(fileName);
            try (FileWriter writer = new FileWriter(sourceFile)) {
                writer.write(sourceCode);
            }

            // Compile the source code
            JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
            int compilationResult = compiler.run(null, null, null, "-d", outputDir, fileName);

            if (compilationResult == 0) {
                System.out.println("Compilation successful.");
                // Read the compiled bytecode
                byte[] bytecode = Files.readAllBytes(Paths.get(outputDir, className + ".class"));
                // Write the bytecode to a file
                Files.write(Paths.get(outputDir, className + ".class"), bytecode);
                System.out.println("Bytecode written to " + outputDir + File.separator + className + ".class");
            } else {
                System.out.println("Compilation failed.");
            }

            // Delete the source file
            sourceFile.delete();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
