import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;

public class FileUploader {
    public static boolean uploadFile(String fileToUploadPath, String serverUrl) throws IOException {
        int retryCount = 0;
        while (retryCount < 3) {
            try {
                URL url = new URL(serverUrl);
                HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                connection.setRequestMethod("POST");
                connection.setDoOutput(true);

                // Open the file and prepare to upload it
                File file = new File(fileToUploadPath);
                OutputStream outputStream = connection.getOutputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = new FileInputStream(file).read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
                outputStream.flush();
                outputStream.close();

                // Check the response code
                int responseCode = connection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    return true; // Upload successful
                } else {
                    System.out.println("Upload failed with response code: " + responseCode);
                }
            } catch (IOException e) {
                retryCount++;
                System.out.println("Retry attempt: " + retryCount);
                if (retryCount == 3) {
                    throw new IOException("Failed to upload file after 3 attempts", e);
                }
            }
        }
        return false; // Upload failed after all retries
    }
}
