import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class AESEncryption {
    public static String encrypt(String key, String target) throws Exception {
        // Validate the input key and target
        if (key == null || key.isEmpty() || target == null || target.isEmpty()) {
            throw new IllegalArgumentException("Key and target must not be empty");
        }

        // Generate a secret key from the given key
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");

