import javax.xml.xpath.*;
import org.w3c.dom.Document;
import org.w3c.dom.Node;
import java.io.File;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.Transformer;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;

public class XMLModifier {
    public boolean modifyProperty(String groupName, String propertyName, String newValue) throws Exception {
        // Create a DocumentBuilderFactory and configure it to disable external entity processing
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        // Parse the XML file into a Document object
        Document doc = factory.newDocumentBuilder().parse(new File("path_to_xml_file"));

        // Create an XPathFactory and use it to create an XPath object
        XPathFactory xPathFactory = XPathFactory.newInstance();
        XPath xPath = xPathFactory.newXPath();

        // Construct the XPath expression to locate the property group node
        String xpathExpression = "//*[local-name()='" + groupName + "']";

        // Evaluate the XPath expression and get a NodeList of matching nodes
        NodeList groupNodes = (NodeList) xPath.evaluate(xpathExpression, doc, XPathConstants.NODESET);

        if (groupNodes.getLength() == 0) {
            throw new Exception("Property group not found: " + groupName);
        }

        // Iterate over the nodes in the NodeList to find the specific property node
        for (int i = 0; i < groupNodes.getLength(); i++) {
            Node groupNode = groupNodes.item(i);
            xpathExpression = "./*[local-name()='" + propertyName + "']";
            Node propertyNode = (Node) xPath.evaluate(xpathExpression, groupNode, XPathConstants.NODE);

            if (propertyNode != null) {
                // Set the new value of the property node
                propertyNode.setTextContent(newValue);

                // Create a TransformerFactory and use it to create a Transformer object
                TransformerFactory transformerFactory = TransformerFactory.newInstance();
                Transformer transformer = transformerFactory.newTransformer();

                // Write the modified Document back to the XML file
                DOMSource source = new DOMSource(doc);
                StreamResult result = new StreamResult(new File("path_to_xml_file"));
                transformer.transform(source, result);

                return true;
            }
        }

        // If the property node was not found, throw an exception
        throw new Exception("Property not found: " + propertyName);
    }
}
