        ALGORITHM_MAP.put("SHA-1", "SHA-1");
        ALGORITHM_MAP.put("SHA-256", "SHA-256");
        ALGORITHM_MAP.put("SHA-384", "SHA-384");
        ALGORITHM_MAP.put("SHA-512", "SHA-512");
