import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class SecureRandomStringGenerator {
    public static String generateRandomString(double seed) throws NoSuchAlgorithmException {
        // Use a secure hash function like SHA-256
        MessageDigest md = MessageDigest.getInstance("SHA-256");

        // Convert the seed to bytes and update the digest
        byte[] seedBytes = Double.toString(seed).getBytes();
        md.update(seedBytes);

        // Generate the hash value
        byte[] hashBytes = md.digest();

        // Convert the hash value to a 32-digit hexadecimal number
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }
}
