import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MaskGenerator {
    public static byte[] generateMask(int length, byte[] seed, String digestAlgorithm) throws NoSuchAlgorithmException {
        // Ensure the digest algorithm is provided and supported
        if (digestAlgorithm == null || digestAlgorithm.isEmpty()) {
            throw new IllegalArgumentException("Digest algorithm must be specified");
        }

        MessageDigest md = MessageDigest.getInstance(digestAlgorithm);
        int hashLength = md.getDigestLength();
        int numHashes = (int) Math.ceil((double) length / hashLength);

        byte[] mask = new byte[length];
        byte[] buffer = new byte[seed.length + 4]; // Buffer to hold the seed and counter
        byte[] hash;

        for (int i = 0; i < numHashes; i++) {
            int counter = Integer.reverseBytes(i); // Convert counter to big-endian
            System.arraycopy(seed, 0, buffer, 0, seed.length);
            System.arraycopy(toBytes(counter), 0, buffer, seed.length, 4);

            md.update(buffer);
            hash = md.digest();

            int startIndex = i * hashLength;
            int endIndex = Math.min(startIndex + hashLength, length);
            System.arraycopy(hash, 0, mask, startIndex, endIndex - startIndex);
        }

        return mask;
    }

    private static byte[] toBytes(int value) {
        return new byte[]{
            (byte) (value >> 24),
            (byte) (value >> 16),
            (byte) (value >> 8),
            (byte) value
        };
    }
}
