const execPromise = util.promisify(exec);

async function executeCommand(command) {
    if (!command || typeof command !== 'string' || command.trim().length === 0) {
        throw new Error('Invalid command input.');
    }

    try {
        const { stdout, stderr } = await execPromise(command);
        return { stdout, stderr };
    } catch (error) {
        if (error.code === 'ENOENT') {
            throw new Error(`Command not found: ${command}`);
        } else {
            throw new Error(`Failed to execute command: ${command}\n${error.stderr || error.message}`);
        }
    }
}

async function run() {
    const command = process.argv[2]; // Get the command from the first argument
    if (!command) {
        console.log('Please provide a command to execute.');
        return;
    }

    try {
        const result = await executeCommand(command);
        console.log(`stdout: ${result.stdout}`);
        console.error(`stderr: ${result.stderr}`);
    } catch (error) {
        console.error(error.message);
    }
}

run();
