            const stats = fs.statSync(fullPath);
            if (!stats.isDirectory() && !stats.isFile()) {
                return false;
            }
        } catch (err) {
            if (strictValidation && err.code === 'ENOENT') {
                return false;
            } else {
                throw err;
            }
        }
        return true;
