    // Check if the key exists in the configuration object
    let value = configObj[key];
    if (value !== undefined) {
        return value;
    }

    // Check if a JavaScript file with the same name as the key exists
    const fs = require('fs');
    const path = require('path');

    const filePath = path.resolve(process.cwd(), `${key}.js`);
    if (fs.existsSync(filePath)) {
