```javascript
const fs = require('fs');
const path = require('path');
const less = require('less');

async function compileLessFiles(dir) {
  const results = {};

  async function processFile(filePath) {
    const stats = await fs.promises.stat(filePath);
    if (stats.isDirectory()) {
      return;
    }

    if (path.extname(filePath).toLowerCase() === '.less') {
      try {
        const lessContent = await fs.promises.readFile(filePath, 'utf8');
        const cssContent = await compileLessToCss(lessContent);
        const outputFilePath = filePath.replace(/\.less$/i, '.css');
        results[outputFilePath] = filePath;
      } catch (error) {
        console.error(`Error processing file ${filePath}:`, error);
      }
    }
  }

  async function compileLessToCss(lessContent) {
    const lessResult = await less.render(lessContent, { filename: filePath });
    return lessResult.css;
  }

  async function walkDirectory(dirPath) {
    const items = await fs.promises.readdir(dirPath);
    for (const item of items) {
      const fullPath = path.join(dirPath, item);
      await processFile(fullPath);
    }
  }

  await walkDirectory(dir);
  return results;
}

module.exports = compileLessFiles;
