```javascript
function findAlerts(duration, searchString) {
    // Validate input length
    if (searchString.length > 256) {
        throw new Error("Search string exceeds maximum allowed length");
    }

    // Load configuration file and perform search
    const fs = require('fs');
    const path = require('path');

    const configFilePath = path.join(__dirname, 'config', 'alerts.json');
    if (!fs.existsSync(configFilePath)) {
        throw new Error("Configuration file not found");
    }

    const configData = fs.readFileSync(configFilePath, 'utf-8');
    const alerts = JSON.parse(configData);

    // Filter alerts by duration and search string
    const matchingAlerts = alerts.filter(alert => alert.duration === duration && alert.message.includes(searchString));

    if (matchingAlerts.length === 0) {
        return { count: 0, jumpTarget: null };
    }

    // Find the first occurrence of the search string in the alerts
    const firstAlert = matchingAlerts[0];
    const message = firstAlert.message;
    const index = message.indexOf(searchString);
    const jumpTarget = { lineNumber: 1, characterIndex: index };

    return { count: matchingAlerts.length, jumpTarget: jumpTarget };
}
