    fs.appendFileSync(filePath, text);
    console.log(`Inserted text into file: ${filePath}`);
}

// Function to compile Sass to CSS
function sassToCss(sassFilePath, cssOutputPath) {
    const result = sass.compile(sassFilePath);
    fs.writeFileSync(cssOutputPath, result.css);
    console.log(`Compiled Sass to CSS: ${sassFilePath} -> ${cssOutputPath}`);
}

// Function to compile TypeScript to JavaScript
function tsToJs(tsFilePath, jsOutputPath) {
    const tsSource = fs.readFileSync(tsFilePath, 'utf-8');
    const compiled = typescript.transpileModule(tsSource, { compilerOptions: {} });
    fs.writeFileSync(jsOutputPath, compiled.outputText);
    console.log(`Compiled TypeScript to JavaScript: ${tsFilePath} -> ${jsOutputPath}`);
}

// Function to concatenate files using Lodash
function concatenateFiles(filePaths, outputFilePath) {
    const fileContents = _.map(filePaths, filePath => fs.readFileSync(filePath, 'utf-8'));
    const concatenatedContent = fileContents.join('');
    fs.writeFileSync(outputFilePath, concatenatedContent);
    console.log(`Concatenated files: ${filePaths.join(', ')} -> ${outputFilePath}`);
}

// Example usage
