```javascript
const fs = require('fs');
const path = require('path');

function checkFileExists(dirPath, fileName) {
    const fullPath = path.join(dirPath, fileName);
    try {
        const stats = fs.statSync(fullPath);
        return stats.isFile();
    } catch (err) {
        if (err.code === 'ENOENT') {
            return false;
        }
        throw err;
    }
}

function traverseDirectoryTree(startPath) {
    let results = [];
    const list = fs.readdirSync(startPath);
    list.forEach(file => {
        const filePath = path.join(startPath, file);
        const stats = fs.statSync(filePath);
        if (stats && stats.isDirectory()) {
            results = results.concat(traverseDirectoryTree(filePath));
        } else {
            results.push({ directory: startPath, file: file });
        }
    });
    return results;
}

function checkFilesInDirectoryTree(rootDir, files) {
    const directories = traverseDirectoryTree(rootDir);
    let foundFiles = [];
    directories.forEach(({ directory, file }) => {
        if (files.includes(file)) {
            foundFiles.push({ directory, file });
        }
    });
    return foundFiles;
}

