function dfs(grid, x, y, visitedNodes) {
    const rows = grid.length;
    const cols = grid[0].length;

    // Check if the current position is out of bounds or already visited
    if (x < 0 || y < 0 || x >= rows || y >= cols || grid[x][y].state === 'visited') {
        return;
    }

    // Mark the current node as visited
    grid[x][y].state = 'visited';
    visitedNodes.push(grid[x][y]);

    // Define the directions for DFS (up, down, left, right)
    const directions = [
        [-1, 0], [1, 0], [0, -1], [0, 1]
    ];

    // Recursively visit all adjacent nodes
    for (const direction of directions) {
        dfs(grid, x + direction[0], y + direction[1], visitedNodes);
    }
}

function plantRandomNode(grid) {
    const rows = grid.length;
    const cols = grid[0].length;

    // Generate random positions until a valid one is found
    let newX, newY;
    do {
        newX = Math.floor(Math.random() * rows);
        newY = Math.floor(Math.random() * cols);
    } while (grid[newX][newY].state !== 'unvisited'); // Ensure the node is unvisited

    // Plant a new node with a random value at the found position
    const newValue = Math.floor(Math.random() * 100); // Random value between 0 and 99
    grid[newX][newY] = { x: newX, y: newY, value: newValue, state: 'unvisited' };
}

function plantNodesUntilMax(grid, maxNodes) {
    const rows = grid.length;
    const cols = grid[0].length;

    for (let i = 0; i < maxNodes; i++) {
        plantRandomNode(grid);
    }
}

