```javascript
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

function cloneRepository(repoUrl, branch, targetDir) {
    const repoName = path.basename(repoUrl, '.git');
    const tempPath = path.join('/tmp', repoName);

    // Clone the repository
    exec(`git clone --branch ${branch} --single-branch ${repoUrl} ${tempPath}`, (err, stdout, stderr) => {
        if (err) {
            console.error(`Error cloning repository: ${stderr}`);
            return;
        }
        console.log('Repository cloned successfully.');

        // Path to the binary executable in the repository's 'bin' directory
        const binPath = path.join(tempPath, repoName, 'bin', 'your-binary');

        // Ensure targetDir exists
        if (!fs.existsSync(targetDir)) {
            fs.mkdirSync(targetDir, { recursive: true });
        }

        // Create a symbolic link to the binary executable
        const symlinkPath = path.join(targetDir, 'your-binary');
        try {
            fs.symlinkSync(binPath, symlinkPath);
            console.log('Symbolic link created successfully.');
        } catch (err) {
            console.error(`Error creating symbolic link: ${err}`);
        }
    });
}

// Example usage
cloneRepository('https://github.com/user/repo.git', 'main', '/path/to/target/directory');
```

