const crypto = require('crypto');

function generateUniqueIdentifier(algorithm) {
    // Generate a random 128-bit key for the given algorithm
    const hash = crypto.createHash(algorithm);
    hash.update(Date.now().toString() + Math.random().toString());
    return hash.digest('hex');
}

function encryptAndSendMessage(message, key) {
    // Ensure the message and key are properly encoded
    if (typeof message !== 'string' || typeof key !== 'string') {
        throw new Error('Invalid input: message and key must be strings');
    }

    const iv = crypto.randomBytes(16); // Generate a random IV for each encryption
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key, 'hex'), iv);

    let encryptedMessage = cipher.update(message, 'utf8', 'hex');
    encryptedMessage += cipher.final('hex');

    // Send the encrypted message over a network connection (simulated here)
    console.log(`Sending encrypted message: ${encryptedMessage}`);
}

