const fs = require('fs');
const path = require('path');

function validateAndCreateFiles(directoryPath, options) {
    // Ensure directory exists and is writable
    if (!fs.existsSync(directoryPath)) {
        throw new Error(`Directory ${directoryPath} does not exist.`);
    } else if (!fs.lstatSync(directoryPath).isDirectory()) {
        throw new Error(`${directoryPath} is not a directory.`);
    } else if (!fs.accessSync(directoryPath, fs.constants.W_OK)) {
        throw new Error(`No write permissions for ${directoryPath}.`);
    }

    // Validate and create files/directories specified in options
    Object.keys(options).forEach(key => {
        const fullPath = path.join(directoryPath, key);
        if (fs.lstatSync(fullPath, { throwIfNoEntry: false }) && !fs.lstatSync(fullPath).isDirectory()) {
            throw new Error(`${fullPath} exists but is not a directory.`);
        } else if (!fs.existsSync(fullPath)) {
            fs.mkdirSync(fullPath, { recursive: true });
        }
    });

    // Generate an empty file if specified in options and it does not exist
    if (options.emptyFile && !fs.existsSync(path.join(directoryPath, options.emptyFile))) {
        fs.writeFileSync(path.join(directoryPath, options.emptyFile), '');
    }
}

// Example usage:
