```javascript
function generateUUIDv4() {
    const crypto = require('crypto');

    // Generate 16 random bytes
    let bytes = crypto.randomBytes(16);

    // Set the version (4) and variant (RFC4122)
    bytes[6] = (bytes[6] & 0x0F) | 0x40; // Version 4
    bytes[8] = (bytes[8] & 0x3F) | 0x80; // Variant RFC4122

    // Convert to a UUID string format
    let uuid = [
        bytes.slice(0, 4).toString('hex'), // Time low
        bytes.slice(4, 6).toString('hex'), // Time mid
        bytes.slice(6, 8).toString('hex'), // Time high and version
        bytes.slice(8, 10).toString('hex'), // Clock seq hi and reserved
        bytes.slice(10, 16).toString('hex') // Node
    ].join('-');

    return uuid;
}
