// JavaScript function to implement autocomplete feature using AJAX and Handlebars templates
document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('search-input');
    const suggestionsList = document.getElementById('suggestions-list');

    // Function to fetch data from PHP script via AJAX
    async function fetchSuggestions(query) {
        try {
            const response = await fetch(`/php/autocomplete.php?q=${encodeURIComponent(query)}`);
            if (!response.ok) {
                throw new Error('Network response was not ok');
            }
            const data = await response.json();
            return data;
        } catch (error) {
            console.error('There has been a problem with your fetch operation:', error);
            return [];
        }
    }

    // Function to render suggestions using Handlebars templates
    function renderSuggestions(suggestions) {
        const source = document.getElementById('suggestion-template').innerHTML;
        const template = Handlebars.compile(source);
        suggestionsList.innerHTML = template({ suggestions });
    }

    // Event listener for input field to show/update suggestions
    searchInput.addEventListener('input', async (event) => {
        const query = event.target.value;
        if (query.length < 3) {
            suggestionsList.innerHTML = '';
            return;
        }
        const suggestions = await fetchSuggestions(query);
        renderSuggestions(suggestions);
    });

    // Event listener for suggestion list to handle selection
    suggestionsList.addEventListener('click', async (event) => {
        if (event.target.tagName === 'LI') {
            const selectedProduct = event.target.dataset;
            searchInput.value = `${selectedProduct.name} (${selectedProduct.upc})`;
            suggestionsList.innerHTML = '';
        }
    });
});
