const { v4: uuidv4 } = require('uuid');

class UniqueIdentifierGenerator {
  constructor() {
    this.identifiers = new Map();
  }

  generateUniqueId(key) {
    const randomPostfix = uuidv4().substring(0, 5); // Generate a random postfix using UUID v4
