function animateElements(scene) {
    // Ensure elements exist and are properly configured
    if (!scene || !scene.title || !scene.button || !scene.minesImage) {
        throw new Error("Scene, title, button, or minesImage is not defined.");
    }

    const targetAngle = 360; // Full rotation in degrees
    const durationRange = { min: 5000, max: 10000 };

    function getRandomDuration() {
        return Phaser.Math.Between(durationRange.min, durationRange.max);
    }

    scene.tweens.add({
        targets: [scene.title, scene.button, scene.minesImage],
        angle: targetAngle,
        ease: Phaser.Easing.Linear.None,
        duration: getRandomDuration(),
        onComplete: () => {
            if (typeof scene.onAnimationEnd === 'function') {
                scene.onAnimationEnd();
            }
        }
    });
}
