const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

function isValidPackageName(name) {
    // Allow alphanumeric characters, underscores, hyphens, dots, and slashes
    const pattern = /^[a-zA-Z0-9_\-\.\/]+$/;
    return pattern.test(name);
}

function createDebianPackage(packageName) {
    if (!isValidPackageName(packageName)) {
        throw new Error('Invalid package name');
    }

    const tempDir = fs.mkdtempSync('/tmp/dpkg-deb-XXXXXX');
    const controlFileContent = `Package: ${packageName}\nVersion: 0.1\nArchitecture: all\nMaintainer: yourname@example.com\nDescription: A sample package`;
    const controlFilePath = path.join(tempDir, 'control');
    fs.writeFileSync(controlFilePath, controlFileContent);

    exec(`dpkg-deb --build ${tempDir}`, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error creating Debian package: ${stderr}`);
            process.exit(1);
        } else {
            console.log(`Debian package created successfully at ${tempDir}.deb`);
        }
    });
}

function createRedHatPackage(packageName) {
    if (!isValidPackageName(packageName)) {
        throw new Error('Invalid package name');
    }

    const tempDir = fs.mkdtempSync('/tmp/rpmbuild-XXXXXX');
    const specFileContent = `Name: ${packageName}\nVersion: 0.1\nRelease: 1\nGroup: Development/Tools\nSummary: A sample package\nLicense: GPL\n%description\nA sample package for testing`;
    const specFilePath = path.join(tempDir, 'SPECS', `${packageName}.spec`);
    fs.mkdirSync(path.join(tempDir, 'SPECS'));
    fs.writeFileSync(specFilePath, specFileContent);

    exec(`rpmbuild -ba ${specFilePath}`, { cwd: tempDir }, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error creating Red Hat package: ${stderr}`);
            process.exit(1);
        } else {
            const rpmFilePath = path.join(tempDir, 'RPMS', 'noarch', `${packageName}-0.1-1.noarch.rpm`);
            console.log(`Red Hat package created successfully at ${rpmFilePath}`);
        }
    });
}

function main() {
    const packageName = process.argv[2];
    if (!packageName) {
        console.error('Please provide a package name');
        process.exit(1);
    }

    try {
        createDebianPackage(packageName);
        // Check for rpmbuild availability and create Red Hat package
        exec(`which rpmbuild`, (error, stdout, stderr) => {
            if (!error) {
                createRedHatPackage(packageName);
            } else {
                console.log('rpmbuild is not available');
            }
        });
    } catch (error) {
        console.error(`Error: ${error.message}`);
        process.exit(1);
    }
}

main();
