function generateUniqueIdentifier(length, charset, existingIdentifiers) {
    if (length <= 0 || !charset || typeof charset !== 'string') {
        throw new Error('Invalid input parameters');
    }

    const maxRetries = 100; // Limit the number of retries to avoid infinite loops
    let identifier;
    let retryCount = 0;

    do {
        if (retryCount >= maxRetries) {
            throw new Error('Unable to generate a unique identifier after ' + maxRetries + ' attempts');
        }

        // Generate the identifier using secure random bytes
        const bytes = crypto.getRandomValues(new Uint8Array(length));
        identifier = Array.from(bytes, byte => charset[byte % charset.length]).join('');

        retryCount++;
    } while (existingIdentifiers.includes(identifier));

    return identifier;
}
