  "Genesis": "Gen",
  "Exodus": "Exod",
  "Leviticus": "Lev",
  "Numbers": "Num",
  "Deuteronomy": "Deut",
  // Add more books as needed
};

function getBookAbbreviation(bookName) {
  if (!bookName) {
    return null;
  }

  const regex = new RegExp(`\\b(${Object.keys(bookAbbreviations).join('|')})\\b`, 'i');
  const match = bookName.match(regex);

  if (match && match[1]) {
    return bookAbbreviations[match[1].charAt(0).toUpperCase() + match[1].slice(1)];
  } else {
    return null;
  }
}
