def pack_values(format_string, values):
    # Validate format string using regular expression
    if not re.match(r'^[a-zA-Z%]', format_string):
        raise ValueError("Invalid format string")

    # Parse the format string and calculate the number of bytes for each specifier
    pattern = re.compile(r'([a-zA-Z%])')
    specifiers = pattern.findall(format_string)

    if not specifiers:
        raise ValueError("No valid format specifiers found")

