function checkElementVisibilityAndExecute(elementId) {
    const element = document.getElementById(elementId);

    if (!element) {
        console.error(`Element with id ${elementId} not found.`);
        return;
    }

    // Check if the element is an iframe and visible
    if (element.tagName === 'IFRAME' && element.style.display !== 'none') {
        const updatedSrc = `${element.src}?enableJsApi=true`;
        element.src = updatedSrc;

        // Send a message to the contentWindow to mute the volume
        if (element.contentWindow) {
            element.contentWindow.postMessage('mute', '*');
        } else {
            console.error('Unable to send message to contentWindow.');
        }

        // Set width and height of the iframe to empty strings
        element.style.width = '';
        element.style.height = '';

        // Retrieve the dimensions of the iframe
        const rect = element.getBoundingClientRect();
        console.log(`Width: ${rect.width}, Height: ${rect.height}`);

        // Execute a load event listener on the iframe
        element.onload = function() {
            console.log('Iframe loaded successfully.');
        };
    } else {
        console.error(`Element with id ${elementId} is not an iframe or is not visible.`);
    }
}
