```javascript
function parseCSSSelector(cssString) {
    // Trim leading and trailing whitespace
    cssString = cssString.trim();

    // Define regular expressions for parsing CSS selectors
    const combinatorRegex = /([>+~])\s*/g;
    const simpleSelectorRegex = /((?:[.#]?[_a-zA-Z][_a-zA-Z0-9-]*(?:\.[_a-zA-Z][_a-zA-Z0-9-]*)?|\*|:not\(.*?\)))(?=\s*[,>+~])/g;
    const attributeSelectorRegex = /\[(?:[^[\]]+|\[(?:[^\[\]]+|\[[^[\]]+\])*\])*\]\s*(?:[#.:][_a-zA-Z][_a-zA-Z0-9-]*)|\[:[^-_a-zA-Z][^-_a-zA-Z0-9]+(?:\([^()]*\))?(?=\s*[,>+~])/g;

    // Replace escaped characters in the CSS string
    cssString = cssString.replace(/\\([!"#$%&'()*+,./:;<=>?@[\\\]^`{|}~-])/g, '$1');

    // Extract combinators
    const combinators = [];
    let match;
    while ((match = combinatorRegex.exec(cssString)) !== null) {
        combinators.push(match[1]);
    }

    // Extract simple selectors and attribute tests
    const simpleSelectors = [];
    const attributeTests = [];
    while ((match = simpleSelectorRegex.exec(cssString)) !== null || (match = attributeSelectorRegex.exec(cssString)) !== null) {
        if (match[1].startsWith('[') && match[1].endsWith(']')) {
            attributeTests.push(match[1]);
        } else {
            simpleSelectors.push(match[1]);
        }
    }

    // Return the parsed selector components
    return {
        combinators: combinators,
        simpleSelectors: simpleSelectors,
        attributeTests: attributeTests
    };
}
