    const greetings = {
        morning: ["Good Morning!", "Morning Sunshine!", "Rise and Shine!"],
        afternoon: ["Good Afternoon!", "Afternoon Delight!", "Hello Noon!"],
        evening: ["Good Evening!", "Evening Star!", "Nighty Night!"]
    };

    const currentHour = new Date().getHours();

    if (currentHour >= 6 && currentHour < 12) {
        return getRandomGreeting(greetings.morning);
