    // Check if currentNode is null or undefined
    if (!currentNode) {
        throw new Error("Current node cannot be null or undefined");
    }

    // Retrieve the sub-indices of the current node
    const subIndices = getSubIndices(currentNode);

    // If subIndices are not available, load them from a separate script file
    if (!subIndices) {
        const subIndicesData = loadSubIndicesFromFile(path);
        setSubIndices(currentNode, subIndicesData);
        return traverseTree(currentNode, path);
    }

    // Recursively call the function with the sub-indices and the relative path to the current node
    for (const index in subIndices) {
        if (subIndices.hasOwnProperty(index)) {
            const childNode = getChildNodeById(currentNode, index);
            if (childNode) {
                traverseTree(childNode, `${path}/${index}`);
            }
        }
    }
}

// Example functions to replace placeholders
function getSubIndices(node) {
    // Implement this function to return the sub-indices of a node
    return node.subIndices;
}

function setSubIndices(node, subIndicesData) {
    // Implement this function to set the sub-indices for a node
    node.subIndices = subIndicesData;
}

function getChildNodeById(parentNode, id) {
    // Implement this function to return the child node by its unique ID
    return parentNode.children.find(child => child.id === id);
}

function loadSubIndicesFromFile(path) {
    // Implement this function to load sub-indices from a separate script file based on the path
    const fs = require('fs');
    const filePath = `${__dirname}/subIndices/${path}.json`;
    try {
        const data = fs.readFileSync(filePath, 'utf8');
        return JSON.parse(data);
    } catch (error) {
        console.error(`Error loading sub-indices from file: ${error}`);
        return null;
    }
}
