const fs = require('fs');
const path = require('path');

function loadHandlersAndHelpers(config) {
  const apiKey = config.apiKey;
  let failCount = config.failCount || 0;
  const handlersObject = {};
  const helpersObject = {};

  // Function to check if a file is a JavaScript file
  function isJavaScriptFile(file) {
    return path.extname(file).toLowerCase() === '.js' && file !== 'index.js';
  }

  // Read the directory and load handlers and helpers
  const dirPath = config.handlersDir;
  if (!fs.existsSync(dirPath)) {
    throw new Error(`Directory ${dirPath} does not exist`);
  }

  fs.readdirSync(dirPath).forEach((file) => {
    if (isJavaScriptFile(file)) {
      const filePath = path.join(dirPath, file);
      try {
        const handlerModule = require(filePath);
        handlersObject[path.basename(file, '.js')] = handlerModule;
      } catch (err) {
        failCount++;
        console.error(`Failed to load ${file}:`, err);
      }
    }
  });

  // Load helper functions from helpers directory
  const helpersDirPath = config.helpersDir || path.join(dirPath, 'helpers');
  if (!fs.existsSync(helpersDirPath)) {
    throw new Error(`Helpers directory ${helpersDirPath} does not exist`);
  }

  fs.readdirSync(helpersDirPath).forEach((file) => {
    if (isJavaScriptFile(file)) {
      const filePath = path.join(helpersDirPath, file);
      try {
        const helperModule = require(filePath);
        helpersObject[path.basename(file, '.js')] = helperModule;
      } catch (err) {
        failCount++;
        console.error(`Failed to load helper ${file}:`, err);
      }
    }
  });

  return { handlers: handlersObject, helpers: helpersObject, failCount };
}
