function generateNestedArray(dimensions) {
    // Validate input dimensions
    if (!Array.isArray(dimensions) || dimensions.some(dim => typeof dim !== 'number' || dim <= 0)) {
        throw new Error('Invalid array dimensions');
    }

    // Helper function to create the nested array
    function createArray(dims) {
        const [first, ...rest] = dims;
        if (rest.length === 0) {
            return Array(first).fill(null);
        }
        return Array.from({ length: first }, () => createArray(rest));
    }

    // Create and return the nested array based on dimensions
    return createArray(dimensions);
}

function evaluateNestedArray(array) {
    if (!Array.isArray(array)) {
        throw new Error('Invalid input: expected an array');
    }

    function sumArrayValues(arr) {
        let sum = 0;
        for (const item of arr) {
            if (Array.isArray(item)) {
                sum += sumArrayValues(item);
            } else if (typeof item === 'number') {
                sum += item;
            } else {
                throw new Error('Invalid array element: expected number');
            }
        }
        return sum;
    }

    return sumArrayValues(array);
}
