function loadJavaScriptFiles(baseDir, callback) {
  const fs = require('fs');
  const path = require('path');

  function readDirectoryRecursive(dir, filesList) {
    fs.readdir(dir, (err, files) => {
      if (err) {
        console.error(`Error reading directory ${dir}:`, err);
        return callback(err);
      }

      files.forEach((file) => {
        const filePath = path.join(dir, file);
        fs.stat(filePath, (err, stats) => {
          if (err) {
            console.error(`Error getting stats for ${filePath}:`, err);
            return callback(err);
          }

          if (stats.isDirectory()) {
            readDirectoryRecursive(filePath, filesList);
          } else if (path.extname(file) === '.js') {
            require(filePath); // Ensure the path is safe and validated before using it
            filesList.push(filePath);
          }
        });
      });

      callback(null, filesList);
    });
  }

  const filesList = [];
  readDirectoryRecursive(baseDir, filesList);
}
