function createNativeShortcuts(nativeMethods) {
  const shortcuts = {};
  const constructorLookup = {};

  for (const methodName in nativeMethods) {
    if (nativeMethods.hasOwnProperty(methodName)) {
      shortcuts[methodName] = function(...args) {
        return nativeMethods[methodName](...args);
      };
