const crypto = require('crypto');

class LiveStreamDatabase {
  constructor() {
    this.keysList = new Set();
  }

  generateRandomKey(length) {
    return crypto.randomBytes(length).toString('hex');
  }

  addKey(key) {
    if (this.keysList.has(key)) {
      this.removeKey(key);
    } else {
      this.keysList.add(key);
    }
  }

  removeKey(key) {
    this.keysList.delete(key);
  }

  getRandomKey() {
    const keysArray = Array.from(this.keysList);
    if (keysArray.length === 0) return null;
    const randomIndex = Math.floor(Math.random() * keysArray.length);
    return keysArray[randomIndex];
  }
}

