import React, { useState, useEffect } from 'react';
import axios from 'axios';

const VersionSelector = ({ repositoryUrl }) => {
  const [versions, setVersions] = useState([]);
  const [selectedVersion, setSelectedVersion] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchVersions = async () => {
      try {
        const response = await axios.get(repositoryUrl);
        const data = response.data;
        if (Array.isArray(data.versions)) {
          setVersions(data.versions);
          setSelectedVersion(data.latestStableVersion || data.versions[0]);
        } else {
          throw new Error('Invalid version data');
        }
      } catch (err) {
        console.error('Error fetching versions:', err);
        setError('Failed to load versions. Please try again later.');
      }
    };

    fetchVersions();
  }, [repositoryUrl]);

  if (error) {
    return <div>{error}</div>;
  }

  return (
    <div>
      <h1>Select a Version</h1>
      <select value={selectedVersion} onChange={(e) => setSelectedVersion(e.target.value)}>
        {versions.map((version, index) => (
          <option key={index} value={version}>{version}</option>
        ))}
      </select>
    </div>
  );
};

export default VersionSelector;
