const { Buffer } = require('buffer');
const zlib = require('zlib');

function processBase64Data(base64String, callback) {
    // Validate input parameters
    if (typeof base64String !== 'string' || typeof callback !== 'function') {
        throw new Error('Invalid input parameters');
    }

    // Decode the base64 string to a buffer
    const decodedBuffer = Buffer.from(base64String, 'base64');

    // Decompress the buffer using zlib
    zlib.inflate(decodedBuffer, (err, result) => {
        if (err) {
            throw new Error('Decompression failed: ' + err);
        }

        // Convert the decompressed buffer to a hex string
        let hexString = '';
        for (let i = 0; i < result.length; i++) {
            const byte = result[i].toString(16).padStart(2, '0');
            hexString += byte;
        }

        // Parse the hex string into code fragments and time offsets
        const codeFragments = [];
        let timeOffsets = [];
        for (let i = 0; i < hexString.length; i += 4) {
            if (i + 3 >= hexString.length) break; // Ensure we don't go out of bounds

            const codeFragment = parseInt(hexString.slice(i, i + 2), 16);
            const timeOffset = parseInt(hexString.slice(i + 2, i + 4), 16);

            codeFragments.push(codeFragment);
            timeOffsets.push(timeOffset);
        }

        // Call the callback function with the fingerprint object
        callback({
            codeFragments: codeFragments,
            timeOffsets: timeOffsets
        });
    });
}
