function stopEmbeddedContent(slide) {
    const iframe = slide.querySelector('iframe');
    if (!iframe) {
        console.log('No embedded content found in the slide.');
        return;
    }

    const src = iframe.src;
    let postMessageCommand;

    // Determine the type of embedded content based on the src attribute
    if (src.includes('youtube.com') || src.includes('youtu.be')) {
        postMessageCommand = 'pauseVideo';
    } else if (src.includes('player.vimeo.com')) {
        postMessageCommand = 'play'; // Assuming pauseVideo is the command for Vimeo
    } else {
        console.log('Unsupported embedded content type.');
        return;
    }

    // Send the appropriate postMessage command to the iframe
    iframe.contentWindow.postMessage(postMessageCommand, '*');
}
