function parseBuffer(buffer, offset) {
    // Check if the buffer is large enough to contain the action length field (2 bytes)
    if (offset + 2 > buffer.length) {
        return { error: true, message: "Buffer too small to read action length", code: -1 };
    }

    // Extract the length of the action from the buffer
    const length = (buffer[offset] << 8) | buffer[offset + 1];

    // Check if the extracted length is valid (non-negative and within reasonable bounds)
    if (length < 0 || length > 10000) { // Adjust the upper bound as needed
        return { error: true, message: "Invalid action length", code: -2 };
    }

    // Return the extracted action length
    return { actionLength: length, error: false };
}
