const MAX_BUFFER_SIZE = 1024; // Define a maximum buffer size to prevent excessive memory usage

function processStreamData(stream) {
    let dataArray = [];
    let buffer = new Uint8Array(MAX_BUFFER_SIZE);
    let bytesRead = 0;

    while (true) {
        const result = stream.read(buffer.slice(bytesRead, MAX_BUFFER_SIZE));

        if (result === null || result.length === 0) {
            break; // Exit the loop if no more data is available
        }

        bytesRead += result.length;
        dataArray = dataArray.concat(result);

        if (bytesRead >= MAX_BUFFER_SIZE) {
            console.log("Buffer full, pausing stream...");
            stream.pause(); // Pause the stream to prevent overflow

            // Wait for user input or resume signal
            const pauseEvent = new Promise((resolve) => {
                setTimeout(() => resolve('resume'), 1000); // Simulate a delay before resuming
            });

            await pauseEvent;

            console.log("Resuming stream...");
            stream.resume(); // Resume the stream after handling
        }
    }

    return dataArray;
}
```

