function createDraggableObject(minX, maxX, minY, maxY) {
    let isDragging = false;
    let offsetX, offsetY;

    const obj = document.createElement('div');
    obj.style.position = 'absolute';
    obj.style.width = '100px';
    obj.style.height = '100px';
    obj.style.backgroundColor = 'red';
    obj.setAttribute('draggable', true);

    const startBtn = document.createElement('button');
    startBtn.textContent = 'Start Dragging';
    startBtn.addEventListener('mousedown', onDragStart);

    const stopBtn = document.createElement('button');
    stopBtn.textContent = 'Stop Dragging';
    stopBtn.addEventListener('mousedown', onDragEnd);

    document.body.appendChild(startBtn);
    document.body.appendChild(stopBtn);
    document.body.appendChild(obj);

    function onDragStart(event) {
        if (event.target === startBtn || event.target === stopBtn) return; // Ignore button clicks

        isDragging = true;
        offsetX = event.clientX - obj.offsetLeft;
        offsetY = event.clientY - obj.offsetTop;
    }

    function onDrag(event) {
        if (!isDragging) return;

        let x = event.clientX - offsetX;
        let y = event.clientY - offsetY;

        // Ensure the object stays within bounds
        x = Math.max(minX, Math.min(maxX, x));
        y = Math.max(minY, Math.min(maxY, y));

        obj.style.left = `${x}px`;
        obj.style.top = `${y}px`;
    }

    function onDragEnd() {
        isDragging = false;
    }

    document.addEventListener('mousemove', onDrag);

    return {
        obj: obj,
        startBtn: startBtn,
        stopBtn: stopBtn
    };
}
