function createCustomDataStructure(dimension) {
    if (typeof dimension !== 'number' || dimension <= 0) {
        throw new Error('Dimension must be a positive number');
    }

    class CustomArray {
        constructor() {
            this.data = Array(dimension).fill(null);
        }

        pick() {
            return [...this.data];
        }

        set(newData) {
            if (!Array.isArray(newData) || newData.length !== dimension) {
                throw new Error('New data must be an array of the same dimension');
            }
            this.data = newData;
        }

        valueOf(offset) {
            if (typeof offset !== 'number' || offset < 0 || offset >= dimension) {
                throw new Error('Offset must be a number within the bounds of the array');
            }
            return this.data[offset];
        }
    }

    return CustomArray;
}
