```javascript
function scrollToElement() {
    const hash = window.location.hash;
    if (hash) {
        // Remove leading '#' from hash
        const elementId = hash.substring(1);

        let targetElement;
        if (elementId.startsWith('id-')) {
            // Extract the actual ID from the hash
            const id = elementId.substring(3);
            targetElement = document.getElementById(id);
        } else if (elementId === 'top') {
            window.scrollTo({ top: 0, behavior: 'smooth' });
            return;
        } else {
            // Assume it's an anchor name
            targetElement = document.getElementsByName(elementId)[0];
        }

        if (targetElement) {
            targetElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
        } else {
            console.warn(`Element with ID/name "${elementId}" not found.`);
        }
    }
}

// Watch for hash changes and call the function
window.addEventListener('hashchange', scrollToElement);
document.addEventListener('DOMContentLoaded', scrollToElement);
