<?php

use Doctrine\ORM\EntityManager;
use Doctrine\DBAL\Logging\DebugStack;

function truncateTable(EntityManager $entityManager, string $tableName) {
    // Disable foreign key checks temporarily
    $conn = $entityManager->getConnection();
    $conn->executeQuery('SET FOREIGN_KEY_CHECKS=0;');

    // Truncate the table
    $conn->executeUpdate("TRUNCATE TABLE $tableName;");

    // Reset auto-incrementing ID column
    $schemaManager = $conn->getSchemaManager();
    if ($schemaManager->tablesExist($tableName)) {
        $tableMetadata = $schemaManager->listTableDetails($tableName);
        foreach ($tableMetadata->getColumns() as $column) {
            if ($column->getAutoincrement()) {
                $sequenceName = 'default' . strtolower($tableName) . '_' . $column->getName() . '_seq';
                $conn->executeUpdate("ALTER TABLE $tableName AUTO_INCREMENT = 1;");
                // Optionally, reset the sequence if supported by the database
                if ($schemaManager->tablesExist('information_schema.sequences') && $schemaManager->listTableColumns('information_schema.sequences', 'SEQUENCE_NAME')) {
                    $conn->executeUpdate("ALTER SEQUENCE IF EXISTS $sequenceName RESTART WITH 1;");
                }
            }
        }
    }

    // Re-enable foreign key checks
    $conn->executeQuery('SET FOREIGN_KEY_CHECKS=1;');
}
