import java.lang.reflect.Method;
import java.util.*;

public class MethodFilter {
    private static final Set<String> WHITELISTED_METHODS = new HashSet<>(Arrays.asList(
        "getName",
        "getSimpleName",
        "isArray",
        "isAssignableFrom",
        "isEnum",
        "isInstance",
        "isInterface",
        "isLocalClass",
        "isMemberClass",
        "isPrimitive",
        "isSynthetic"
    ));

    public static List<Method> filterMethods(Object obj, Set<String> annotationsToFilter) {
        List<Method> methods = new ArrayList<>();
        Class<?> clazz = obj.getClass();

        while (clazz != null) {
            Method[] allMethods = clazz.getDeclaredMethods();
            for (Method method : allMethods) {
                if (!WHITELISTED_METHODS.contains(method.getName())) {
                    continue;
                }
                if (annotationsToFilter != null && !method.getAnnotations().isEmpty()) {
                    boolean shouldInclude = false;
                    for (Annotation annotation : method.getAnnotations()) {
                        if (!annotationsToFilter.contains(annotation.toString())) {
                            shouldInclude = true;
                            break;
                        }
                    }
                    if (!shouldInclude) {
                        continue;
                    }
                }
                methods.add(method);
            }
            clazz = clazz.getSuperclass();
        }
        return methods;
    }
}
