<?php
function getFileMimeType($filePath) {
    // Check if the system is Unix-based and the file() command is available
    if (strtoupper(substr(PHP_OS, 0, 3)) === 'WIN') {
        return null; // Windows-based system
    }

    if (!function_exists('file')) {
        return null; // The file() function is not available
    }

    // Use the file() command to determine the MIME type
    $output = array();
    exec("file --mime-type " . escapeshellarg($filePath), $output, $return_var);

    if ($return_var !== 0) {
        return null; // The file() command failed
    }

    // Extract the MIME type from the output
    preg_match('/^.*: (.*)$/', $output[0], $matches);
    if (!isset($matches[1])) {
        return null; // Failed to extract the MIME type
    }

    $mimeType = trim($matches[1]);

    // Log the detected MIME type
    error_log("Detected MIME type: " . $mimeType);

    return $mimeType;
}
