    // Open the file for writing
    $fileHandle = fopen($filePath, 'w');
    if (!$fileHandle) {
        return "Failed to create temporary file.";
    }

    // Write headers to force a file download
    header('Content-Type: text/plain');
    header('Content-Disposition: attachment; filename="' . $fileName . '"');

    // Iterate over each item and write its information to the file
    foreach ($items as $item) {
        if (!is_array($item)) {
            continue; // Skip invalid items
        }

        // Validate that the item array contains necessary keys
        if (isset($item['question'], $item['answer']) && is_string($item['question']) && is_string($item['answer'])) {
