<?php
function secure_aes256_encrypt($key, $data) {
    // Validate input
    if (!is_string($key) || !is_string($data)) {
        throw new InvalidArgumentException('Key and data must be strings.');
    }

    // Generate a random IV each time
    $iv = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-ctr'));
    if ($iv === false) {
        throw new RuntimeException('Failed to generate IV.');
    }

