function generate_image($text, $font_path, $width, $height, $position, $direction = 'ltr', $padding = 10) {
    // Validate parameters
    if (!is_string($text) || !is_string($font_path) || !is_int($width) || !is_int($height) || !is_array($position) || !is_string($direction) || !is_int($padding)) {
        throw new InvalidArgumentException("Invalid parameter type.");
    }

    if ($width <= 0 || $height <= 0 || $padding < 0) {
        throw new InvalidArgumentException("Invalid dimension value.");
    }

    // Create image with specified dimensions
    $image = imagecreatetruecolor($width, $height);
    if (!$image) {
        throw new RuntimeException("Failed to create image.");
    }

    // Set background color (white in this case)
    $bg_color = imagecolorallocate($image, 255, 255, 255);
    imagefill($image, 0, 0, $bg_color);

    // Validate text position
    if (!isset($position['x']) || !isset($position['y'])) {
        throw new InvalidArgumentException("Invalid position format.");
    }

    $text_x = max(0, min($width - 1, (int)$position['x']));
    $text_y = max(0, min($height - 1, (int)$position['y']));

    // Add padding to text position
    if ($direction == 'ltr' || $direction == 'rtl') {
        if ($direction == 'ltr') {
            $text_x += $padding;
        } else {
            $text_x -= $padding;
        }
    } elseif ($direction == 'ttb') {
        $text_y += $padding;
    }

    // Load font and add text to image
    if (!file_exists($font_path)) {
        throw new InvalidArgumentException("Font file does not exist.");
    }

    $font = imageloadfont($font_path);
    if (!$font) {
        throw new RuntimeException("Failed to load font.");
    }

    $text_color = imagecolorallocate($image, 0, 0, 0); // Black color for text
    imagestring($image, $font, $text_x, $text_y, $text, $text_color);

    return $image;
}
