<?php
function sanitizeAndQueryLDAP($userInput) {
    // Validate and sanitize input
    if (!is_string($userInput)) {
        $userInput = '';
    } else {
        $userInput = filter_var($userInput, FILTER_SANITIZE_STRING);
    }

    // Connect to LDAP server
    $ldapServer = "ldaps://your.ldap.server:636";
    $ldapConnection = ldap_connect($ldapServer);
    if (!$ldapConnection) {
        die("Could not connect to LDAP server");
    }

    // Set SSL options for secure connection
    ldap_set_option($ldapConnection, LDAP_OPT_PROTOCOL_VERSION, 3);
    ldap_set_option($ldapConnection, LDAP_OPT_REFERRALS, 0);

    // Bind to the LDAP server
    $bindDN = "cn=admin,dc=example,dc=com";
    $bindPassword = "password";
    if (!ldap_bind($ldapConnection, $bindDN, $bindPassword)) {
        die("Could not bind to LDAP server");
    }

    // Construct the search query using sanitized input
    $baseDn = "dc=example,dc=com";
    $filter = "(uid={$userInput})";
    $attributes = array("dn", "cn");

    $searchResult = ldap_search($ldapConnection, $baseDn, $filter, $attributes);
    if (!$searchResult) {
        die("LDAP query failed");
    }

    // Get the entries from the search result
    $entries = ldap_get_entries($ldapConnection, $searchResult);
    if ($entries["count"] == 0) {
        echo "No matching entries found";
    } else {
        return $entries;
    }

    // Close the LDAP connection
    ldap_close($ldapConnection);
}
?>
