<?php

function generateRequestSignature(Request $request) {
    // Check if user is authenticated
    if ($request->user() && $request->user()->isAuthenticated()) {
        $userId = $request->user()->getAuthIdentifier();
        return hash('sha1', $userId);
    }

    // Check if a route is available
    if (Route::current()) {
        $domain = $request->getHost();
        $ipAddress = $request->getClientIp();
        $signatureData = $domain . $ipAddress;
        return hash('sha1', $signatureData);
    }

    // If no user is authenticated and no route is available, throw an exception
    throw new RuntimeException("Request signature cannot be generated.");
}
