<?php

class ConversationLoader {
    private $dataDirectory;
    private $memoryFile;

    public function __construct($dataDirectory, $memoryFile) {
        $this->dataDirectory = $dataDirectory;
        $this->memoryFile = $memoryFile;
    }

    public function loadConversation(Entity $entity): self {
        // Check if the memory file exists
        if (file_exists($this->memoryFile)) {
            // Load the conversation from the memory file
            $conversation = json_decode(file_get_contents($this->memoryFile), true);
        } else {
            // Initialize an empty conversation
            $conversation = [];
        }

        // Add the entity to the conversation
        $conversation['entity'] = $entity;

        // Save the updated conversation back to the memory file
        file_put_contents($this->memoryFile, json_encode($conversation));

        return $this;
    }
}
