import sqlite3

def get_user_id_from_file(file_path):
    """Reads user ID from a text file."""
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file {file_path} does not exist.")

    with open(file_path, 'r') as file:
        user_id = file.readline().strip()

    if not re.match(r'^\d+$', user_id):
        raise ValueError("The extracted ID is not a valid integer.")

    return int(user_id)

def execute_query(database_path, user_id):
    """Executes a SQL query to retrieve data based on the provided user ID."""
    conn = sqlite3.connect(database_path)
    cursor = conn.cursor()

    try:
        query = f"SELECT * FROM your_table WHERE id = {user_id}"
        cursor.execute(query)
        result = cursor.fetchall()

        if not result:
            return None, "No data found for the provided ID."

        columns = [description[0] for description in cursor.description]
        return columns, result

    except sqlite3.Error as e:
        return None, f"An error occurred: {e}"

    finally:
        conn.close()

