<?php
function processFileAndXML($filename, $value) {
    // Read file into buffer and check if read was successful
    $buffer = '';
    $handle = fopen($filename, 'r');
    if ($handle === false) {
        throw new Exception("Failed to open the file.");
    }

    while (($line = fgets($handle)) !== false) {
        $buffer .= $line;
    }

    if (!feof($handle)) {
        throw new Exception("Unexpected end of file.");
    }

    fclose($handle);

    // Perform arithmetic operation on the value in the buffer
    $numericValue = intval($buffer);
    $result = $numericValue + $value;

    // Parse XML and search for a match
    libxml_disable_entity_loader(true);
    $xml = simplexml_load_string($buffer) or die("Error: Cannot create object");

    foreach ($xml->xpath('//match') as $match) {
        if ((string)$match == $value) {
            return $result;
        }
    }

    throw new Exception("Match not found.");
}
?>
