<?php
function createGraphvizImage($dotFilePath, $outputImagePath) {
    // Validate input paths
    if (!is_file($dotFilePath)) {
        throw new InvalidArgumentException("Dot file does not exist.");
    }

    // Check if the output image path is writable
    if (file_exists($outputImagePath) && !is_writable($outputImagePath)) {
        throw new RuntimeException("Output image path is not writable.");
    } elseif (!file_exists($outputImagePath) && !is_writable(dirname($outputImagePath))) {
        throw new RuntimeException("Output image directory is not writable.");
    }

    // Construct the command to execute Graphviz
    $command = "dot -Tpng {$dotFilePath} -o {$outputImagePath}";

    // Execute the command
    exec($command, $output, $return_var);

    // Check if the command executed successfully
    if ($return_var !== 0) {
        throw new RuntimeException("Failed to create Graphviz image: " . implode("\n", $output));
    }

    return $outputImagePath;
}
