function createInteractiveMap() {
    const map = new google.maps.Map(document.getElementById('map'), {
        center: { lat: 0, lng: 0 },
        zoom: 2
    });

    let markers = [];
    let categories = {};

    function addMarker(location, category) {
        const marker = new google.maps.Marker({
            position: location,
            map: map,
            title: 'Location'
        });

        if (!categories[category]) {
            categories[category] = [];
        }
        categories[category].push(marker);
        markers.push(marker);
    }

    function toggleCategory(category) {
        const categoryMarkers = categories[category];
        if (categoryMarkers && categoryMarkers.length > 0) {
            categoryMarkers.forEach(marker => marker.setVisible(!marker.getVisible()));
        }
    }

    return {
        addMarker,
        toggleCategory
    };
}
