```php
<?php

class UserManager {
    private $db;

    public function __construct(Database $db) {
        $this->db = $db;
    }

    public function createUser($acronym, $email, $firstName, $lastName) {
        // Validate input
        if (!preg_match('/^[A-Za-z0-9]{3,10}$/', $acronym)) {
            throw new InvalidArgumentException("Invalid acronym format.");
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new InvalidArgumentException("Invalid email address.");
        }
        if (strlen($firstName) < 2 || strlen($lastName) < 2) {
            throw new InvalidArgumentException("Names must be at least 2 characters long.");
        }

        // Generate a secure password hash
        $passwordHash = password_hash(bin2hex(random_bytes(16)), PASSWORD_BCRYPT);

        // Set creation and activation dates to now
        $creationDate = date('Y-m-d H:i:s');
        $activationDate = date('Y-m-d H:i:s', strtotime('+30 days'));

        // Insert user into the database
        $sql = "INSERT INTO users (acronym, email, first_name, last_name, password_hash, creation_date, activation_date) VALUES (:acronym, :email, :firstName, :lastName, :passwordHash, :creationDate, :activationDate)";
        $stmt = $this->db->prepare($sql);
        $stmt->bindParam(':acronym', $acronym);
        $stmt->bindParam(':email', $email);
        $stmt->bindParam(':firstName', $firstName);
        $stmt->bindParam(':lastName', $lastName);
        $stmt->bindParam(':passwordHash', $passwordHash);
        $stmt->bindParam(':creationDate', $creationDate);
        $stmt->bindParam(':activationDate', $activationDate);
        $stmt->execute();
    }
}
