<?php
function createRecord($url, $trackId, $userId, $createTime, $createDate, $hour, $site, $shortUrl, $httpClientIp, $httpXForwardedFor, $remoteAddr) {
    // Validate the URL to ensure it meets certain security criteria
    if (!filter_var($url, FILTER_VALIDATE_URL)) {
        throw new Exception("Invalid URL");
    }

    // Generate a hash value for the URL
    $hash = hash('sha256', $url);

    try {
        // Connect to the database using PDO
        $db = new PDO('mysql:host=localhost;dbname=your_database_name', 'your_username', 'your_password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Prepare the SQL statement to check if a record with the same hash already exists
        $stmt = $db->prepare("SELECT * FROM your_table_name WHERE hash = :hash LIMIT 1");
        $stmt->execute([':hash' => $hash]);
        $existingRecord = $stmt->fetch();

        // If a record with the same hash already exists, update the views field instead of creating a new one
        if ($existingRecord) {
            $views = $existingRecord['views'] + 1;
            $stmt = $db->prepare("UPDATE your_table_name SET views = :views WHERE hash = :hash");
            $stmt->execute([':views' => $views, ':hash' => $hash]);
        } else {
            // If no record with the same hash exists, create a new one
            $stmt = $db->prepare("INSERT INTO your_table_name (url, track_id, user_id, create_time, create_date, hour, site, short_url, http_client_ip, http_x_forwarded_for, remote_addr, hash, views) VALUES (:url, :trackId, :userId, :createTime, :createDate, :hour, :site, :shortUrl, :httpClientIp, :httpXForwardedFor, :remoteAddr, :hash, 1)");
            $stmt->execute([
                ':url' => $url,
                ':trackId' => $trackId,
                ':userId' => $userId,
                ':createTime' => $createTime,
                ':createDate' => $createDate,
                ':hour' => $hour,
                ':site' => $site,
                ':shortUrl' => $shortUrl,
                ':httpClientIp' => $httpClientIp,
                ':httpXForwardedFor' => $httpXForwardedFor,
                ':remoteAddr' => $remoteAddr,
                ':hash' => $hash
            ]);
        }
    } catch (PDOException $e) {
        // Log the error message and rethrow the exception
        error_log("Database Error: " . $e->getMessage());
        throw new Exception("Failed to create or update record in database");
    }
}
?>
