<?php
function create_user_table($data) {
    // Validate all relevant fields before proceeding
    if (!isset($data['username']) || !isset($data['password']) || !isset($data['email'])) {
        throw new Exception("Incomplete user data");
    }

    $username = htmlspecialchars($data['username'], ENT_QUOTES, 'UTF-8');
    $email = filter_var($data['email'], FILTER_VALIDATE_EMAIL);

    if (!$email) {
        throw new Exception("Invalid email address");
    }

    // Hash the password using a secure hashing algorithm
    $passwordHash = password_hash($data['password'], PASSWORD_BCRYPT);

    // Connect to the database (example connection parameters, adjust as needed)
    $conn = new mysqli('localhost', 'username', 'password', 'database');

    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Prepare and execute the SQL statement to create a new user
    $stmt = $conn->prepare("INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)");
    $stmt->bind_param('sss', $username, $email, $passwordHash);

    if ($stmt->execute()) {
        // Commit the transaction to ensure data is persisted
        $conn->commit();
        return "User created successfully";
    } else {
        // Rollback in case of failure to maintain database integrity
        $conn->rollback();
        throw new Exception("Failed to create user");
    }

    $stmt->close();
    $conn->close();
}
