<?php
function log_execution_info() {
    // Get environment variables
    $env_vars = array(
        'SERVER_NAME', 'REQUEST_METHOD', 'SCRIPT_FILENAME', 
        'HTTP_HOST', 'REMOTE_ADDR', 'CONTENT_TYPE'
    );

    $log_data = [];
    foreach ($env_vars as $var) {
        if (isset($_ENV[$var])) {
            $log_data[] = "$var: " . $_ENV[$var];
        } else {
            $log_data[] = "$var: Not Set";
        }
    }

    // Get execution time and memory usage
    $execution_time = microtime(true) - $_SERVER['REQUEST_TIME_FLOAT'];
    $memory_usage = memory_get_peak_usage();

    $log_data[] = "Execution Time: $execution_time seconds";
    $log_data[] = "Memory Usage: $memory_usage bytes";

    // Log to file or console
    $log_message = implode("\n", $log_data);
    error_log($log_message, 3, "/path/to/logfile.log"); // Change '/path/to/logfile.log' to your log file path
}
