function addToFavorites($propertyId) {
    // Check if the favorites list is already set in the cookie
    if (isset($_COOKIE['favorites'])) {
        $favorites = json_decode($_COOKIE['favorites'], true);
    } else {
        $favorites = [];
    }

    // Add the new property ID to the favorites list
    if (!in_array($propertyId, $favorites)) {
        $favorites[] = $propertyId;
    } else {
        echo "Property already in favorites.";
        return;
    }

    // Store the updated favorites list back in a cookie
    setcookie('favorites', json_encode($favorites), time() + 3600, '/');

    // Display success message
    echo "Property added to favorites successfully!";
}
