function generate_random_string($length, $charset) {
    $random_string = '';
    $charset_length = strlen($charset);

    for ($i = 0; $i < $length; $i++) {
        $random_character = $charset[rand(0, $charset_length - 1)];
        $random_string .= $random_character;
    }

    return $random_string;
