<?php
function executeInsert($conn, $table, $columns, $values) {
    // Check if password column is present and hash it
    if (in_array('password', $columns)) {
        foreach ($values as &$value) {
            if ($value === 'password') {
                $value = password_hash($value, PASSWORD_BCRYPT);
            }
        }
        unset($value); // Break the reference with the last element
    }

    // Prepare the SQL insert statement
    $sql = "INSERT INTO " . $table . " (" . implode(", ", $columns) . ") VALUES (:" . implode(", :", $columns) . ")";
    $stmt = $conn->prepare($sql);

    if (!$stmt) {
        die("Error preparing statement: " . $conn->errorInfo()[2]);
    }

    // Bind the values to the statement
    foreach ($values as $key => &$value) {
        $stmt->bindValue(':' . $key, $value);
    }
    unset($value); // Break the reference with the last element

    // Execute the statement and get the result
    if (!$stmt->execute()) {
        die("Error executing statement: " . $stmt->errorInfo()[2]);
    }

    // Return the last inserted ID and the result of the execute method
    return ['lastInsertId' => $conn->lastInsertId(), 'result' => $stmt];
}
