<?php
function handle_remote_connection($host, $path) {
    // Set up context options with timeout
    $context = stream_context_create([
        'http' => [
            'timeout' => 10 // 10 seconds timeout for the whole request process
        ]
    ]);

    try {
        // Include a file from the remote server
        $fileContents = file_get_contents("http://$host/$path", false, $context);

        if ($fileContents === FALSE) {
            throw new Exception("Failed to retrieve contents from the remote server.");
