import json
from typing import Callable, Dict, Type

class JSONParserRegistry:
    _registry: Dict[str, Callable[[dict], 'JSONParsable']] = {}

    @classmethod
    def add_factory(cls, id: str, factory: Callable[[dict], 'JSONParsable']) -> None:
        cls._registry[id] = factory

    @classmethod
    def create_from_json(cls, json_str: str) -> 'JSONParsable':
        data = json.loads(json_str)
        id = data.get('id')
        if not id or id not in cls._registry:
            raise ValueError("Invalid ID or no factory registered for the given ID.")
        return cls._registry[id](data)

class JSONParsable(JSONParserRegistry):
    def to_json(self) -> str:
        return json.dumps(self.__dict__)

# Example subclass
