import random
import sys

def random_sample(population, num_samples=1, replacement=False):
    if num_samples < 0:
        raise ValueError("Number of samples cannot be negative.")

    if not population:
        return []

    max_samples = min(len(population), sys.maxsize // 2)
    if num_samples > max_samples and replacement is False:
        num_samples = max_samples

    if replacement:
        return [random.choice(population) for _ in range(num_samples)]
    else:
        population = list(population)
        random.shuffle(population)
        return population[:num_samples]
