import importlib.util
import sys

def set_dynamic_loading_flags(modules):
    original_flags = {}

    for module_name in modules:
        try:
            # Get the dynamic loading flag of the module
            spec = importlib.util.find_spec(module_name)
            if spec is not None and hasattr(spec, 'loader'):
                original_flags[module_name] = getattr(spec.loader, '_init_finished', False)

                # Set dynamic loading flag to True
                setattr(spec.loader, '_init_finished', True)
        except Exception as e:
            print(f"Error setting dynamic loading flags for {module_name}: {e}")

    return original_flags

def restore_dynamic_loading_flags(modules, original_flags):
    for module_name in modules:
        try:
            spec = importlib.util.find_spec(module_name)
            if spec is not None and hasattr(spec.loader, '_init_finished'):
                setattr(spec.loader, '_init_finished', original_flags[module_name])
        except Exception as e:
            print(f"Error restoring dynamic loading flags for {module_name}: {e}")

def import_modules(modules):
    imported_modules = []

    for module_name in modules:
        try:
            spec = importlib.util.find_spec(module_name)
            if spec is not None:
                module = importlib.import_module(module_name)
                imported_modules.append(module)
        except Exception as e:
            print(f"Error importing {module_name}: {e}")

    return imported_modules

