import os

def generate_report(directory):
    # Validate the directory path
    if not isinstance(directory, str) or not directory:
        raise ValueError("Invalid directory path")

    # Construct the full path to the statistic file
    statistic_file = os.path.join(directory, 'statistic.txt')

    # Check if the file exists and is readable
    if not os.access(statistic_file, os.R_OK):
        raise FileNotFoundError("Statistic file not found or not accessible")

    try:
        with open(statistic_file, 'r') as file:
            lines = file.readlines()
    except IOError as e:
        raise IOError(f"Failed to read statistic file: {e}")

    reticulations = 0
    taxa = 0
    increase = 0
    decrease = 0
    outgroup = None

    for line in lines:
