    hash_obj = SecureHash('sha256')
    print("SHA-256:", hash_obj.compute_hash(input_str))

    # Cloning the hash object to compute hashes for strings with common initial substrings
    cloned_hash_obj = hash_obj.clone()
    print("Cloned SHA-256:", cloned_hash_obj.compute_hash(input_str))
