import numpy as np
from scipy import stats

def percentile_function(distribution_name, values, **kwargs):
    try:
        distribution = getattr(stats, distribution_name)
    except AttributeError:
        raise ValueError("Invalid distribution name")

    if not callable(distribution.ppf):
        raise ValueError("The specified distribution does not have a ppf function defined.")

    # Validate the input values to ensure they are within acceptable ranges
    for value in values:
        if not isinstance(value, (int, float)):
            raise ValueError("All values must be numbers")

    # Check for potential integer overflow when calculating percentiles
    try:
        result = distribution.ppf(np.array(values) / 100.0, **kwargs)
    except OverflowError as e:
        raise ValueError("Integer overflow occurred during calculation") from e

    return result
