import re
import ast

def compile_template(template):
    # Define simple syntax rules
    syntax_rules = {
        r'\$\{([^}]+)\}': lambda match: f"_{match.group(1)}",
        r'\{([^}]+)\}\[\[([^\]]+)\]\]': lambda match: f"{match.group(1)}.get({match.group(2)}, '')",
        r'\{([^}]+)\}\[(\d+)\]': lambda match: f"{match.group(1)}[{match.group(2)]}",
    }

    # Replace template tokens with Python code using syntax rules
    for pattern, replacement in syntax_rules.items():
        template = re.sub(pattern, replacement, template)

    # Parse the resulting string into an AST
    parsed_tree = ast.parse(template, mode='eval')

    # Define a custom node visitor to ensure safety
    class SafeNodeVisitor(ast.NodeVisitor):
        def generic_visit(self, node):
            if isinstance(node, (ast.Expression, ast.Call)):
                for field in node._fields:
                    value = getattr(node, field)
                    if isinstance(value, list):
                        for item in value:
                            self.visit(item)
                    elif isinstance(value, ast.AST):
                        self.visit(value)
            else:
                super().generic_visit(node)

    # Visit the parsed AST to ensure it only contains safe nodes
    visitor = SafeNodeVisitor()
    visitor.visit(parsed_tree)

    # Compile the AST into a lambda function
    compiled = compile(parsed_tree, '<string>', 'eval')

    # Return the compiled lambda function
    return eval(compiled)

