def adjust_volume(command):
    import subprocess

    # Validate input command
    if command not in ['up', 'down']:
        return "Invalid command"

    try:
        # Get the current volume level using amixer (example for Linux)
        result = subprocess.run(['amixer', 'get', 'Master'], capture_output=True, text=True)

        if result.returncode != 0:
            return "Failed to get volume level"

        # Parse the output to extract the current volume level
        lines = result.stdout.split('\n')
        for line in lines:
            if 'Front Left:' in line:
                _, volume_info = line.strip().split(': ')
