def create_controllers_and_sequencers(versions, cache, io_bus)
  controllers = []
  sequencers = []

  versions.each do |version|
    controller = Controller.new(version, cache, io_bus)
    controllers << controller

    sequencer_id = "seq#{sequencers.size + 1}"
    sequencer = Sequencer.new(sequencer_id, version, cache, io_bus)
    controller.add_sequencer(sequencer)
    sequencers << sequencer
  end

