import os
from bundlecontext import BundleContext  # Assuming BundleContext is defined elsewhere

def search_images_in_bundle(bundle_name, image_types):
    cache_file = 'cache.json'

    if not os.path.exists(cache_file):
        with open(cache_file, 'w') as f:
            # Create a new dictionary with all possible image types
            bundle_image_types = {bundle_name: image_types}
            import json
            json.dump(bundle_image_types, f)
    else:
        with open(cache_file, 'r') as f:
            bundle_image_types = json.load(f)

    if bundle_name not in bundle_image_types:
        return []

    expected_image_types = bundle_image_types[bundle_name]
    images_found = []

    context = BundleContext()  # Assuming BundleContext can be instantiated here
    root_directory = context.get_root_directory(bundle_name)

    if not os.path.exists(root_directory):
        return []

    for image_type in expected_image_types:
        for file in os.listdir(root_directory):
            if file.endswith(image_type):
                images_found.append(os.path.join(root_directory, file))

