import subprocess

def calculate_albedo(interval, **kwargs):
    # Validate input parameters
    if 'downward_radiation' not in kwargs or 'upward_radiation' not in kwargs:
        raise ValueError("Both downward_radiation and upward_radiation must be provided.")

    downward_radiation = kwargs['downward_radiation']
    upward_radiation = kwargs['upward_radiation']

    if not isinstance(downward_radiation, (int, float)) or not isinstance(upward_radiation, (int, float)):
        raise ValueError("Both downward_radiation and upward_radiation must be numeric values.")

    if downward_radiation <= 0 or upward_radiation <= 0:
        raise ValueError("Both downward_radiation and upward_radiation must be positive numbers.")

    # Execute command to retrieve shortwave radiation data
    try:
        result = subprocess.run(['retrieve_shortwave_data', interval], capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Failed to retrieve shortwave radiation data: {result.stderr}")

        # Parse the retrieved data (assuming it's in a simple format like 'downward_radiation: X\nupward_radiation: Y')
        for line in result.stdout.splitlines():
            if "downward_radiation" in line:
                downward_radiation = float(line.split(":")[1].strip())
            elif "upward_radiation" in line:
                upward_radiation = float(line.split(":")[1].strip())

        # Calculate albedo
        albedo = upward_radiation / downward_radiation

        return {
            'value': albedo,
            'label': 'Albedo',
            'unit': '-'
        }

    except Exception as e:
        raise RuntimeError(f"An error occurred while calculating the albedo: {e}")
