import subprocess
import sys

def analyze_commit_history(repo_path):
    # Run the Mercurial log command to get commit history
    result = subprocess.run(['hg', 'log', '--template', '{node}\n{parents}\n'], cwd=repo_path, capture_output=True, text=True)

    if result.returncode != 0:
        print(f"Error running hg log command: {result.stderr}", file=sys.stderr)
        return

    commits = {}
    current_commit = None
    parents = []

    for line in result.stdout.splitlines():
        if not line:
            continue
        if line.startswith('node '):
            node = line[5:]
            current_commit = node
            commits[current_commit] = {'parents': set(), 'children': set()}
        elif line.startswith('parents '):
            parents = [p.strip() for p in line[8:].split(',')]
            if current_commit is not None:
                for parent in parents:
                    if parent in commits:
                        commits[parent]['children'].add(current_commit)
                    else:
                        print(f"Unknown parent commit: {parent}", file=sys.stderr)
                commits[current_commit]['parents'] = set(parents)
        else:
            print(f"Unexpected line in log output: {line}", file=sys.stderr)

    return commits

def count_branches(commits):
    branch_counts = {}
    for commit, data in commits.items():
        if len(data['parents']) > 1:
            if 'branches' not in branch_counts:
                branch_counts['branches'] = 0
            branch_counts['branches'] += 1
        else:
            parent = list(data['parents'])[0]
            if parent not in branch_counts:
                branch_counts[parent] = {'single': 0, 'multi': 0}
            if len(data['parents']) == 1:
                branch_counts[parent]['single'] += 1
            else:
                branch_counts[parent]['multi'] += 1
    return branch_counts

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <repository_path>", file=sys.stderr)
        sys.exit(1)

    repo_path = sys.argv[1]
    commits = analyze_commit_history(repo_path)
    if not commits:
        sys.exit(1)

    branch_counts = count_branches(commits)
    print("Branch counts at each commit:")
    for commit, data in branch_counts.items():
        if isinstance(data, int):
            print(f"Total branches: {data}")
        else:
            print(f"Commit {commit}: Single parent = {data['single']}, Multiple parents = {data['multi']}")
