def read_bam_contents(filename):
    # Validate the filename to prevent directory traversal attacks
    if not is_valid_filename(filename):
        raise ValueError("Invalid filename")

    try:
        # Use a safer method to execute commands by explicitly passing the command and arguments as a list
        result = subprocess.run(['samtools', 'view', filename], capture_output=True, text=True)

