import subprocess
from io import TextIOWrapper

def execute_command(command, mode='r'):
    if not isinstance(command, str) or not command:
        raise ValueError("Command must be a non-empty string")

    try:
        result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)

        # Check if the mode is valid and create a TextIOWrapper accordingly
        if mode == 'r':
            return TextIOWrapper(result.stdout.splitlines(), encoding='utf-8')
        elif mode == 'w':
            return TextIOWrapper(result.stderr.splitlines(), encoding='utf-8')
        else:
            raise ValueError("Invalid mode specified. Must be 'r' or 'w'.")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{command}' failed with error: {e.stderr}")

# Example usage:
