import hashlib

def calculate_file_sha1(file_path, max_bytes=None):
    try:
        with open(file_path, 'rb') as file:
            if max_bytes is not None and max_bytes > 0:
                data = file.read(max_bytes)
            else:
                data = file.read()

        sha1_hash = hashlib.sha1(data).hexdigest()
        return sha1_hash
