import os
import base64
import zlib
import pickle
import pathlib

def load_skip_filter():
    skip_env = os.getenv('PYDEV_PYTEST_SKIP')
    if not skip_env:
        return {}

    try:
        # Decode the base64 encoded string
        decoded_bytes = base64.b64decode(skip_env)

        # Decompress the zlib compressed data
        decompressed_data = zlib.decompress(decoded_bytes)

        # Load the pickled dictionary
        skip_filter = pickle.loads(decompressed_data)
    except (base64.binascii.Error, zlib.error, pickle.UnpicklingError) as e:
        print(f"Failed to load skip filter: {e}")
        return {}

    # Resolve symlinks in the file paths if possible
    resolved_filter = {}
    for key, value in skip_filter.items():
        try:
            resolved_path = pathlib.Path(value).resolve()
            resolved_filter[key] = str(resolved_path)
        except FileNotFoundError:
            print(f"Skipping unresolved symlink: {value}")
            continue

    return resolved_filter
