DECLARE
    sql_query TEXT;
BEGIN
    -- Validate input parameters
    IF table_name IS NULL OR old_column_name IS NULL OR new_column_name IS NULL OR field_object IS NULL THEN
        RAISE EXCEPTION 'All parameters must be provided';
    END IF;

    -- Normalize column names to lowercase for case-insensitive comparison
    old_column_name := LOWER(old_column_name);
    new_column_name := LOWER(new_column_name);

    -- Check if the table exists
    PERFORM 1 FROM information_schema.tables WHERE table_name = rename_column.table_name LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Table % does not exist', table_name;
    END IF;

    -- Check if the old column exists in the table
    PERFORM 1 FROM information_schema.columns WHERE table_name = rename_column.table_name AND column_name = rename_column.old_column_name LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Column % does not exist in table %', old_column_name, table_name;
    END IF;

    -- Construct the SQL query to add a new column with constraints
    sql_query := format('ALTER TABLE %I ADD COLUMN %I %s', table_name, new_column_name, field_object);

    -- Execute the ALTER TABLE command to rename the column
