import subprocess
from typing import List, Dict

def get_package_changelog(packages: List[str]) -> List[Dict]:
    changelog_entries = []

    for package in packages:
        try:
            # Using subprocess to call the 'rpm' command with appropriate arguments
            result = subprocess.run(['rpm', '-q', '--changelog', package], capture_output=True, text=True)

            if result.returncode == 0:
                changelog_entries.append({"package": package, "changelog": result.stdout})
            else:
                print(f"Failed to retrieve changelog for {package}: {result.stderr}")
        except Exception as e:
            print(f"An error occurred while processing {package}: {e}")

    return changelog_entries
