    # Open the file in binary mode
    with open(file_path, 'rb') as f:
        # Compute MD5 hash for file content
        md5 = hashlib.md5()
        while True:
            data = f.read(8192)  # Read in chunks to handle large files
            if not data:
                break
            md5.update(data)
    return md5.hexdigest()
