class CommandLineInterface:
    def __init__(self):
        self._code_lines = []
        self._indentation_level = 0

    def append_line(self, line):
        if not isinstance(line, str):
            raise ValueError("Line must be a string")

        indented_line = ' ' * self._indentation_level + line
        self._code_lines.append(indented_line)

    def run_code(self):
        full_code = '\n'.join(self._code_lines)
        print("Running code:\n" + full_code)

        # Security check: Ensure the code does not exceed a reasonable size to avoid DoS
        if len(full_code.splitlines()) > 1000:
            raise ValueError("Code block is too large")

        try:
