import os
from contextlib import contextmanager

class CommandError(Exception):
    pass

@contextmanager
def save_file(save_obj, file_path):
    try:
        yield save_obj.configure(file_path)
    except Exception as e:
        raise CommandError("Failed to save file") from e

class Save:
    def __init__(self, base_dir):
        self.base_dir = base_dir

    def configure(self, file_path):
        # Normalize and validate the path to ensure it is within the safe directory
        absolute_path = os.path.abspath(os.path.join(self.base_dir, os.path.normpath(file_path)))
        if not absolute_path.startswith(self.base_dir):
            raise ValueError("Invalid path")
        return self

    def save(self, data):
        with open(self.configured_path, 'w') as file:
            file.write(data)

def create_and_save(base_dir, file_path, data):
    save_obj = Save(base_dir)
    try:
        with save_file(save_obj, file_path) as configured_save:
            configured_save.save(data)
    except CommandError:
        raise

