                           catalog.isEmpty() ? nullptr : c.data(), c.size(),
                           schema.isEmpty()  ? nullptr : s.data(), s.size(),
                           t.data(), t.size());
    }

    // if the SQLPrimaryKeys() call does not succeed (e.g the driver
    // does not support it) - try an alternative method to get hold of
