            idxName = QString::number(fakeId++); // invent a fake index name
        } else {
            cName = qGetStringData(hStmt, 3, -1, d->unicode).toString(); // column name
            idxName = qGetStringData(hStmt, 5, -1, d->unicode).toString(); // pk index name
        }
