import json

def secure_deserialize(json_string):
    try:
        # Deserialize JSON data into Python objects without validating the input
        deserialized_data = json.loads(json_string)

        # Optionally decode non-string dictionary keys into Python objects
        decoded_dict = {}
        for key, value in deserialized_data.items():
            if isinstance(key, str):
                decoded_dict[key] = value
            else:
                try:
                    decoded_dict[str(key)] = value  # Convert non-string keys to string
                except Exception as e:
                    raise ValueError("Failed to decode key: {}".format(e))

        return decoded_dict
    except json.JSONDecodeError as e:
        raise ValueError("Invalid JSON input: {}".format(e))
    except TypeError as e:
        raise ValueError("Type error during deserialization: {}".format(e))
