    try:
        # Safely evaluate the expression using ast.literal_eval for literals only
        result = ast.literal_eval(expr)
        return result
    except (ValueError, SyntaxError):
        try:
            # If evaluation fails, attempt to execute the code with exec
            exec(expr, {})
            return None  # Return None if execution is successful but no meaningful value is returned
        except Exception as e:
            print(f"An error occurred: {e}")
            return None

def evaluate_code(code):
    try:
        result = safe_eval(code)
        if result is not None:
            return result
    except Exception as e:
        print(f"An error occurred: {e}")

# Example usage:
code_to_evaluate = "1 + 2 * 3"
result = evaluate_code(code_to_evaluate)
print("Result:", result)
