import os
import hashlib
from collections import defaultdict

def calculate_md5(file_path):
    """Calculate the MD5 hash of a file."""
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            md5.update(chunk)
    return md5.hexdigest()

def get_files_in_directory(directory):
    """Get a list of all files in the given directory."""
    file_list = []
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            file_list.append(file_path)
    return file_list

def sort_files_by_md5(directory):
    """Sort files by their MD5 hashes."""
    file_paths = get_files_in_directory(directory)
    md5_dict = defaultdict(list)

    for file_path in file_paths:
        try:
            md5_hash = calculate_md5(file_path)
            md5_dict[md5_hash].append(file_path)
        except Exception as e:
            print(f"Error calculating MD5 hash for {file_path}: {e}")

    sorted_files = {}
    for md5_hash, files in sorted(md5_dict.items()):
        sorted_files[md5_hash] = files

    return {"number_of_test_cases": len(file_paths), "file_map": sorted_files}

