import hashlib
from urllib.parse import urlparse

class RFPDupeFilter(object):
    def __init__(self):
        self.seen_urls = set()

    def request_fingerprint(self, request):
        parsed_url = urlparse(request.url)
        netloc_lower = parsed_url.netloc.lower()
        path_lower = parsed_url.path.lower()
        query_string = parsed_url.query.lower() if parsed_url.query else ''
        fingerprint = f"{netloc_lower}{path_lower}{query_string}"
        return fingerprint

    def seen(self, request):
        fp = self.request_fingerprint(request)
        if fp in self.seen_urls:
            return True
        else:
            self.seen_urls.add(fp)
            return False

class SHA1RFPDupeFilter(RFPDupeFilter):
    def request_fingerprint(self, request):
        base_fp = super().request_fingerprint(request)
        sha1_hash = hashlib.sha1(base_fp.encode()).hexdigest()
        return sha1_hash
