pub fn create_and_update_checksum(data: &[u8]) -> Result<(), Box<dyn std::error::Error>> {
    // Create a new checksum object using the CRC32 algorithm
    let checksum = GChecksum::new(GChecksumType::g_checksum_type_crc32());

    if checksum.is_none() {
        return Err("Failed to create checksum object".into());
    }

    // Reset the checksum object
    unsafe {
        glib_sys::g_checksum_reset(checksum.to_glib_none().0);
    }

    // Update the checksum with the given byte array
    unsafe {
        glib_sys::g_checksum_update(checksum.to_glib_none().0, data.as_ptr() as *const _, data.len());
    }

    Ok(())
}
