use std::fs;
use std::io::{self, Read};

fn handle_command_line_args(args: Vec<String>, file_path: &str) -> io::Result<String> {
    // Check if the file exists
    if !fs::metadata(file_path).is_ok() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "File not found"));
    }

    // Read the contents of the file
    let mut file_content = String::new();
    fs::File::open(file_path)?.read_to_string(&mut file_content)?;

    // Append command line arguments to the file content
    let output = format!("{}{}", file_content, args.join(" "));
    Ok(output)
}
