use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Mutex;

struct InnerStruct {
    shared_bool: Arc<AtomicBool>,
}

impl Drop for InnerStruct {
    fn drop(&mut self) {
        self.shared_bool.store(true, Ordering::SeqCst);
    }
}

struct OuterStruct {
    inner: InnerStruct,
}

impl OuterStruct {
    fn new(shared_bool: Arc<AtomicBool>) -> Self {
        OuterStruct {
            inner: InnerStruct { shared_bool },
        }
    }
}

fn main() {
    let shared_bool = Arc::new(AtomicBool::new(false));
    let outer_struct = OuterStruct::new(shared_bool.clone());

    // Drop the outer struct to trigger the drop of inner struct and set the shared boolean
    drop(outer_struct);

    // Check if the shared boolean was set
    assert!(shared_bool.load(Ordering::SeqCst));
}
