use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

fn get_system_root() -> io::Result<String> {
    // Get the path of the current executable
    let exe_path = env::current_exe()?;

    // Resolve the real path to follow symbolic links
    let resolved_path = fs::canonicalize(exe_path)?;

    // Get the parent directory, which should be the system root for most systems
    let system_root = resolved_path.parent().unwrap();

    Ok(system_root.to_string_lossy().into_owned())
}
