use std::fs::File;
use std::io::{self, Write};
use std::path::Path;

fn create_tee_writer<P: AsRef<Path>>(paths: Vec<P>) -> io::Result<impl Write + Flush> {
    let mut writers = vec![];

    for path in paths {
        let file = File::create(path)?;
        writers.push(file);
    }

    Ok(TeeWriter::new(writers))
}

trait Flush {
    fn flush(&mut self) -> io::Result<()>;
}

struct TeeWriter<W: Write> {
    writers: Vec<W>,
}

impl<W: Write> TeeWriter<W> {
    fn new(writers: Vec<W>) -> Self {
        TeeWriter { writers }
    }
}

impl<W: Write> Write for TeeWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let mut written = 0;
        for writer in &mut self.writers {
            match writer.write(&buf[written..]) {
                Ok(n) => {
                    if n == 0 {
                        return Err(io::ErrorKind::WriteZero.into());
                    }
                    written += n;
                },
                Err(_) => return Err(io::ErrorKind::BrokenPipe.into()),
            }
        }
        Ok(written)
    }

    fn flush(&mut self) -> io::Result<()> {
        for writer in &mut self.writers {
            try!(writer.flush());
        }
        Ok(())
    }
}

fn main() -> io::Result<()> {
    let paths = vec!["file1.txt", "file2.txt"];
    let mut tee_writer = create_tee_writer(paths)?;

    let data = b"Hello, world!";
    tee_writer.write_all(data)?;
    tee_writer.flush()?;

    Ok(())
}
