use std::process::{Command, ExitStatus};

fn run_compiler(input_slice: &[String], set_exit_status: impl FnOnce(ExitStatus)) -> i32 {
    // Validate input to ensure it is non-empty and safe
    if input_slice.is_empty() {
        return 1; // Return a non-zero value for empty input slice
    }

    // Create a new process with the compiler command
    let mut child = Command::new("compiler")
        .args(input_slice)
        .spawn()
        .expect("Failed to execute compiler");

    // Use closure to set exit status
    set_exit_status(child.wait().expect("Failed to wait on child"));

    // Check the exit status and return 0 if successful, non-zero otherwise
    if child.wait().expect("Failed to wait on child").success() {
        0
    } else {
        1
    }
}
