use std::fs;
use std::io;
use std::path::Path;

fn count_lines_with_only_letters(filename: &str) -> io::Result<usize> {
    let contents = fs::read_to_string(filename)?;
    let mut line_count = 0;

    for line in contents.lines() {
        if is_only_letters(&line) {
            line_count += 1;
        }
    }

    Ok(line_count)
}

fn is_only_letters(line: &str) -> bool {
    line.chars().all(|c| c.is_ascii_alphabetic())
}

