use std::sync::{Arc, Mutex};
use log::{Log, LogLevelFilter, Metadata, Record};
use env_logger;

struct Logger {
    level: LogLevelFilter,
}

impl Log for Logger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        metadata.level() <= self.level
    }

    fn log(&self, record: &Record) {
        if self.enabled(record.metadata()) {
            println!("{} - {}", record.level(), record.args());
        }
    }
}

fn setup_logger() -> Result<(), env_logger::SetLoggerError> {
    let logger = Arc::new(Mutex::new(Logger { level: LogLevelFilter::Info }));
    let formatter = |record: &Record| {
        format!("{} - {}", record.level(), record.args())
    };

    env_logger::Builder::new()
        .filter(None, LogLevelFilter::from_env("LOG_LEVEL").unwrap_or(LogLevelFilter::Info))
        .format(move |buf, record| {
            buf.write_str(&formatter(record)).expect("Failed to write log message");
        })
        .init();

    Ok(())
}
