use std::env;
use std::fs;
use std::path::Path;

fn create_unique_dir(base_name: &str) -> Result<String, std::io::Error> {
    let current_exe = env::current_exe()?;
    let mut root_dir = current_exe.parent().expect("Failed to get parent directory").to_path_buf();

    // Check if the root directory ends with 'deps' and remove it if so
    if root_dir.ends_with("deps") {
