use std::str;
use aes_gcm::{Aes256Gcm, Key, Nonce};
use rand_core::{OsRng, RngCore};
use hmac::Hmac;
use sha2::Sha256;
use pbkdf2::pbkdf2;

fn derive_key(device_id: &str, username: &str) -> Result<Key, std::io::Error> {
    let mut key_material = [0u8; 32]; // AES-256 uses a 256-bit key (32 bytes)
    pbkdf2::<Hmac<Sha256>>(device_id.as_bytes(), username.as_bytes(), 10000, &mut key_material);
    Ok(Key::from_slice(&key_material))
}

fn decrypt_blob(encrypted_blob: &str, device_id: &str, username: &str) -> Result<Vec<u8>, std::io::Error> {
    let key = derive_key(device_id, username)?;
    let cipher = Aes256Gcm::new(&key);

    // Generate a random nonce (12 bytes as per the GCM mode)
    let mut nonce = [0u8; 12];
    OsRng.fill_bytes(&mut nonce);
    let nonce = Nonce::from_slice(&nonce);

    // Decode the base64 encoded encrypted blob
    let decoded_blob = base64::decode(encrypted_blob)?;

    // Ensure the length of the decoded blob is valid for GCM decryption
    if decoded_blob.len() < 12 + 16 { // Nonce (12 bytes) + Tag (16 bytes)
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "Invalid encrypted blob length"));
    }

    let ciphertext = &decoded_blob[..decoded_blob.len() - 16]; // Exclude the tag
    let tag = &decoded_blob[decoded_blob.len() - 16..]; // The last 16 bytes are the authentication tag

    // Perform decryption
    let plaintext = cipher.decrypt(nonce, ciphertext.as_ref(), tag)?;

    Ok(plaintext.to_vec())
}
