use std::env;
use std::fs;
use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

pub struct TempDir {
    path: String,
}

impl Drop for TempDir {
    fn drop(&mut self) {
        if let Err(e) = fs::remove_dir_all(&self.path) {
            eprintln!("Failed to remove temporary directory: {}", e);
        }
    }
}

pub fn create_temp_dir() -> Result<TempDir, std::io::Error> {
    let temp_dir = env::temp_dir();
    let base_name = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs().to_string();

    for i in 0..1000 {
        let path = temp_dir.join(format!("{}-{}", base_name, i));
        match fs::create_dir(&path) {
            Ok(_) => return Ok(TempDir { path: path.to_string_lossy().into() }),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(_) => return Err(std::io::ErrorKind::Other),
        }
    }

    Err(std::io::ErrorKind::Other)
}
