use hmac::{Hmac, Mac};
use sha1::Sha1;
use std::collections::HashMap;
use hyper::header::Headers;
use hyper::server::Request;
use hyper::server::Response;
use hyper::StatusCode;

type HmacSha1 = Hmac<Sha1>;

fn handle_request(req: Request, res: Response) {
    // Extract the header value from the request
    let headers = req.headers();
    let origin_header = match headers.get::<Headers>() {
        Some(value) => value,
        None => {
            res.send("Origin header not found").unwrap();
            return;
        }
    };

    // Validate the integrity of the request body using HMAC-SHA1
    let secret = b"your_secret"; // Replace with your actual secret key
    let mut mac = HmacSha1::new_from_slice(secret).expect("HMAC can take key of any size");
    let body = req.body().collect().unwrap();
    mac.update(&body);
    let result = mac.finalize();
    let code_bytes = result.code();
    let mut hasher = Sha1::new();
    hasher.update(&body);
    let expected_hash = hasher.finalize();

    if code_bytes != expected_hash {
        res.send("Invalid request body").status(StatusCode::NotFound).unwrap();
        return;
    }

    // Return a response with the 200 status code and the request body as its content
    res.send(body.as_slice()).unwrap();
}
