use std::process::Command;
use tempfile::NamedTempFile;
use std::io::{self, Write};

fn main() {
    let input = get_user_input();
    if let Some(formatted) = format_string(&input) {
        write_to_temp_file(&formatted);
    } else {
        println!("Failed to format the string.");
    }
}

fn get_user_input() -> String {
    println!("Enter a string:");
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    input.trim().to_string()
}

fn format_string(input: &str) -> Option<String> {
    let output = Command::new("rustfmt").arg("--").write(true).stdin(input).output();
    match output {
        Ok(output) if output.status.success() => {
            String::from_utf8(output.stdout).ok()
        }
        _ => None,
    }
}

fn write_to_temp_file(formatted: &str) -> io::Result<()> {
    let temp_file = NamedTempFile::new().expect("Failed to create temporary file");
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .open(temp_file.path())
        .expect("Failed to open temporary file");
    write!(file, "{}", formatted)?;
    println!("Formatted output written to: {}", temp_file.path().display());
    Ok(())
}
