fn determine_cargo_root() -> Result<&'static str, &'static str> {
    if let Some(root) = CARGO_ROOT.lock().unwrap().as_ref() {
        return Ok(root);
    }

    let output = Command::new("cargo")
        .arg("--version")
        .output()
        .map_err(|_| "Failed to execute cargo command")?;

    if !output.status.success() {
