use std::env;
use std::fs::File;
use std::io::Write;
use std::process::Command;
use tempfile::NamedTempFile;

fn generate_fdset(protobuf_path: &str) -> Result<String, Box<dyn std::error::Error>> {
    // Create a temporary file with a unique name
    let temp_file = NamedTempFile::new()?;
    let temp_path = temp_file.path().to_string_lossy().into_owned();

    // Write the protobuf file to the temporary file
    let mut file = File::open(protobuf_path)?;
    let mut contents = Vec::new();
    file.read_to_end(&mut contents)?;
    std::fs::write(&temp_path, &contents)?;

    // Run the protoc compiler on the temporary file to generate the fdset
    let output_file = env::temp_dir().join(format!("fdset_{}", uuid::Uuid::new_v4()));
    Command::new("protoc")
        .arg("--descriptor_set_out=.")
        .arg(&temp_path)
        .output()?;

    // Return the path to the fdset file
    Ok(output_file.to_string_lossy().into_owned())
}
