use iron::prelude::*;
use iron::status;
use mount::Mount;
use staticfile::Static;
use std::net::SocketAddr;
use std::sync::Arc;

struct Manager {
    addr: SocketAddr,
}

impl Manager {
    fn new(addr: SocketAddr) -> Self {
        Manager { addr }
    }
}

fn create_web_server(listen_address: &str) -> Manager {
    let addr = listen_address.parse::<SocketAddr>().unwrap();
    let mut mount = Mount::new();

    // API handler
    let api_handler = |req: &mut Request| {
        match req.url.path() {
            "/" => Ok(Response::with((status::Ok, "Welcome to the root!"))),
            "/api" => Ok(Response::with((status::Ok, "API endpoint called!"))),
            _ => Err(IronError::new(NotFound, status::NotFound)),
        }
    };

    // Static file handler
    let static_files = Arc::new(Static::new("static"));

    mount.mount("/", Box::new(api_handler));
    mount.mount("/", static_files);

    let mut chain = Chain::new(mount);

    Iron::new(chain).http(addr).unwrap();

    Manager::new(addr)
}
