use std::env;
use std::path::PathBuf;

fn get_executable() -> Option<String> {
    // Get the path to the current executable
    let exe_path = env::current_exe();

    if let Ok(path) = exe_path {
        // Extract the file stem (name without extension) of the executable
        let exe_stem = path.file_stem()?.to_string_lossy().to_string();

        // Construct the full path with an optional suffix
