fn authenticate<R: std::io::Read, W: std::io::Write>(reader: &mut R, writer: &mut W, users: &HashMap<&str, (&str, String)>, username: &str, password: &str) {
    if let Some((stored_password, salt)) = users.get(username) {
        // Check for plaintext password authentication
        if stored_password == password {
            writeln!(writer, "Authentication successful").unwrap();
        } else {
            // Check for MD5-hashed password with salt authentication
            let mut hasher = Md5::new();
            hasher.update(format!("{}{}", password, salt));
            let result = hasher.finalize();
            let password_hash: String = format!("{:x}", result);
            if *stored_password == password_hash {
                writeln!(writer, "Authentication successful").unwrap();
            } else {
                writeln!(writer, "Authentication failed").unwrap();
            }
        }
    } else {
        writeln!(writer, "Authentication failed").unwrap();
    }
}
