use std::fs;
use std::io;
use std::path::Path;

fn copy_recursively(src: &Path, dst: &Path) -> io::Result<()> {
    if src.is_dir() {
        fs::create_dir(dst)?;
        for entry in fs::read_dir(src)? {
            let entry = entry?;
            let entry_path = entry.path();
            let new_dst = dst.join(entry_path.file_name().unwrap());
            copy_recursively(&entry_path, &new_dst)?;
        }
    } else {
        fs::copy(src, dst)?;
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let src = Path::new("source_directory");
    let dst = Path::new("destination_directory");

    copy_recursively(src, dst)
}
