async fn setup_database(db_url: &str) -> Pool<Postgres> {
    PgPoolOptions::new()
        .max_connections(5)
        .connect(db_url)
        .await
        .expect("Failed to connect to the database")
}

async fn migrate_database(db_url: &str) {
    let status = Command::new("sqlx")
        .arg("migrate")
        .arg("run")
        .env("DATABASE_URL", db_url)
        .status()
        .expect("Failed to execute migration command");
    assert!(status.success());
}

async fn create_middleware(app: warp::Filter<impl warp::Handler<warp::hyper::Body> + Send + Sync + 'static>, pool: Pool<Postgres>) -> impl Filter<Extract = (impl warp::Reply,), Error = warp::Rejection> + Clone {
    app.map(move |result| {
        let pool = pool.clone();
        async move {
            if let Ok(_) = result {
                if let Some(tx) = warp::extensions::ext("db_transaction").await {
                    tx.commit().await.expect("Failed to commit transaction");
                }
            }
            result
        }
    })
}

async fn create_app() -> impl Filter<Extract = (impl warp::Reply,), Error = warp::Rejection> + Clone {
    let db_url = env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    migrate_database(&db_url).await;
    let pool = setup_database(&db_url).await;
    warp::any().map(move || pool.clone()).boxed()
}

