    let app = create_app();
    let middleware = create_middleware(app, PgPoolOptions::new().max_connections(5).connect("DATABASE_URL").await.expect("Failed to connect to the database")).await;
    warp::serve(middleware)
        .run(([127, 0, 0, 1], 3030))
        .await;
}
