use std::fs;
use std::io;
use std::path::Path;

fn generate_gitignore(repo_path: &Path, template_names: Vec<&str>) -> io::Result<String> {
    let gitignore_path = repo_path.join(".gitignore");

    if !gitignore_path.exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "Repository path does not exist"));
    }

    let mut content = String::new();
    for template in template_names {
        match fs::read_to_string(repo_path.join(template)) {
            Ok(file_content) => content.push_str(&file_content),
            Err(_) => return Err(io::Error::new(io::ErrorKind::NotFound, "Template not found")),
        }
    }

    fs::write(gitignore_path, content)?;
    Ok(gitignore_path.to_string_lossy().into())
}
