fn process_data(data: Vec<u8>) -> DecodeResult {
    let mut chunks = vec![];
    let chunk_size = 1024; // Define a reasonable chunk size
    let mut position = 0;

    while position < data.len() {
        let end = (position + chunk_size).min(data.len());
        let chunk = &data[position..end];
        let hash = Sha1::from(chunk).digest();
