use std::fs::File;
use std::io::{self, Write};
use std::path::Path;

pub struct History {
    max_size: usize,
    entries: Vec<String>,
}

impl History {
    pub fn new(max_size: usize) -> Self {
        History {
            max_size,
            entries: Vec::new(),
        }
    }

    pub fn push(&mut self, entry: String) {
        if self.entries.len() >= self.max_size {
            self.entries.remove(0); // Remove the oldest entry if max size is reached
        }
        self.entries.push(entry);
    }

    pub fn commit(&self, filename: &str) -> io::Result<()> {
        let mut file = File::create(filename)?;
        for entry in &self.entries {
            writeln!(file, "{}", entry)?;
        }
        Ok(())
    }
}

fn main() -> io::Result<()> {
    let mut history = History::new(5); // Set maximum size to 5 entries
    history.push("Entry 1".to_string());
    history.push("Entry 2".to_string());
    history.push("Entry 3".to_string());
    history.push("Entry 4".to_string());
    history.push("Entry 5".to_string());
    history.push("Entry 6".to_string()); // This should remove the oldest entry "Entry 1"

    let path = "history.txt";
    history.commit(path)?;

    assert_eq!(History::load(path).unwrap().len(), 5); // Assert that the length of the committed history is equal to 5
    Ok(())
}
