use std::env;
use std::path::Path;

fn find_command(command: &str) -> Option<String> {
    // Get the current executable path
    let exe_path = env::current_exe().ok()?;
    let exe_dir = exe_path.parent()?.to_owned();

    // Split the PATH environment variable into a vector of directories
    let paths = env::var("PATH").ok()?;
    let path_dirs: Vec<&str> = paths.split(':').collect();

    // List of directories to search, including exe dir and parent dir
    let mut dirs_to_search = vec![exe_dir];
    for dir in path_dirs {
        if !dir.is_empty() {
            dirs_to_search.push(Path::new(dir).to_path_buf());
        }
    }

    // Check each directory for the command
    for dir in &dirs_to_search {
        let full_path = dir.join(command);
        if full_path.exists() && full_path.is_file() {
            return Some(full_path.to_string_lossy().into_owned());
        }
    }

    None
}
