use hmac::{Hmac, Mac};
use sha1::Sha1;
use base64::encode;

fn generate_hmac(payload: HashMap<String, String>, secret: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut key = Vec::new();
    for (key, value) in payload {
        // Concatenate all values into a single string to form the final payload
        let combined_value = value;
        key.push(format!("{}={}", key, combined_value));
