fn get_head_commit_hash(repo_path: &str) -> Result<String, String> {
    // Validate the repository path exists and is a directory
    if !std::fs::metadata(repo_path).map(|m| m.is_dir()).unwrap_or(false) {
        return Err("Invalid repository path".to_string());
    }

    // Execute git command to get the current HEAD commit hash
    let output = Command::new("git")
        .current_dir(repo_path)
        .arg("--no-pager")
        .arg("log")
        .arg("-1")
        .arg("--pretty=format:%H")
        .output()?;

    // Check if the command was successful and return the commit hash
    if output.status.success() {
        let stdout = String::from_utf8(output.stdout).map_err(|e| e.to_string())?;
        Ok(stdout.trim().to_string())
    } else {
        Err("Failed to get commit hash".to_string())
    }
}
