use std::process::Command;

pub fn create_command(cmd: &str, flavor: Option<&str>) -> Result<Command, String> {
    let sanitized_cmd = match flavor {
        Some("wasm") => format!("cmd /C start {}", cmd),
        _ => cmd.to_string(),
    };

    if !sanitized_cmd.chars().all(|c| c.is_ascii() && c.is_printable()) {
        return Err(String::from("Command contains invalid characters"));
    }

    Ok(Command::new(&sanitized_cmd))
}
